window.__D("tolt-7",[[109,"ביאור על הנ\"ל"],[109,"<b>הנה<\/b> כתיב ועמך כולם צדיקים. והנה יוסף נק' צדיק עליון ובנימין נק' צדיק תחתון. ויש נשמות שהם מבחי' יוסף. ויש מבחי' בנימין. ולכן נאמר ועמך כולם צדיקים. ופי' צדיק עליון היינו המקשר אצי' בבריאה כי כל בשמים ובארץ דאחיד בשמיא וארעא. כי הנה יעקב נק' בריח התיכון המבריח מן הקצה אל הקצה היינו להיות ההמשכה מאא\"ס עד מקור דבי\"ע שהוא בחי' הדבור עליון שהמשכה זו היא ע\"י יעקב שהוא כללות המדות עליונות."],[109,"וכמו עד\"מ שע\"י המדות נמשך ההשפעה שכשיש לו אהבה מדבר כו'. אך אלה תולדות יעקב הוא בחי' יוסף שהוא בחי' יסוד התקשרות של המשפיע עם המקבל וזהו בחי' צ\"ע. אך בכדי שיהיה המקבל קולט את ההשפעה צ\"ל ג\"כ בבחי' התקשרות שהוא בעבודת ה' בחי' מס\"נ והוא בחי' בנימין צ\"ת שמקשר בריאה באצי' מלמטה למעלה. ולכן נאמר בלידת בנימין ותקש בלדתה. כי בנימין הוא ההתכללות והבטול מבי\"ע לאצי' שזהו הפך ענין הלידה והגילוי מלמעלה למטה."],[109,"והנה במצות מעשיות יש ג\"כ שני הבחי' יש מצות שהן בחי' המשכת האור מלמעלה למטה כמו שופר לולב סוכה ציצית ותפלין ויש שהן בחי' העלאות כמו קרבנות וראשית הגז כו'. וז\"ש ורב שלום בניך. שלום הוא בחי' התקשרות והתחברות משפיע ומקבל. ויש ב' בחי' שלום מלמעלה למטה ע\"י יוסף. ומלמטה למעלה ע\"י בנימין. אך הבחי' שע\"י יוסף נק' ורב שלום כו'. וזהו ג\"כ ענין כרוב א' מקצה מזה הוא בחי' יוסף שממשיך מלמעלה למטה מאא\"ס לבחי' הדבור כו'. וז\"ש ביוסף והוא נער כו' שהוא בחי' כרוב כרביא. (וז\"ש בזוהר פ' וישב )(בדף קפ\"ד) מי יתנך כאח לי כו'. כיוסף על אחוי כו'. וכרוב א' מקצה מזה הוא בחי' בנימין שהוא התקשרות המקבל מלמטה למעלה. ופניהם איש אל אחיו התחברות שניהם כו'. אך משחרב בהמ\"ק מבקשת כנ\"י מי יתנך כאח לי. והיינו ע\"י יונק שדי אמי עסק התושבע\"פ כו' וכנ\"ל. אך זהו ע\"י הנשמות ששרשן מבחי' יוסף צ\"ע כו' שנק' אחים למקום."],[109,"והנה המשכה זו עיקרה הוא בפנימיות העולמות כיון שעיקר ההמשכה ע\"י מחשבה ודבור בעסק התורה אך כדי שיהיה ההמשכה גם בחיצוניות העולמות ע\"ז נאמר אמצאך בחוץ. והוא ע\"י נשמות שמבחי' בנימין שרוב עסקיהם במעשה דוקא בצדקה וגמ\"ח שעי\"ז נמשך גם בעוה\"ז השפל. (ע' באגה\"ק ד\"ה ויעש דוד שם):"],[109,"<b>והנה<\/b> פי' אשקך נשיקין אתדבקות רוחא ברוחא. הענין דכמו עד\"מ הנשיקים גשמיים באדם שהם באים ונמשכים מחמת פנימית אהבה שבלב שאינה מתלבשת בשום כלי כו' (שאותיות הדבור שהם בחי' כלים להמדות אין יכולים להכיל אהבה רבה זו לכך אינה מתלבשת בדבור רק בבחי' נשיקין) כך ענין ההמשכה זו שע\"י קיום המצות מעשיות דנשמות שמבחי' בנימין ממשיכים מבחי' עקודים שהוא למעלה מבחי' ההתלבשות בכלים כי רק באצי' שייך בחי' כלים אלא דאיהו וגרמוהי חד כו' משא\"כ בבחי' עקודים. והיינו משום שעל ידי ההעלאות דבנימין מבירורים דעולם התהו ששם ג\"כ האורות למעלה מההתלבשות בכלים אלא ששם היה שבה\"כ. משא\"כ בעולם העקודים כו'. ועל ידי בירורים הנ\"ל ממשיכים מבחי' העקודים. וזהו בחי' הנשיקין שהוא בחי' שלמעלה מהדבור כו'. (ועמ\"ש גבי קי\"ס בענין ואתם תחרישון כו' כי הדבור שרשו מחכמה כו' ע\"ש בפ' בשלח בד\"ה וה' הולך לפניהם כו' ומשם יובן יותר מ\"ש):"],[109,"⟦פא,א⟧<b>וז\"ש<\/b> אנהגך אביאך אל בית אמי. כי כאן ההמשכה גבוה מבחי' אימא עלאה רק שאח\"כ מתלבשת באימא. משא\"כ לעיל אמר יונק שדי אמי. וגם כאן אמר תלמדני שנעשים בחי' מקבל בלבד מהמשכה זאת ולא בחי' כאח לי. לפי שמבחי' עליונה כזו א\"א להיות אלא מקבל בלבד כענין ודברי אשר שמתי בפיך כו'."],[109,"וענין יין הרקח הוא ע\"ד שנזכר בגמ' תליסר נהרא דאפרסמונא דכיא שרומז לאור ההמשכה מי\"ג ת\"ד דנפקי ממו\"ס. אע\"ג דשמן סתם הוא בחי' חכמה. אבל שמן אפרסמון שיש בו ריח טוב שהוא בחי' מקיף רומז לבחי' ההמשכות מבחי' חכמה שבכתר שלמעלה מבחי' כלים. (ועמ\"ש פ' נשא בד\"ה זאת חנוכת המזבח ביום המשח אתו). ועד\"ז ג\"כ בבחי' יין דיין סתם זהו בחי' בינה. אבל יין הרקח שיש בו ריח הוא בחי' התגלות התענוג בבינה מבחי' עתיקא כו' וזה נמשך ע\"י אתכפייא של קביעות עתים לתורה של הבעלי עסקים וכמש\"ל:"],[110,"כי\"ק אדמו\"ר נ\"ע"],[110,"<b>ביאור לענין הכרובים<\/b>"],[110,"<b>כשהנוק'<\/b> היא כנ\"י עומדת פב\"פ עם ז\"א ושויון בקומתן ומקבלת ג\"כ המוחין דאו\"א וכתר א' לשניהם. אזי נקראים אחים וזה היה ע\"י קבלת התורה (דנפקא מחו\"ב) פב\"פ. והנה באצי' נקראים אדם הגדול ואנפי רברבי להיות אוא\"ס ⟦פא,ב⟧מלובש גם בכלים ולזאת איהו וגרמוהי חד. וע\"י המשכן ובהמ\"ק שצמצם שכינתו מבין בדי ארון בעשיה אזי נק' זו\"נ אנפי זוטרי בגמרא והן הן הכרובים."],[110,"ולפי שעולם העשיה עולה לאצי' ג\"פ בכל יום. לכן יש לכרובים כנפים פרושים למעלה לעופף לאצי'. ונודע שהז\"א הוא תכלית ירידת אוא\"ס מלמעלה למטה בכדי להאיר אח\"כ לבי\"ע ע\"י הנוק' שהיא אימא תתאה שהוא מקור בי\"ע שבאצי'. לכן כתיב כרוב אחד מקצה מזה הוא קצה אוא\"ס שבז\"א וכרוב א' מקצה מזה הוא מקור בי\"ע ושרשם שבאצי' שמתלבש בהם ג\"כ אוא\"ס ע\"י המוחין דאו\"א הנותנים בראש הנוק' ע\"י ז\"א בעלה דרך מעבר לבד ולא בדרך התלבשות ממש כמו שהוא בזמן שאינו שוה בקומתה עמו רק מהחזה ולמטה כנודע."],[110,"והכרובים נעשים מקשה אחת מהכפורת שהוא בחי' כתר לשניה' וגם בחי' מקיף על הלוחות שבארון שהן בחי' יסוד אבא שנתלבשו בעשיה בזמן המשכן והמקדש ובזמן עליית הכרובים הם מעלים גם הכפורת והלוחות לאצי' לכן כתיב סוככים בכנפיהם על הכפורת שהכפורת עולה עמהם ואחר החורבן נסתלקו זו\"נ שבאצילו' למקומם ולא חזרו להתלבש עוד בעשיה גשמיות אף בבית שני כי נגנזו הכרובים. אלא רק בבחי' פנימית העולמות ע\"י עסק התורה של התנאים שבימי בית שני ואחריו בהלכות שהן פנימית רצה\"ע שלא נתגלה בח\"ע הוא תורה שבכתב. וכנודע ממ\"ש אשת חיל עטרת בעלה:"],[111,"⟦פא,א⟧<b>ואתה תצוה את בני ישראל ויקחו אליך כו'.<\/b> מחוץ לפרכת אשר על העדת יערך אתו אהרן כו'. וצריך להבין מאחר שהמצוה היא באהרן שהוא יעריך את הנרות למה צוה ה' ויקחו אליך דמשמע שיביאו השמן אל משה."],[111,"וגם דבפסוק ראשון גבי ויקחו אליך אל משה כתיב להעלות נר תמיד ובפסוק שני גבי אהרן כתיב מערב עד בקר לבד. אך הענין הוא כי הנה אהרן שושבינא דמטרוניתא מטרוניתא הוא מקור נש\"י כי כל ישראל כו'. ואהרן הוא השושבין להם כמו עד\"מ חתן וכלה שצריכין שושבין לילך עמהם לפי שא\"א להם לילך בעצמם מחמת הבושה וצריכין סעד לתמכם. כך להיות התכללות נש\"י במקורם באוא\"ס ב\"ה אין להם כח מצד עצמם רק ע\"י בחי' אהרן שהוא שושבינא דלהון."],[111,"והנה כמו ענין השושבינים עד\"מ שאין זה אלא בשעת החתונה כי משם ואילך אין צריכין עוד לשושבינים. כך הנה שושבינות של אהרן הוא בבחי' ביום חתונתו וביום שמחת לבו והוא שמחה של מעלה המתגלה בנש\"י לשמח לבם בה' השוכן בתוך תורתם ועבודתם שצ\"ל בשמחה כמ\"ש תחת אשר לא עבדת בשמחה כו'."],[111,"ושמחה זו היא באה ע\"י אהרן ובשמחה זו הוא שושבין. והענין כי הנה שמחה זו הוא מחמת אוא\"ס ב\"ה מקור החיים מקור התענוגי' המלובש במצות. וכמאמר אק\"ב. אשר הוא לשון תענוג גדול מאד עד להלל וכמו באשרי כי אשרוני בנות שהוא לשון שמחה והילול על רוב טוב כו'."],[111,"וכמ\"ש ויניחהו בג\"ע לעבדה ולשמרה. לעבדה במ\"ע שע\"י המצות הוא עושה הג\"ע דהיינו שממשיך בו זיו השכינה ליהנות בו לצדיקים שמתענגים על ה' בג\"ע שהוא תענוג נפלא עד אין קץ שלכן אמרו על אחר מוטב דלידייני' כו'. שכל יסורי גיהנם כדאי לסבול בשביל קבלת תענוג עוה\"ב וכמארז\"ל על ר\"ע כשרא' כרך ⟦פא,ב⟧גדול של עכו\"ם שחק ואמר אם לעוברי רצונו כך לעושי רצונו עאכו\"כ. פי' אם יש הרבה תענוגים כ\"כ בבחי' עוברי רצונו שהם תענוגי עוה\"ז שירדו ונתגשמו בגשמיו' העוה\"ז וחומריותו שלא כדרך השתלשלות וירידת המדרגות מאוא\"ס ב\"ה מדרגה אחר מדרגה כמו מדרגות דקדושה אלא שהם נפלו ממדרגות עליונות דקדושה דרך נפילה מאיגרא רמה כו'."],[111,"ולכן נק' עוברי רצונו שהעבירו את הדרך. ואם לעוברי רצונו כך יש תענוג הרבה שנפל בשבה\"כ כ\"ש לעושי רצונו דהיינו מה שהוא עשוי ונתון מרצה\"ע ב\"ה כסדר ירידת המדרגות דקדושה בג\"ע העליון והתחתון שהוא התענגות על הוי\"ה שבודאי יש בו תענוג נפלא והרבה מיני תענוג אין קץ שהוא מקור החיים ומקור התענוגים:"],[111,"<b>והנה<\/b> תענוג זה נמשך מן המצות שלכן נמשלים המצות לנרות כמו שע\"י שמדליקין את הנרות נתמלא הבית אור וזיו. כך ע\"י עשיית המצות נמשך זיו בג\"ע כו'. לכן כתיב תחת אשר לא עבדת את ה' אלקיך בשמחה ובטוב לבב מרב כל. יותר מרוב כל כי רוב כל הם תענוגי העוה\"ב והמצות צריך להיות בשמחה יתירה מהם."],[111,"והוא כאשר ישים אל לבו כי בשמים ממעל ועל הארץ מתחת על כל שבח מעשה ידיך כו'. פי' בשמים ממעל זה געה\"ע. ועל הארץ מתחת זה געה\"ת אין השבח בהם אליך אלא שהם בחי' מעשה ידיך כמו עד\"מ שמשבחין את האדם במעשה ידיו איך שהוא כותב גדול או שמצייר ציור נאה שהשבח הזה אינו נוגע לחכמתו ולא למהותו ועצמותו. כך כל השבח וההילול שנמשך בג\"ע לנשמות להתענג על ה' בהשכלתם והשגתם אין השבח הזה אלא בהמשכת מעשה ידיו של הקב\"ה לבד שבזה יש להם השכלה והשגה והיינו זיו הנמשך ⟦פא,ג⟧מן המצות שנק' מעשה ידיו של הקב\"ה כי באתעדל\"ת בקיום המצות למטה אתעדל\"ע הקב\"ה מניח תפלין והקב\"ה רופא חולים ומברך השנים ומכלכל חיים בחסד כו'. ומזה נמשך הזיו בג\"ע להתענג על הוי\"ה בהשכלתם והשגתם בהמשכה זו (וזהו ומעשה ידיו מגיד הרקיע כי הג\"ע נק' מתיבתא דרקיע. ועמ\"ש בפי' הללוהו ברקיע עוזו) וכמה מיני מדרגות זו למעלה מזו בהשכלה זו בכמה מיני תענוגים עד אין קץ שיש כמה מיני ג\"ע כו'. הגם שלא נזכר בספרים רק ג\"ע תחתון ועליון הרי אמרו רז\"ל ת\"ח אין להם מנוחה שנאמר ילכו מחיל אל חיל כו'."],[111,"וע\"ז נאמר כי כל בשמים ובארץ ותרגומו דאחיד בשמיא ובארע'. והוא ענין שנזכר בספרים שיש עמוד בג\"ע שבו עולין מג\"ע עליון לתחתון שהעמוד הוא המחבר ג\"ע עליון עם תחתון. וכמה בחי' עמודים לכמה בחי' צדיקים יש לכל א' כפי מדרגתו וכמה בחי' עליות בעילוי אחר עילוי כענין נו\"ן אלף יובלות שהכל בחי' עליות כו'."],[111,"וכל זה הוא בבחי' הזיו שנמשך ממעשה ידיו בלבד. אבל בא\"ס ב\"ה ממש בעצמותו ומהותו ית' לית מחשב' תפיסא המלאכים אומרים קדוש ומובדל כו'. ומחמת זה האופנים ברעש גדול כו'. שאומרים איה מקום כבודו. אך המצות עצמן הן בחי' אור הנר שמזה נמשך הזיו."],[111,"והם מקור הזיו שהם נק' אברים דמלכא בחי' אברין וכלים לאוא\"ס ב\"ה ממש. ולכן בכל המצות כתיב לפני ה' לפני ה' ממש וכמ\"ש אשר אנכי מצוך היום. שבבחי' היום לעשותם אנכי ממש הוא עצמותו ומהותו ממש מצוך כו'. ואי לזאת תהיה השמחה בקיום המצות גדולה לאלקים הוא אוא\"ס ב\"ה ממש המלובש בהן ביתר שאת מרב כל. היינו בחי' כל דאחיד בשמיא ובארע' וכמרז\"ל יפה שעה א' וכו':"],[111,"<b>והנה<\/b> להיות גילוי שמחה זו מאור א\"ס ב\"ה בנפש האדם הוא ע\"י אהרן שהוא המדליק את הנרות להיות בחי' אורה ושמחה. כי אהרן הוא משבעה רועים המפרנסים וממשיכים לכללות נשמות ישראל מלמעלה מאוא\"ס ב\"ה."],[111,"ואהרן הוא הרועה ומפרנס וממשיך לכללות נש\"י בחי' אורה ושמחה הנ\"ל ובהמשכה זו יש ב' בחי' יערוך את הנרות ובהעלות אהרן את הנרות יערוך להיות ערוכה ושמורה בלב ונפש האדם בזכרו על ה' אלהיו בעמקו' הדע' מעומק' דלבא ביגיעת הנפש בהתבוננות בגדולת ה' כאשר תוכל נפשו שאת ובהעלות הוא היא המשכות השמחה הבאה מלמעלה להעלות את הנפש ולקשרה באלקים חיים הוא חיי החיים ב\"ה מקור החיים ומקור התענוגים שלמעלה מעלה מהשתלשלות למעלה מכדי שתוכל נפשו שאת והיא אהבת בכל מאדך המתגלה בק\"ש ולקיום הק\"ש בכל מאדך תקנו פסוקי דזמרה לפניה להיות רוממות אל בגרונם וחרב פיפיות בידם כי שעת צלותא שעת קרבא לעשות הכנה בנפש האדם תחלה להגביר כח נפשו על המונעי' ומעכבים מבית ומחוץ. וזהו מערב ועד בקר כי ברישא חשוכא והדר נהורא שמאיר בנפשו אורה ושמחה בה' מעט מעט מתוך החשך כו':"],[111,"<b>אך<\/b> הדלקת אהרן את הנרות הוא בשמן זית כתית דוקא וכדאיתא במשנה כותש ונותן לתוך הסל כו'. הראשון למנורה והשאר למנחות. והענין הוא כי ענין הזית הוא שיש בו מרירות. וכמו שאמרה היונה יהיו מזונתי מרורים כזית כו'."],[111,"וגם אמרו בגמרא שהזית משכח תלמודו של ע' שנה כו' שהוא מבחי' עולם השכחה שהוא מעולם הקליפות. והיינו ענין הגוף ונה\"ב שמנוגה ומשכא דחויא וכותשים אותו עד שמוציאים ממנו שמן היינו בחי' חכמה."],[111,"וכמארז\"ל כשם שהזית משכח תלמודו של ע' שנים. כך שמן זית מחזיר תלמודו של ע' שנה כו' כי חכמה הוא מוח הזכרון כמ\"ש ⟦פא,ד⟧בפ' קדש שרומזת בחכמה ולזכרון בין עיניך כו' וענין כתישה זו היינו להיות בבחי' אתכפייא סט\"א ע\"י לשארית נחלתו שמשים עצמו כשיריים שבחי' זו היא המכנעת כל הרצונות שבזלעו\"ז שלא יהיה לו חפץ ורצון אחר לעצמו להנות ולהתענג בתענוגי בני אדם בעוה\"ז ולא יבקש וירדוף אחריהם כלל כי מאחר שמשים עצמו כשיריים ומותרות בעולם וכאלו אין בו צורך בעולם כלל. מה לו ולעולם כו'."],[111,"ולכן לא יאבה לא העוה\"ז ולא העוה\"ב. וכמ\"ש מי לי בשמים כו' וכמ\"ש והיה שארית יעקב בגוים כו' וכתיב בתריה תרום ידך על צריך וכל אויביך יכרתו שבבחי' שארית יעקב שמשים עצמו כשיריים הוא מכרית וירים ידו על צריו בבחי' רוממות אל בגרונם להיות חרב פיפיות בידם בהתגלות רוממות אוא\"ס על נפשו משא\"כ בבחי' יש אין אני והוא יכולין לדור כו'."],[111,"ואין אוא\"ס ב\"ה שורה ומתגלה אלא במי שבטל כו'. והיינו בחי' חכמה הוא בחי' שמן הנעשה ע\"י כתישת הזית שהשמן הוא שנמשך אחר הפתילה ונכלה ונשרף הכל באור הנאחז בפתילה שלא נשאר ממנו כלום (משא\"כ מן הפתילה נשאר קצת אפר) וכך בחי' החכמה הוא בחי' הבטול שבטל ונכלל ממש באור הנר של מצוה זו להיות גילוי אוא\"ס ב\"ה ממש על נפשו. ועי\"ז מתקיים בנפשו אוא\"ס ב\"ה הנמשך מן המצוה. משא\"כ בלא בחי' שמן הרי אין אור הנר מתקיים על הפתילה לבדה אלא דולקת מהר וכלה כרגע כו'."],[111,"והנה עבודת אהרן בעריכת הנרות והעלאתם היינו בחינת השמחה של מצוה היא מחוץ לפרכת העדות. וענין הפרכת הוא כי הנה כתיב כי שמש ומגן הוי\"ה אלקים. פי' כי שם הוי\"ה הוא ענין יחודא עלאה איך שאין עוד מלבדו וכלא קמיה כלא חשיב כו' ושם אלקים הוא המסתיר ומעלים להיות נראה העולם בבחי' יש ודבר כו' רק אעפ\"כ מלא כל הארץ כבודו בבחי' יחודא תתאה. והנה שם אלקים הוא מגן לשם הוי\"ה כמו מגן שעושין לשמש שמחמת שא\"א להסתכל בשמש מרוב בהירותו כו':"],[111,"<b>וזהו<\/b> ענין והבדילה הפרכת לכם בין הקדש כו' ושם הוא ענין עריכת הנרות ושמחה ש\"מ מחוץ לפרכת בבחי' יחודא תתאה להיות רץ לבך ליחודא עלאה כי שמחה זו היא בחי' רצוא בנפש מחמת גילוי אור א\"ס ב\"ה ממש שבמצותיו שעי\"ז אליו לבדו ית' תכסוף ותכלה הנפש בבחי' ובכל מאדך בשמחה שהיא בחי' ובהעלות אהרן כו':"],[111,"<b>אך<\/b> הכח הזה שיש לאהרן להעלות את הנפש מחוץ לפרכת להיות בה גילוי אהבה זו שהיא בבחי' א\"ס הנה ע\"ז נאמר חוקת עולם לדורותם מאת בני ישראל. פי' מאת היינו מבחי' אותיות התורה שמאל\"ף ועד תי\"ו דהיינו ע\"י עסק התורה של בני ישראל שהאדם לומד ומשים לבו ונפשו באותיות שמדבר בהם בדו\"ר שאותיות אלו יסודתן בהררי קדש חכמה עלאה לכן התורה היא אור שהיא מאירה את הנר שנר מצוה היא כלי לאור התורה והתורה היא אור וחיות המצות והן הגורמות להיות כח לאהרן להיות שושבין להמשיך אור וגילוי האהבה בנפש האדם ולהיות בה אורה ושמחה ש\"מ. משא\"כ ע\"ה שאין בו בחינת חכמה ארז\"ל ולא ע\"ה חסיד כו'. אך להיות המשכת התורה למטה בישראל הוא ע\"י בחי' משה וכמ\"ש בזהר ע\"פ מה יתרון לאדם בכל עמלו שיעמל תחת השמש. שאני עמל' דאורייתא דהיא לעילא מן שמשא ושם הוא מדרגת משה כבד פה וכבד לשון כו'. כי בחי' עסק התורה הנה אינו בדרך שמחה ש\"מ שהוא בבחי' רץ לבך מחוץ לפרכת אלא היא בבחי' שוב לאחד שע\"י התורה הוא גילוי יחודו ית' למטה כמו למעלה ע\"י התורה שהיא דבר ה' ממש."],[111,"וכמ\"ש ודברי אשר שמתי בפיך דברי ממש הנה ארז\"ל מתניתא מלכתא כמלך עצמו ⟦פב,א⟧שמתאחד עם דבר ה' זו הלכה שיהא הפסק כך כאלו הפסק הזה יוצא מפי עצמו והיינו מעלת ומדרגת מי שתורתו אומנתו כמו רשב\"י וחביריו (שלכן פטורים מן התפלה שהתפלה היא בחינת בטול בהשתחוואות והמשכת אוא\"ס ב\"ה המשכות אלו נמשכות ע\"י עסק התורה ג\"כ) וכמו שא' רשב\"י בחד קטירא אתקטרנא כו' שהוא בחי' בטול באוא\"ס ב\"ה ממש בבחי' יחו\"ע ולכן ארז\"ל ות\"ת כנגד כולם. והנה כדי שיגיע לבחי' ומדרגת בטול זה כתיב ויקחו אליך שמן זית זך בחי' חכמה כי איזהו חכם הרואה את הנולד דהיינו הנולד מאין ליש."],[111,"וכמאמר המחדש בטובו בכל יום תמיד מעשה בראשית כו'. כי ההתחדשות מאין ליש הוא תמיד כו'. והיינו לפי כי אני הוי\"ה לא שניתי ואתה הוא קודם שנברא כו' רק ההתחדשות להיות יש הוא רק הארה בעלמא כו'. ולכך צ\"ל התחדשות ההארה תמיד שלא תבטל במציאות לגמרי כו' וכאשר ישים אל לבו הדבר הזה יהיה בבחי' בטול אליו ית' ורוח אייתי רוח ואמשיך רוח כו' בטול אוא\"ס ב\"ה ממש על נפשו בעסק התורה כו':"],[111,"<b>וזהו<\/b> ואתה תצוה את בני ישראל תצוה מלשון צוותא והתקשרות ע\"י ויקחו אליך שמן זית זך לבחי' משה תחלה ומזה נמשך להיות חוקת עולם מאת בני ישראל להיות אותיות התור' גורמת שיערוך אהרן את הנרות בחי' שמחה של מצוה מחמת כי אותיות התורה הן הנמשכות מבחי' משה ואתה תצוה את בני ישראל כו'."],[111,"והנה בבחי' אהרן שהוא בחי' רץ לבך כתיב מערב ועד בקר ברישא חשוכא והדר נהורא אבל בבחי' משה שהוא בבחי' שוב לאחד וגילוי יחודו ית' בבחי' יח\"ע כתיב להעלות נר תמיד שהוא גילוי יחוד עליון שלמעלה מהזמן ולפניו ית' כחשכה כאורה שהוא השוה ומשוה כו' וד\"ל:"],[112,"<b>ועשית בגדי קדש לאהרן אחיך וגו' ואתה תדבר אל כל חכמי לב אשר מלאתיו רוח חכמה ועשו את בגדי אהרן לקדשו וגו' ועשו בגדי קדש לאהרן אחיך ולבניו וגו'.<\/b> להבין שלש עשיות הללו שבבגדי אהרן של משה ושל חכמי לב וסתם ועשו משמע של כלל ישראל. הנה אהרן הוא משבעה רועים המפרנסים וממשיכים לכללות נש\"י מאוא\"ס ב\"ה שהוא איש החסד וכהן גדול הממשיך בחי' אה\"ר ובגדי אהרן הם לבושים לאהבה זו."],[112,"וכענין מ\"ש ימים יוצרו שהימים הם בחי' לבושים. וכמ\"ש בזוהר ע\"פ ואברהם זקן בא בימים יומין עלאין דאינון לבושין כו'. לפי שכל נשמה יש לה לבושים של תורה ומצות אשר יעשה אותם האדם ומכוונת המצות ורעותא דלבא נעשו לבושין בג\"ע העליון. וממצות מעשיות סתם נעשו לבושים בג\"ע התחתון כנודע. והימים הקצובים לאדם מספר ימי שני חייו כ\"כ ימים בשיעור לבושין שצריכה הנשמה להיות לה מהתורה ומצות אשר יעשה דבר יום ביומו:"],[112,"<b>והנה<\/b> נודע כי אברהם הוא הרועה הראשון משבעה רועים הממשיך ג\"כ בחי' אהבה לכללות נשמות ישראל. וכמ\"ש אברהם אוהבי. וההפרש שבין מדת אהרן איש החסד ובין מדת אברהם אוהבי יובן ע\"פ מ\"ש בזוהר אית חסד ואית חסד אית חסד דאקרי חסד עולם. ואית חסד דאקרי ורב חסד כו':"],[112,"<b>וביאור<\/b> הענין זה הנה נודע דבאתערותא דלתתא אתערותא דלעילא. והנה גם לפני אתערותא דלתתא קדמה אתערותא דלעילא כדי שתהא אתעדל\"ת לעורר לב האדם להקיצו משנתו בהבלי העולם שטבע האדם נמשך אחריהם ולהמשיך לבו לעבודת ה' לדבקה בו."],[112,"ואתעדל\"ע זו היא מבחי' חסד עולם. וכמ\"ש וחסד ה' מעולם ועד עולם. חסדי ה' עולם אשירה הוא בחינת מדרגת אברהם שזכה להיות מרכבה לחסד זה. וכמ\"ש חסד לאברהם ⟦פב,ב⟧שהיא מדת האהבה הטבעית שבלב כללות נש\"י רק שהיא מסותרת ומכוסה בלבוש שק שהם הגוף ונה\"ב."],[112,"ואתערותא דלעילא זו היא לעורר את האהבה עד שתחפץ להתפשט מלבושיה לדבקה בו ית' ולצעוק אל ה' בצר לו מקרב איש ולב עמוק להמשיך לבו אחר ה' כטבע נפשו מאליו וממילא. אך באתעדל\"ת אתעדל\"ע הוא שמעורר האדם למעלה בחי' ורב חסד שהוא בחי' אהרן כהן גדול שבחי' זו מאד נעלה מבחי' חסד עולם כי חסד עולם הוא מבחי' התהוות ההשתלשלות בסדר המדרגות דרך עילה ועלול שכל עלול יש לו איזה ערך ויחוס עם עילתו כמו עד\"מ גילוי השכל במדות אהוי\"ר כו' שהמדות מקבלים מגילוי השכל שהוא מלובש בהם ממש וכן המדות במחשבה ומחשבה בדבור כו'. אבל בחי' ורב חסד הוא למעלה מעלה מן ההשתלשלות שהוא בחי' גילוי ההמשכה והתלבשות אור א\"ס ב\"ה בחכמה וחסד כו'. דהיינו להיות ראשית ההתהוות של בחי' חכמה כו' והחכמה מאין ממש תמצא שאין ערוך אליו כלל וכמ\"ש בת\"ז לאו דאית לך צדק ידיעא כו' ולא מכל מדות כו'."],[112,"וגם מן החכמה הוא למעלה רם ונשא כו'. וכמ\"ש כלם בחכמה עשית בחי' עשייה גופנית כו'. ודרך גילוי זה והמשכה זו להיות התלבשות אוא\"ס ב\"ה בחכמה הוא כמ\"ש כי הנה כשמן הטוב על הראש יורד על הזקן זקן אהרן. פי' מה שנמשך בבחי' זקן אהרן דיקנא דכהנא רבא שהוא בחי' שערות. דהיינו כמשל ההארה היוצאת דרך נקבי שערות הראש או הזקן ממותרי מוחין שהשערות הן חלולין ויונקין מהמוחין שבראש ועל כל זה אין להם ערך ויחוס כלל עם המוחין שבראש שהם חב\"ד ואין עיקר חיות המוחין מתפשט בהם שהרי אם יחתוך אדם שער ראשו לא ירגיש המוח כאב כלל שאין מתפשט בהם אלא הארה בעלמא להיות להם רק יניקה ואחיזה במוחין. כך עד\"מ הוא גילוי אור והתלבשותו בחכמה וחסד שאין ערוך כלל ולהיות נמשך מבחי' דלאו מכל מדות כו' ולמעלה מגדר חכמה כו' התהוות בחי' חכמה ומדות אין זה אלא זיו והארה בעלמא בבחי' שערות שהם צמצומים רבים ועצומים להמשיך ההארה."],[112,"וכמשל זה של השערות שהוא בגשמיות הגוף כך יש עוד משל רוחני בחיות הנפש מהמשכת איזה חכמה בצירופי אותיות הדבור. כמו למשל אותיות דבורי הרב המלמד ומסביר איזה חידוש ושכל לתלמידו כי הנה צירופי אותיות מדבור הרב אינם עצמיות השכל שהרי יכול להיות הסבר הזה גם בצירופי אותיות אחרות רק הם כדמיון השערות כי על ידן ובתוכן עובר השפעת השכל ולפי שבעצמות השכל של הרב אין תפיסא להתלמיד לכך צ\"ל צירופי אותיות הדבור להעביר ולהמשיך השכל של הרב לתלמיד."],[112,"והנה הגורם להיות צמצומים אלו להמשכת גילוי זה היא אתערותא דלתתא שע\"י האהבה שממטה למעלה כמים הפנים כו' כך היא האהבה עליונה אהבתי אתכם אמר הוי\"ה דהיינו להיות בחי' הוי\"ה צמצום והתפשטות כו' כי אהבה דוחקת את הבשר:"],[112,"<b>והנה<\/b> באתערותא דלתתא זו שהאדם מעורר למעלה ממשיך ג\"כ על נפשו למטה להיות גילוי בחי' זו בנפשו כי אתערותא דלעילא הוא מבחי' אהרן שהוא משבעה רועים הרועה וממשיך הגילוי בכנס\"י הוא שורש כל נש\"י ואהרן אותיות נראה שהוא כמ\"ש עין בעין נראה כו'. דהיינו להיות גילוי אתערותא דלעילא זו בנפש האדם בהתפעלות והתגלות הלב וכדמיון ראיה חושיית ויומשך עליו גילוי אור האה\"ר הבאה מלמעלה כמו שיתבאר לקמן."],[112,"וכמ\"ש ואהבת את ה' אלקיך כו'. וע\"ד דרשת רז\"ל שיהא שם שמים מתאהב כו' כלומר שואהבת הוא פועל יוצא לשלישי דהיינו שתפעול את האהבה העליונה ⟦פב,ג⟧שהיא אהבתי אתכם כו' להיות בחי' גילוי בנפש שהוי\"ה יהי' אלקיך אלוה שלך כו' והיינו ע\"י התבוננותו בה' אחד איך שהוא אחד בח' וד' שהם ז' רקיעים והארץ וד' רוחות העולם שתמשך בהם בחי' אחד הוא יחודו להיות מתייחדים וכלולים בא' וכן למעלה מעלה ברוחניות עד רום המעלות יש בחי' ז' רקיעים וארץ כו' שהם בחי' לך ה' הגדולה והגבורה כו' שהם בחי' שמים אש ומים ולך ה' הממלכה היא בחי' ארץ והכל בבחי' לך ה' שהם בבחי' בטול אליו ית' מחמת כי נשגב שמו לבדו רק הודו וזיוו על ארץ ושמים דהיינו על כל בחי' ארץ ושמים הנ\"ל וארץ קדמה לשמים כו' והגורם להיות יחוד זה והמשכה זו הוא כי הוי\"ה אלקינו דהיינו שישראל הם המייחדים שמו והממשיכים להיות יחודו ית' למטה להיות גילוי א\"ס בעולמות שבאתערותא דלתתא תליא מילתא וכמ\"ש בת\"ז לאו דאית לך צדק ידיעא כו' אלא לאחזאה כו' כפום עובדיהון דב\"נ שלהיות לאחזא' דהיינו גילוי איך אתנהג עלמא בצדק ובמשפט דהיינו בבחי' מדות ולהיות יוצא מההעלם שהוא בחי' דלאו מכל מדות כו' הוא כפום עובדיהון דב\"נ תלוי במעשה התחתונים כו' וכאשר יעמיק מחשבתו וישים על לבו הדברים האלה אזי יהיה שם שמים מתאהב כו' שיהי' גילוי האהבה העליונה שורה ומתגלה בנפש בבחי' ראיה שיהא הלב רואה כו'."],[112,"וגילוי זה בנפש הוא מחמת אתערותא דלתתא בכל לבבך בשני יצריך שגם היצה\"ר יהי' לאכפייא כו' שלא יהי' לו רק לב א' לאביהם שבשמים. וכמ\"ש ועמך לא חפצתי בארץ. וכמארז\"ל בטל רצונך כו' שלא יהי' לו חפץ ורצון אחר להיות פוסח על שתי הסעיפים כו'. כי ע\"י שצמצם א\"ע וישליך מנגד נפשו ורצונו שבגשמיות וישים אליו לבו רוחו ונשמתו כו' אזי כמים הפנים לפנים תהיה אהבה עליונה שורה ומתגלה בו להיות האהבה דוחקת את הבשר בבחי' צמצומים רבים להאיר מתוכם אוא\"ס ב\"ה בגילוי על נפשו שיושפע עליו שפע רב וגלוי עצום עד שיגיע למעלת ומדרגת ובכל מאדך הוא בחי' אה\"ר הבאה מלמעלה שהוא למעלה מכדי שתוכל נפשו שאת בכלות הנפש ובטול במציאות כו' כי אהרן שושבינא דמטרוניתא שהוא המגביה ומנשא נש\"י עד רום המעלות. וכמ\"ש אלה מסעי כו' ביד משה ואהרן וכתיב הוא אהרן ומשה אשר אמר ה' להם הוציאו את בני ישראל מארץ מצרים על צבאותם פי' למעלה מצבאותם למעלה משרש נשמותיהם:"],[112,"<b>אך<\/b> הנה לבחי' גלוי האהבה צ\"ל בחי' כלי ולבוש במה שתשרה ותתלבש האהבה שתבא ליד גלוי בפו\"מ כי אין אור בלא כלי ולבוש. ועל זה נאמר זקן אהרן שיורד על פי מדותיו. מדותיו מלשון מדו בד אלו הלבושין שהם הם התורה והמצות שהם בחי' לבושין לאהבה זו כי מאחר שבחי' אהבה זו נמשכה מבחי' דלאו מכל מדות כו'. למעלה מגדר חכמה כו' אינה נתפסת בשום שכל שבגדר חכמת הנבראים והשגתם אלא כאשר תפיסא ומתלבשת בתורה ומצות שהם רצונו וחכמתו ית' מבחי' אנת חכים ולא בחכמה ידיעא כו':"],[112,"<b>וזהו<\/b> והיו הדברים האלה אשר אנכי מצוך כו' שלהיות גלוי בחי' אנכי מי שאנכי הוא ע\"י והיו הדברים האלה דוקא ולכך ודברת בם ולא בדברי' בטלים. ופי' ודברת מלשון ידבר עמים שהוא לשון הנהגה והמשכה. כלומר שהמשכות גלוי האהבה יהיה בלבוש התורה דוקא ולא בשאר חכמות שהם לשכל והשגת הנבראים כי כולם נק' אצלו ית' דברים בטלים דלאו אורחא דמלכא לאשתעי במילין דהדיוטא אלא דוקא בחי' התורה שהיא בחי' דלאו בחכמה ידיעא כו' שהוא למעלה מעלה מגדר ושכל והשגת הנבראים כו'."],[112,"וע\"י עסק התורה למטה שהיא חכמתו ית' ממשיכין האהבה העליונה להיות גלוי ⟦פב,ד⟧אוא\"ס בחכמה כו'. וזהו ענין עסק התורה לשמה לשם התורה דהיינו להיות גלוי אוא\"ס בחכמה שהיא בחי' התורה דאורייתא מחכמה נפקת."],[112,"וזו היא המשכת ראשית התהוות ההשתלשלות מאין ליש שהוא ראשית חכמה וצ\"ל המשכה ב' במדות ג\"כ בראשית שהוא החסד כי הוא ראשית הבנין. וכמ\"ש כי אמרתי עולם חסד יבנה והמשכה זו ע\"י עשיית המצות שכללותן נק' בשם צדקה וחסד. ובפרטן מתחלקין לרמ\"ח. רמ\"ח אברין דמלכא שבהם ועל ידם ממשיכים גלוי למעלה אור א\"ס ב\"ה בחסד. וזהו ושמרו דרך ה' לעשות צדקה כו'. דרך ה' כלומר המשכת גלוי הוי' מההעלם אל הגלוי (ונק' המשכה זו בשם דרך עד\"מ כמו דרך שמהלכין בה מעיר לעיר) לעשות צדקה כו' שיהיה התהוות בחי' צדקה וחסד. וכמ\"ש וצדקה ביעקב אתה עשית שנמשך בחי' צדקה מלמעלה ע\"י ישראל. אל תקרי בניך אלא בוניך שעל ידיהם הוא בנין החסד. וכמ\"ש עולם חסד יבנה. ולכך נק' כנ\"י יונתי תמתי כלומר שמתממת ומשלמת אותי כביכול להיות תמים ושלם ברמ\"ח אברים דמלכא. כלומר שממשיכים להיות בחי' רמ\"ח אברים ע\"י רמ\"ח מצות כו':"],[112,"<b>והנה<\/b> בתקון ועשיית לבושים אלו יש ג' בחינות ומדרגות מדרגה הא' הוא של משה כי משה נקרא על שם כי מן המים משיתהו. ופירוש משיתיהו מההעלם אל הגלוי שנמשך מן ההעלם שלמעלה מן ההשתלשלות מן המים בחי' מקור התורה שכל התורה היא בחינת כד שנשאב מן הים הם כ\"ד ספרי דאורייתא. וכמ\"ש ותמלא כדה ותעל."],[112,"והנה על בחי' לבוש זה הוא ענין מה שארז\"ל שהתורה נק' כלה ומאורשה קהלת יעקב וישראל הם בחי' חתן המשפיע כו' שהם המשפיעים להיות בחי' אוא\"ס בחכמה והם העוסקים בתורה לשמה לשם התורה. דהיינו שיהיה התהוות בחינת תורה. וכן במצות כתיב ועשיתם אתם. אשר יעשה אתם האדם כו'. שהאדם הוא הממשיך ועושה אותן מצות."],[112,"והנה בזה יובן ענין ברכת המצות שהוא כענין ברכת חתנים ונישואין וכמ\"ש בזוהר לית ברכתא שריא אלא באתר דדכר ונוק' כו' שבמקום שיש משפיע ומקבל נשפע תוספת ורבוי שפע והארה מלמעלה מעלה ממקום גבוה מאד נעלה יותר משל ב' הבחי' של המשפיע ושל המקבל."],[112,"וכמ\"ש זכר ונקבה בראם ויברך אתם. וברכה והמשכה זו היא מבחי' משה למעלה מההשתלשלות. ולכך ביום שהוקם המשכן כתיב ויביאו את המשכן אל משה אמר ויהי נועם כו' שתהא השראת הברכה מלמעלה מעלה והיא ברכת המצות ברוך כו' מלך העולם שיהא ריבוי שפע ברכה והמשכה מעולם ועד עולם."],[112,"ותכלית וסוף הברכה הוא להיות גלוי מלכותו ית' מלכותך מלכות כל עולמים והוא בחי' לבוש כמ\"ש ה' מלך גאות לבש וכתיב ומרדכי יצא מלפני המלך בלבוש מלכות שמדת מלכותו היא בחי' לבוש לחכמתו ורצונו ומדותיו ית' הנמשך ומתגלה בתוספת וריבוי האור שלמעלה מעלה מסדר ההשתלשלות וזו היא בחי' ברכה שברכה היא בחי' תוספת וריבוי כו'."],[112,"ומדרגה השנית היא בחי' עשיית לבוש שעושים חכמי לב הנק' חכמי לב ע\"ש שאין להם אלא לב אחד בבחי' בטול בחי' חכמה כי בחי' נפרד שיש לו שתי לבבות עליו נאמר אשר אתם זנים אחריהם כו' שאין אדם עובר עבירה אא\"כ נכנס בו רוח שטות שנסתלק ממנו בחי' חכמה כו' משא\"כ בבחי' לב אחד ע\"ז נאמר אשר מלאתיו רוח חכמה להיות נשפע עליו רוח חכמה מאתערותא דלעילא ע\"י אתעדל\"ת חכמי לב."],[112,"ולכך ועשו את בגדי אהרן לקדשו שגם הם עושים בגדי אהרן בבחינת קדש העליון על ידי המשכת חכמתו ורצונו ית' מאחר שהם בטלים ⟦פג,א⟧אליה ונעשים בחי' מרכבה. ומדרגה השלישית הוא בחי' ועשו סתם של כלל ישראל דלא כתיב בהם לקדשו אלא סתם לכהנו לי שהוא בחי' עשיית המצות מעשיות בסתם מאהבה הטבעית המסותרת בלבד ואעפ\"כ הם ממשיכים לבוש עליון לאהבה זו דהיינו לבוש מלכות כי שום תשים עליך מלך כתיב בקבלת עומ\"ש בשלימות בלב ונפש ונעוץ סופן כו' שהלבוש נמשך מבחי' ברכה עליונה כו'. וע\"ז נאמר איש אשר כברכתו כו'. ועל ידי זה נמשכו להם גם המדות עליונות. וזהו והם יקחו את הזהב ואת התכלת שהם גוונין עלאין כו' וד\"ל:"],[113,"<b>ועשית ציץ זהב טהור ופתחת עליו פתוחי חותם קדש לה'.<\/b> ואמרו רז\"ל קדש למ\"ד למטה והוי' למעלה. ולהבין זה וגם להבין מ\"ש והי' על מצח אהרן ונשא אהרן את עון הקדשים וגו' שהציץ מכפר ונושא עון. וסיפא דקרא והי' על מצחו תמיד לרצון להם לפני הוי'. שבמה שהוא נושא את הציץ על המצח נמשך רצון. ולהבין ענין זה. (אך) הנה ציץ הוא מלשון יציץ נזרו. מציץ מן החרכים. נץ החמה. דהיינו הארת אור וזיו. והוא אור האהבה רבה הבאה מלמעלה שהיא בחי' אהרן זקן אהרן שיורד על פי מדותיו. שאהרן הוא רועה משבעה רועים המפרנסים לכנס\"י המשכות אא\"ס ב\"ה ואהרן הוא הממשיך בחי' אה\"ר."],[113,"והגם שהכל בידי שמים חוץ מיראת שמים. מ\"מ יש אהבה ויש אהבה. יש אהבה שהיא למטה מן הדעת ותולדתה והיא בכח הנפש עצמה. ויש אה\"ר שהיא למעלה מן הדעת הוא בחי' אהרן הרועה וממשיך לכנס\"י והוא בחי' רעותא דלבא."],[113,"וז\"ש לאהבה את ה' אלקיכם וגו'. ולא כתי' לאהוב אלא לאהבה שימשיך האדם את לבו לאהבה עליונה היא רעותא דלבא שיהי' רצונו לה' לבדו ולדבקה בו בא\"ס ב\"ה ממש. וכמ\"ש מי לי בשמים וגו' פי' שמים ג\"ע העליון כו' דכולא קמי' כלא חשיב. אני הוי' לא שניתי ואתה הוא משנברא העולם ואתה הוא קודם שנבה\"ע כו'."],[113,"ועל אהבה זו נאמר מציץ מן החרכים כי הנה זה עומד אחר כתלינו. שמשחרב בהמ\"ק יש כותל ומחיצה של ברזל מפסקת בין ישראל לאביהם שבשמים. כי הגם שאין דבר חוצץ לפניו ית' ח\"ו כי גם חשך לא יחשיך ממך הרי באמת לא אמרו בין אביהם שבשמים לישראל אלא בין ישראל לאביהם שבשמים. שהחציצה הוא בפני המקבלים. עונותיכם היו מבדילין ביניכם וכו'. שמונע את אור האהבה העליונה מישראל ואעפ\"כ הוא מציץ מן החרכים וחלונות. חלונות הם חורים גדולים. וחרכים הם חורים קטנים וסדקים. דהיינו ע\"י שבירת המחיצה לפתוח חלונות וחרכים שהם בחי' לב נשבר והרהורי תשובה הבאים לאדם לכל חד וחד לפום שיעורא דיליה:"],[113,"<b>והנה<\/b> עיקר המסך המבדיל ומחיצה המפסקת הוא ראשית גוים עמלק. שהוא ראש לשבעה גוים. וכתיב מלחמה לה' בעמלק מדר דר אפי' בזמן הזה שלא שייך מלחמת עמלק בגשמיות. מ\"מ ברוחניות הנפש יש בחי' עמלק והיינו בחי' גסות הרוח בחוצפה וגבהות כמ\"ש אם תגביה כנשר וגו' וממנה באות מדות רעות מבית ומבחוץ. מבית בפנימית הנפש גסות הלב ונצחנות וכיוצא בהן."],[113,"ומבחוץ בבחי' חיצונית ההנהגת הגוף בפו\"מ ברדיפת הכבוד ומלבושי בגדי כבוד ותפארת ולהתנהג בכבוד ותפארת וכיוצא בהן. ועל כוונה זו נעשו בגדי כהונה לכבוד ולתפארת לאהרן ולבניו וגו'. להיות בחי' אתהפכא מן היש ולגרמיה שהוא בחי' עמלק שהוא ענין הגדלת היש בכל דרכיו והנהגותיו."],[113,"וכך היתה מדתו של עמלק בזמן משה שהרי ישראל לא באו להלחם אתו ולא שמו לבם אליו רק הוא מעצמו ומאיליו בא לעורר מלחמת חנם מפני גדולתן של ישראל ⟦פג,ב⟧והאותות והמופתים שלא הי' יכול לסבול שיהיה איזה דבר גדול מבלעדו. וככה הוא בכל אדם שלא יוכל לסבול מי שיהיה גדול ממנו בעיני אלהים ואדם כו'. ועכ\"פ שלא יהיה הוא קטן ושפל. לכן מיפה עצמו במלבושי כבוד כו'."],[113,"והנה בבחי' זו של עמלק נאמר כס י\"ה שאין השם שלם ואין הכסא שלם. כסא הוא השראת המלך היושב על הכסא להיות ושכנתי בתוכם. והיינו בבחי' כסא באל\"ף שאלופו של עולם שורה. משא\"כ בהסתלקות האל\"ף נעשה כס מלשון כסוי."],[113,"והתכסות זו היא על שם י\"ה. כי בכל אחד ואחד יש שם י\"ה. כמ\"ש עזי וזמרת יה ויהי לי לישועה. כי הנה ה\"א הוא בחי' התפשטות אורך ורוחב כו'. והוא בחי' התפשטות והמשכות אור אין סוף ב\"ה להיות סובב כל עלמין וממלא כל עלמין."],[113,"והיו\"ד הוא בחי' צמצום ישת חשך סתרו שכדי להיות התפשטות המשכה להיות ממלא וסובב כ\"ע אפי' עולמות עליוני' אין ערוך כו'. וכמשל טפה נגד ים אוקיינוס ויותר מכן לאין קץ כו'."],[113,"ולכך הוצרך להיות בחי' צמצום תחילה ואח\"כ התפשטות כו'. ולכן בתמונת האותיות בכתיבת שם הוי' תמונת ה' ראשונה של שם היא ג\"כ עד\"מ שמתחילה עושין היו\"ד ואח\"כ ממשיכי' ממנה לרוחב ואורך למטה כו'."],[113,"ובחי' זו נמשכה בכל אדם להתבונן בגדולת א\"ס ב\"ה איך שהוא ממכ\"ע וסוכ\"ע ואיך שכ\"ז אינו אלא בחינת צמצום כי אין ערוך כו'. ומזה ישוב לאהבה את ה' ולדבקה בו ממש בבחינת אהבה העליונה. והיינו המשכת הוי\"ו להיות בחינת ו\"ה. אבל עמלק הוא כס י\"ה שהוא המכסה על בחינת י\"ה שלא יתגלה בבחי' ו\"ה שלא יוליד האהבה בהתגלות לבו. שאף שלבבו יבין את כל זאת לא תתפעל הנפש ולא יאיר בה אור האהבה מחמתשנעשה מחיצה של ברזל המפסקת ומונעת את האור:"],[113,"<b>והעצה<\/b> היעוצה לזה הנה במלחמת עמלק כתיב ויאמר משה וגו' בחר לנו אנשים. לנו דוקא שלכבוש מלחמת עמלק צריכים אנשי משה דוקא ובחי' משה הוא כמ\"ש ונחנו מה בחינת בטול והתכללות לגמרי באוא\"ס ב\"ה."],[113,"והנה כל התורה על שמו נק' תורת משה. תורה צוה לנו משה וגו'. והיינו שיהיה כל דרכי התור' והעבודה ע\"פ בחינת משה. וכמארז\"ל כל האומר אין לי אלא תורה אפי' תורה אין לו. רק שצריך להיות תורת משה בבחינת בטול באוא\"ס ב\"ה לגמרי."],[113,"וכמ\"ש ולא תחללו שלא להיות בחינת חלל. כמאמר דוחק רגלי השכינה כביכול אלא כמאמר אתה הוא עד שלא נבה\"ע ואתה הוא משנבה\"ע. הוא ממש בלי שום שינוי דכמו שהי' עד שלא נבה\"ע ממלא את הכל וגם המקום הזה שנברא בו העולם כך עתה כו'."],[113,"ואיך הוא זה והרי העולם מעלים כו' אלא היינו ע\"י עסק התורה דאורייתא מחכמה נפקת וכתיב הוי' בחכמה יסד וגו' שבחכמה שורה אא\"ס ב\"ה שהחכמה היא היא בחינת בטול כח מ\"ה ולכך גם האדם שלומד התורה הרי בכל דבר הלכה או אגדה שלומד מלובש בה בחי' חכמה שבה מלובש אוא\"ס ב\"ה וא\"כ הוא בבחי' בטול בשעת עסק התורה לחכמתו ית' ואין מעלים ומסתיר מאחר שאין נראה ליש ודבר נפרד בפ\"ע רק שהיא חכמתו ית' הבטלה אליו ואין עוד מלבדו."],[113,"ועל זה נאמר ואשים דברי בפיך דברי ממש ופי' דברי בפיך היינו בחי' פנימית. ובצל ידי כסיתיך הן בחי' מקיפים שאוא\"ס ב\"ה שורה ומתגלה בו בבחי' פנימי' ובחי' מקיף וע\"י כן הוא כובש מלחמת עמלק שהוא היש כו' כי ביטול זה הוא הפך היש והוא המכניע ומשבר המחיצה של ברזל כו' וזהו ועשית ציץ דקאי על משה שהוא הוא העוש' את הציץ להיות יציץ נזרו של אור האהבה רבה להיות מציץ מן החרכים וזורח ע\"י ⟦פג,ג⟧עשיית חרכים וחלונות שבירת המחיצה שהן הרהורי תשובה מבחי' בטול אנשי משה וכמ\"ש בחר לנו וגו' כנ\"ל."],[113,"וציץ זה הוא זהב טהור הוא בחי' מעלת הזהב על הכסף. ושתיהן הן בחי' אהבה כמ\"ש לי הכסף ולי הזהב וגו' רק הכסף הוא בחי' קרירות והזהב הוא בחי' רשפי אש האהבה:"],[113,"<b>ופתחת<\/b> עליו פתוחי חותם. הן אותיות התורה כי חותמו של הקב\"ה אמת ואין אמת אלא תורה. ונק' בחי' חותם כי התורה אשר לפנינו שנתלבשה בענינים גשמיים היא היא בחי' חותם כדמיון האותיות שנחקקים על השעוה שאינו מערך ומהות האותיות שבמחשבה או בדבור רק מ\"מ הן אותיות עצמן שנצטיירו ונתגשמו כו'."],[113,"וכך הנה כתיב בצלמנו כדמותנו דקאי על התורה שבע\"פ שהיא בחי' דמות ודמיון בעלמא שהיא בחי' חותם עד\"מ כאותיות הנחקקין על השעוה כו' אעפ\"כ יסודתה בהררי קדש העליון ח\"ע שבכל הלכה כו' וע\"י זה נמשך בחי' קדש העליון בעסק התורה והמצות בבחי' פנימי' ומקיפין שהתורה היא פנימית והמצות הן לבושין ומקיפין כמאמר אשר קדשנו במצותיו והנה המשכה זו היא בחי' קדש למ\"ד למטה והוי' למעלה שבחי' קדש עדיין היא נק' למטה מבחי' הוי' כי הנה יש ב' בחי' הוי' כמ\"ש ויעבר הוי' על פניו ויקרא הוי' הוי' ופסיק טעמא בינייהו כי הן ב' בחי' כי ענין הוי' מורה שהוא מהוה כל ההוויות מאין ליש כו' ע\"י שעלה ברצונו כך ויש מקור ושרש לזה להיות עולה כך ברצונו ולהיות מקור להוות כל ההוויות והוא הוי' הראשון שהוא לרצון לפני הוי\"ה הב' ונק' רעוא דרעוין:"],[113,"<b>וזהו<\/b> ויקרא הוי' הוי'. שהוי' הא' קורא וממשיך הוי' הב' להיות נאצלות ומתגלות י\"ג מכילין דרחמי שהן מקורות כל ההוויות וכל ההשתלשלות ובחי' הוי' הא' הוא למעלה מעלה מבחי' קדש ונקרא רעוא דרעוין."],[113,"וע\"י עסק התורה והמצות הנ\"ל בבחי' הנ\"ל נמשך שיהי' קדש למ\"ד למטה היא בחי' אתעדל\"ת והוי\"ה למעלה היא אתעדל\"ע כי על ידי עסק התורה שהיא חכמתו ורצונו יתברך הרי כמים הפנים כו' ורוח אייתי רוח ואמשיך רוח רצון עליון רעוא דרעוין ועל ידי זה נעשה גלוי רעותא דלבא ואור האהבה עליונה בנפש בלי מסך מבדיל מחיצה מפסקת כו' עד שיהי' על מצח אהרן ג\"כ גילוי בחי' זו:"],[113,"<b>וביאור<\/b> ענין המצח הוא כמו עד\"מ בגשמיו' שיש בתלת חללי דגלגלתא תלת מוחין חב\"ד. ויש גולגלתא דחפיא על מוחא. כך ברוחני' הנה המוחין הם חב\"ד והדעת הוא הכח המקשר את חכ' ובינה להיות תקועה בחוזק בל ימוט שכאשר נגמר בכח חכמתו ובינתו בגדולת א\"ס ב\"ה כך תהא נפשו קשורה בה' לבדו."],[113,"והנה במוחין דחב\"ד שם הוא גילוי אא\"ס ב\"ה בהתבוננות בסדר התפלה וכיוצא בה איך שברוך שאמר והי' העולם ויחיד ומיוחד וחי העולמים מלך וישתבח שמך כו'. וכך הוא התקשרות הדעת בגילוי עוצם התשוקה והתענוג. אך יש בחי' גלגלתא דחפי' על מוחא וכנגד הדעת הוא המצח שהוא הכסוי על הדעת להעלים גלוי הדעת וההתקשרות."],[113,"ולכן אחר התפלה חולפת ועוברת כו' וצריך לחזור ולהתפלל בכל יום לעורר את האהבה וע\"ז נאמר והיו הדברים האלה אשר אנכי מצוך היום. ואמרו רז\"ל בכל יום יהיו בעיניך כחדשים לחדש את האהבה. כי לפי שהוא ית' מחדש בכ\"י תמיד מע\"ב לכך גם האהבה מתחדשת כו'."],[113,"והנה כאשר לבבו פונה זה לכרמו כו' יכול להיות מן הנפילים להמשיך לבו אחר תענוגי עוה\"ז שהן רבוי והגדלת היש. וכתי' תועבת ה' כל גבה לב אפי' בחי' ⟦פג,ד⟧חיצוני' שהן הנהגת הלבושין כנ\"ל וארז\"ל אין אני והוא יכולים לדור כאחת."],[113,"וכמ\"ש אין דעת אלהים בארץ שכאשר הוא מושקע בארציות וחומריות אין בו דעת אלהים והתקשרות. אך כ\"ז הוא בבחי' עכו\"ם שנקראו כך ע\"ש שהם אומות ומקורות לכל עניני עוה\"ז. משא\"כ בבחי' ישראל יכול להיות עצת חכמינו ז\"ל עשה מלאכתך עראי וטפל לבד בבחי' קרירות כמו שכפאו שד כו'."],[113,"וזהו והי' על מצח אהרן שגם אחר התפלה שחולפת ועוברת האהבה מ\"מ נשאר רשימו על בחי' מצח שהוא כיסוי שעל הדעת דהיינו בחינת חיצוניות החב\"ד והוא ענין רצון פשוט לדבקה בו ית' בלי עומק התבוננות כבשעת התפלה רק הסכמת הלב מחיצוניות הדעת אחר אשר נגמר בדעתו כך בשעת התפלה כי הגם שגילוי עוצם התשוקה והתענוג שבדעת חלף ועבר אחר התפלה מ\"מ רשימו ניכר להיות רצון והסכמת הלב לדבקה בו ית' ולהיות מלאכתו עראי וטפל ותורתו קבע ועיקר."],[113,"ורצון זה והסכמה זו יכולה להיות תמיד. וזהו והי' על מצחו תמיד לרצון להם לפני הוי\"ה שע\"י אתעדל\"ת זו אתערותא דלעילא לעורר רצה\"ע רעוא דרעוין והתגלות בחי' הוי\"ה המקור אל הי\"ג מדה\"ר שעי\"ז הגילוי רצה\"ע הוא נושא עון הקדשים ואתהפכא כו'. וכנודע שי\"ג מדה\"ר רחום וחנון נושא עון כו' נמשכות מבחי' רצון העליון. והיינו כשיהיה גילוי רצון זה גם על בחי' מצח אהרן (כי זה לעומת זה מצח אשה זונה) משא\"כ כשאין הגילוי רצון אלא בחב\"ד דהיינו בשעת תפלה לבדה בשעת התבוננות ולא כל היום כולו:"],[114,"ביאור על הנ\"ל"],[114,"<b>הנה<\/b> תלת חללין דגלגלתא (הנזכר בזוהר ואתחנן דף רס\"ב א') הן תלת מוחין חב\"ד. ועל כל חלק מוח גשמי שורה אור השכל השייך למוח ההוא (וע' מק\"מ שם פי' המוחין הן חב\"ד דז\"א ואור המתלבש בהן היינו מחב\"ד דאימא) כנודע בחכמת הרפואה וכשם שהוא למטה באדם בגשמי' כך הוא למעלה בז\"א. והנה על המוחין וחב\"ד חופף הגולגלת. ובסוף הגלגלת היא מצחא. והמצח הוא כנגד מוח הדעת כי מוח הדעת הוא באמצע שמוח חכמה ומוח בינה הם מלפנים ומוח הדעת באחוריים באמצע ב' המוחין חו\"ב. ולכן הוא נגד המצח. והדעת הוא ענין התקשרות בפנימיות שכפי שנגמר בחו\"ב כן יתקיים. ולכן לעומתו מכוון המצח שהוא בחיצוניות המוחין ג\"כ בחינה זו דהיינו ההסכמה שהוסכם לקיים מה שרצה ע\"פ השכל. והוא רשימו שנשאר אחר הסתלקות המוחין כנ\"ל. (אך הדעת הוא בחי' פנימיות שבעוד החו\"ב מאירין בתוקפן הוא מקשרם וממשיכם בבחי' פנימיותו כו'. וע' בשער היחודים פ\"ז מבואר איך הדעת מאיר במצחא. וכ\"ה בע\"ח ובזהר הרקיע על האד\"ר גבי מצחא כו' ע\"ש):"],[114,"<b>והנה<\/b> אהרן הוא מז' רועים שממשיך רעותא דלבא כו'. אך באמת אח\"כ חולפת ועוברת שיש מחיצה של ברזל מפסקת רק לפעמים מציץ מן החרכים. היינו הרהורי תשובה. וא\"כ פעמים הוא כך ופעמים כך. והעצה להיות על מצחו תמיד דוקא כו' הוא ע\"י משה. תורה צוה לנו משה. בחר לנו אנשים כו'. כי הזלעו\"ז היא מחיצה של ברזל המפסקת הוא בחי' עמלק אם תגביה כנשר חוצפה וגסות הרוח עקשות ונצחנות כו' (כי עמלק הוא יודע רבונו ומכוון למרוד בו שהוא הקליפה שכנגד הדעת ואינו מניח את הדעת להתפשט במדות ע\"י חוצפה בלי טעם ודעת וכמ\"ש במ\"א בביאור שע\"פ זכור דעמלק. וע' בהרמ\"ז ר\"פ ויקהל מענין זה) כנודע. והמבטל בחינה זו הוא בחי' משה מ\"ה בטול והתורה היא למוד בבחי' בטול כו'. כי האומר אין לי אלא תורה כו'. אלא תורת ⟦פד,א⟧משה ולא תחללו כי אתה הוא קודם שנברא כו'. הוא ממש בלי שינוי. ולכאורה הרי המחשבה והדבור הם יש כו' אלא הבטול הוא בחכמה תתאה היא תושבע\"פ מעולם ועד עולם מלכות דיצירה עתיק לעשי' וחכמה דנוק' דעשי' היא התורה אשר לפנינו או\"ה כו':"],[114,"<b>וזהו<\/b> ענין ועשית ציץ לשון זכר הארה שנמשך מלמעלה. משא\"כ צצית לשון נקבה הוא ממטה למעלה בבחי' תפלה (עיין בטעמי מצות להרח\"ו פ' תצוה מצות ציץ כו'). אבל תורה היא מלמעלה למטה הבטול ולא תחללו. והוא הזלעו\"ז שכנגד עמלק. ועי\"ז נמשך להיות גילוי י\"ה בו\"ה היינו באהוי\"ר. וזהו שמשה הוא העושה הציץ. (וא\"ש לפמ\"ש הרח\"ו שם שהציץ הוא נמשך ממוחין דאבא שזהו בחי' משה. גם למעלה יותר במצח' דא\"א הנה מאיר שם בחי' דעת דא\"א וגם זה הוא בחי' משה ששרשו בחינת דעת עליון. וזהו המבטל לבחי' עמלק שהוא רק כנגד דעת תחתון שם הוא מסתיר ומכסה כו'. ולמעלה יותר הנה שם מ\"ה המאיר במצחא דא\"ק זהו ג\"כ בחי' משה וז\"ש ונחנו מה וכמ\"ש במ\"א ע\"פ משה ידבר כו'. ולכן נאמר לו דוקא ועשית ציץ שהיא הארה המאיר בבחי' מצחא הנ\"ל בבחי' דעת עליון שלמעלה מהשגה. וכן שם מ\"ה הבטול במציאות. שזהו דוקא המבטל בחי' עמלק כו' ועמ\"ש במ\"א בביאור ע\"פ יביאו לבוש מלכות מענין המן שהוא בחי' יש. ושהמנגד לבחי' זו הוא בטול רצון עיניו למטה ונחנו מה כו') וזהב טהור היינו ג\"כ בחי' רשפי אש משא\"כ כסף אהבה כמים כו'. ופתחת עליו פתוחי חותם. הנה פתוחי חותם הם אותיות דבינה יסוד דאימא שבה נצטיירו אותיות. כי הרי החכמה היא בחי' ברק ואין בה שום תמונה. רק בינה היא יש ושייך בה בחי' אותיות. כי אורייתא מחכמה נפקת ונתלבשה בבינה שהם תרין רעין כו'. וזהו ענין סופר וספור (עמ\"ש ע\"פ זה שמי. ולקמן ע\"פ אמר עם הספר) ואותיות אלו הם כדמות חותם החקוק בשעוה שנחקק שם אברהם עד\"מ ואינו מערך ומהות אברהם עצמו. וכך הרי להיות חכמה הנה כולם בחכמה עשית. שהחכמה בחי' עשי' נחשבת לגבי הקב\"ה. וכנודע מענין עסק התורה לשמה לשם התורה עצמה להיות תורה התלבשות א\"ס בחכמה לכן נק' חותם כחותם האותיות שהם על השעוה כו':"],[114,"<b>קדש<\/b> להוי\"ה. וארז\"ל קדש למ\"ד למטה הוי\"ה מלמעלה. דהנה ע\"י תורה נעשה או\"פ ותורתך בתוך מעי. וזהו פתוחי חותם הנ\"ל. וע\"י המצות נמשך מקיפין. וזהו ענין קדש למ\"ד כמאמר אשר קדשנו במצותיו. קדוש מובדל שהוא בחי' מקיף. והלמ\"ד הם ג' אורות מקיפין דכח\"ב (וכנודע מענין צלם אלקים. הצ' הוא ט\"ס דאו\"פ. והלמ\"ד הוא בחינת מקיף כו' עמ\"ש ע\"פ כי תצא) ואעפ\"כ כ\"ז הוא למטה שזהו מה שבאתערותא דלתתא ממטה למעלה נעשה אתעדל\"ע. והוי\"ה מלמעלה הוא בחי' שאין אתעדל\"ת מגעת שם. כי יש הוי\"ה הוי\"ה ופסיק טעמא בינייהו כי הוי\"ה באצילות יו\"ד וקש\"י רומז לכתר וחכמה. אך יש שם הוי\"ה הוא למעלה מהאצילות שהוא מקור להיות שם הוי\"ה שבאצי'. כי התהוות אצי' כשעלה ברצונו כו'. וזהו כתר דאצי' קוצו של יו\"ד. אך להיות רצון לרצון זה הוא מבחי' רעוא דכל רעוין והוא בחי' עתיק. וזהו ויקרא הוי\"ה הוי\"ה. פי' ויקרא שם הוי\"ה דאצילות את בחי' הוי\"ה שלפני האצי' (עיין לקמן סוף הדבור פי' בע\"א דהוי' הא' תקוני הראש כו' והכל למעלה ולפני י\"ג מדה\"ר ושני הפי' אמת) ובחי' זו היא אשר אין אתעדל\"ת מגעת שם. ולכן בחינת קדש למ\"ד נק' למטה לגבי בחי' שם הוי\"ה זה. ולכן נאמר גבי ציץ לרצון לפני הוי\"ה כלומר לפני שם הוי\"ה דאצי'. או לפני לשון פנימיות שהוא פנימיות ⟦פד,ב⟧שם הוי\"ה כו'."],[114,"וכמ\"ש גבי יוה\"כ לפני הוי\"ה תטהרו. ולכן שם הוא תמיד לרצון. וכן באדם בעבודת ה' הנה בבחי' מצחא שהוא חיצוניות הרצון בלי טעם רק מרשימו שנשאר אחר התפלה מהתבוננות בינה ודעת שהיה לו בשעת התפלה."],[114,"וזהו תמיד דוקא ר\"ל בכל היום כולו אף שאינו מתבונן ואף כשעוסק בצורכי העולם יהיה ע\"ד תורתו קבע ומלאכתו עראי דהיינו שיהיה עיקר המכוון כדי שיהיה פנאי לעסוק בתורה ולהתפלל ועל כוונה זו הולך בכל עניניו בבחי' זו שיהי' תמיד לרצון כו' והיינו ע\"י משה שהוא העושה הציץ להיות תמיד לרצון על בחינת מצחא. כי משה הוא מבחינת הדעת והוא ממשיך מבחינת רעוא דכל רעוין בבחינת מצחא המכוון כנגד מוח הדעת (כי הדעת עולה כו' שבו גילוי בחי' עתיקא וע' במ\"ש ע\"פ החלצו מאתכם) ובכל נפש יש מבחי' זו דמשה שהוא א' המיוחד משבעה רועים. אך והיה על מצח אהרן כי אהרן הוא אהבה רבה ובבחי' מצח שבו שהוא ההסכמה הנמשך מאהבה שם צ\"ל הציץ שיהיה תמיד לרצון בלי שינויים. משא\"כ במשה עצמו א\"צ לזה כי משה מלגאו שהוא הדעת עצמו שהוא בחי' פנימיות על כן לא שייך לומר ע\"ז בחי' הסכם וחיצוניות ורצון כ\"א בחי' דעת וחפץ."],[114,"וכנודע שחפץ הוא למעלה מהרצון רק שמשה הוא העושה הציץ על מצח אהרן. והוא הלעומת זה נגד בחי' עמלק שגם שם יש מצח. מצח אשה זונה גסות עקשות בבחי' יש דוקא שאע\"פ שיודע את רבונו מ\"מ כו' והציץ שמבחי' משה מבטל זה כנ\"ל:"],[114,"<b>ונשא<\/b> אהרן את עון הקדשים. בחי' נושא עון. (וכנ\"ל דשם הוי\"ה שבציץ הוא למעלה מבחי' קדש למ\"ד וע\"כ ונשא אהרן כו') שהם מי\"ג מכילין דרחמי דהיינו הארת הוי\"ה הב' להיות אל רחום וחנון כו' י\"ג מדה\"ר י\"ג ת\"ד. והוי\"ה הב' הם פאות הראש והוי\"ה הא' הם תקוני הראש (כמו ציץ על מצחא הוא מבחי' תקון הראש רעדכ\"ר) כו' כנודע. והיינו להיות הוי\"ה הוי\"ה ולהיות אצי' ע\"ס מי\"ג מכילין אבא יונק ממזל כו' וכ\"ז נמשך ע\"י הציץ שממשיך מבחי' רעדכ\"ר כתר שבכתר סתימא דכל סתימין:"],[115,"⟦פד,ב⟧<b>זכור את אשר עשה לך עמלק בדרך וגו'.<\/b> הנה כתיב מלחמה לה' בעמלק מדר דר שאין השם שלם ואין הכסא שלם עד שימחה זרעו של עמלק. ומלחמה זו היא בכל דור ודור בבחי' כל נפש מישראל. כי הנה בכל דור ודור ובכל יום ויום חייב אדם לראות א\"ע כאלו יצא ממצרים."],[115,"ולכן מזכירין יציאת מצרים בכל יום בוקר וערב. שבחי' יציאת מצרים הוא בכל נפש מישראל בכל יום ואחר יצ\"מ עומד' לנגדו מלחמ' עמלק כמ\"ש אשר עשה לך עמלק בדרך בצאתכם ממצרי' וכתי' אשר שם לו בדרך בעלותו ממצרים:"],[115,"<b>וביאור<\/b> ענין זה הנה כנסת ישראל שהיא מקור כל נשמות ישראל נק' בשם לבי. כמ\"ש לבבתני אחותי כלה שכמו שהלב הוא משכן וכלי קבול לרוח החיים העיקרי שמקור החיים וכללותו נמשך אל הלב אל תוכו ומתוכו מתפשט בכל הגוף."],[115,"ובו ועל ידו סובב הולך רוח החיים בכל הגוף כי החיות רצוא ושוב. כך מקור נשמות ישראל נק' בשם כנסת ישראל. על שם הקבוץ והכניסה שמתקבץ ומתאסף לתוכה עיקר החיות וההשפעה מבחי' ישראל דלעילא בחי' כי שרית עם אלהים וגו' היא בחי' הארת שם הוי\"ה שלמעלה מבחי' אלהים כמ\"ש ועל דמות הכסא דמות כמראה אדם וגו':"],[115,"<b>והנה<\/b> בכל נשמה בפרט היא היא נקודת הלב ממש שבכל נפש מישראל שבטבעה היא כשלהבת העולה מאליה לדבקה בו ית'. והיא היא בחי' עצמות הנפש ומהותה שיסודתה בהררי קדש חלק אלוה ממעל ממש. וכל חפצה ותשוקתה ליבטל וליכלל באור הוי\"ה ⟦פד,ג⟧וממנה מתפשטות כחות הנפש שכל ומדות כו'. עד שמתפשטת במחשבה דבור ומעשה שהם בחי' לבושין שאינן ממהות הנפש כנודע. וגם השכל ומדות שהם ממהות הנפש הם מתלבשין בלבושי השכל ומדות שבנפש הבהמית שמנוגה טוב ורע כו'."],[115,"והנה בחי' נקודה זו של עצמות הנפש ומהותה הגם שהיא שוה בכל נפש מישראל מ\"מ אינה מתגלה בשוה. אך על כל איזה גילוי שיהיה נאמר לבבתני באחת מעיניך כלומר אפי' באחת מאיזה בחי' המתגלית בכל נפש כי מוכרח הוא להיות איזה גילוי הארה בכל נפש וגילוי זה הוא משרש הנפש שהיא בחי' לב. ולכן נאמר לבבתני וגו'."],[115,"והנה ענין גלות מצרים הוא שהיה אז גילוי בחי' נקודת הלב בגלות שהיא בחי' קטנות בחי' אמונה לבדה. וכמ\"ש ויאמן העם וישראל מאמינים בני מאמינים. אך אח\"כ כתיב אעלה אתכם מעני מצרים אל ארץ טובה ורחבה שהיא הרחבת הדעת."],[115,"וכמ\"ש וידעתם כי אני ה' שבהתרחבות הדעת תהיה הרחבת גילוי נקודה זו ביתר שאת שתתלהב ותתלהט נקודת לבו עד שתתגלה ותתפשט בכל כחות הנפש בבחי' פנימיות. משא\"כ באמונה לבדה אינה אלא בחינת מקיף והרחבת הדעת הוא כמארז\"ל כל המאריך באחד כו'. דהיינו להאריך ולהרחיב בדעתו ובעומק לבו עד מקום שיד שכלו ותבונתו מגעת איך שאני הוי\"ה לא שניתי ממש כמו קודם בריאת העולם. כי גם עתה בשמים ממעל ועל הארץ מתחת אין עוד כי כולא קמיה כלא ממש חשיבי כי רק הודו וזיוו של שמו לבדו מאיר על הארץ ושמים כו'."],[115,"ואי לזאת הכל בטלים אצלו ית' ואליו תכסוף נפש כל חי והאופנים וחיות הקדש ברעש גדול וכו' וכל מה שיאריך בזה וכיוצא בזה ברוחב ובעומק בעיני שכלו ולבבו יבין שלא יהיה לו חפץ ורצון אחר בלתי לה' לבדו וכמ\"ש מי לי בשמים ועמך לא חפצתי בארץ רק אליו לבדו תכסוף נפשו לדבקה בו ית'."],[115,"ועי\"ז ואהבת את הוי\"ה שיהא אלהיך בכל לבבך. פי' שיהא הלב משכן וכלי קבול ממולא מבחינת גילוי הוי\"ה. שיהא שורה ומתגלה בקרב איש ולב עמוק בהתלהבות והתלהטות רשפי אש עזה ולעמוד נגד כל מונע ולהפקיר א\"ע ולהשליך נפשו ורצונו שמנפש הבהמית מנגד רק ישים אליו לבו מנקודת פנימיותו."],[115,"וזהו בחי' כנסת ישראל דלעילא כי ישראל דלעילא היא בחי' הוי\"ה וכנס\"י היא המקבלת וכונסת לתוכה החיות וההשפעה מבחי' זו כו'. ובכל נפשך שיהא גילוי זה בכל כחות והתפשטות הנפש בכל ג' מיני לבושין מחשבה דבור ומעשה."],[115,"והיינו ע\"י התלבשות מחשבה עליונה במחשבתו כו' ודבור בדבור כו'. וכמ\"ש והיו הדברים האלה אשר אנכי מי שאנכי מצוך כו' ודברת בם בשבתך וכו' בם ממש שתהא מחשבה עליונה ודבור עליון מלובשים ממש בתוך מחשבתו ודבורו והגם כי לא מחשבותי מחשבותיכם כתיב ואיך תהיה מלובשת ממש מחשבה במחשבה כו'. אך סיפא דקרא ולא דרכיכם דרכי. כלומר אימתי כי לא מחשבותי כו' בזמן שלא דרכיכם דרכי. אבל כשדרכיכם דרכי דהיינו ע\"י שישים אל לבו בהתבוננות והעמקת הדעת בה' אחד כו' שזו היא דרך הוי\"ה והמשכת גילוי ה' אחד בואהבת הנה עי\"ז תהיינה גם המשכת מחשבותי במחשבותיכם בהתלבשות מחשבה במחשבה כו':"],[115,"<b>והנה<\/b> עיקר גילוי זה של נקודת הלב בק\"ש ושיהיה גילוי הוי\"ה אחד בלבו הוא ואהבת את הוי\"ה שיהיה גילוי בחי' אהבה בתענוגים שהיא אהבה עליונה העולה על כולנה להתענג על הוי\"ה וכו'. כמ\"ש בזהר אכלתי יערי עם דבשי בק\"ש."],[115,"ודבשי היינו מתיקות ותענוג כי מאחר שיהיה גילוי הוי\"ה אחד בלבו שאין עוד מלבדו ואין חיים אחרים ותענוג אחר כלל רק כי הוא חייך שהוא ⟦פד,ד⟧מקור החיים ומקור התענוגים."],[115,"ולזאת תהיה אהבתו להוי\"ה כאדם האוהב את חייו ממש שאהבה זו היא מעצמות הנפש. כך תהיה אהבת ה' תקועה בלבו. ולזאת יתענג על ה' מקור התענוגים ושש ושמח בעבודתו כי קרבת אלהים טוב לו. וכמ\"ש טעמו וראו כי טוב ה'. וזהו אל ארץ טובה ורחבה אל ארץ זבת חלב ודבש דהיינו שיהי' דבש בחי' אכלתי יערי עם דבשי בקיום הק\"ש בגילוי הוי\"ה אחד ואהבת אהבה בתענוגי' ע\"י ארץ טובה ורחבה היא הרחבת הדעת כו':"],[115,"<b>אך<\/b> כיצד יגיע אדם לבחי' גילוי בחי' זו מאחר שהיה תחלה בבחי' גלות מצרים שנקודת הלב היא בבחי' קטנות ומסותרת ומכוסה בלבושי הנפש הבהמית למשוך אחר חיי הגוף ותענוגיו שהם הם היו אצלו חיים ותענוגים גמורים כל חד לפום מאי דידע בנפשיה."],[115,"ואיך יהפך לבו מן הקצה אל הקצה ומן ההפך אל ההפך לגמרי להיות אהבת ה' תקועה בלבו כחייו ממש. הנה על זה נאמר ויסב אלהים את העם דרך המדבר ים סוף שלא נסעו ממצרים מיד לארץ ישראל אלא דרך המדבר."],[115,"וכתיב לכתך אחרי במדבר שבחי' המדבר הוא בחינת אחרי ה'. והענין כי הנה יש בקדושה בחי' פנים ואחור. כמ\"ש וראית את אחורי וגו'. וכתיב מגילה עפה כתובה פנים ואחור וגו'. וכנודע ליודעי חן שיש שמות שהן בבחי' אחוריים והם שמות דקדושה."],[115,"וכך יש בנפש האלהית פנים ואחור. פנים הוא בחי' פנימיות הלב ששורה ומתגלה בו בחי' הוי\"ה אחד בגילוי ממש שזהו חיותו וקיומו והוא הוא שעשועיו ותענוגיו וחדות ה' ממש היא מעוזו."],[115,"ובחי' אחור הוא שאינו מתגלה בו כל כך בבחי' חיות ותענוג רק שהוא מכריח וכופה את לבו להטות לבבו אליו יתברך ולאהבה אותו. וזהו לעשותה לאהבה שהיא אהבה העשוייה בלב ע\"י התבוננות ג\"כ שמתבונן ומעמיק דעת בה' אחד ואיך שהוא חיי החיים ומקור התענוגים אשר ע\"כ יאתה כו'."],[115,"ואעפ\"כ לא מפני זה תהיה אהבה זו לבדה ממלא כל תוכיות הלב שלא להיות שום חפץ ורצון אחר כלל אלא שאהבה זו היא המושלת בלב ע\"י המוח השליט על הלב שליט דוקא והוא בחי' אתכפייא סטרא אחרא ולא בחי' אתהפכא כנ\"ל."],[115,"והמשכיל יבין שיש בזה כמה מדרגות זו למעלה מזו. דהיינו שהגם שיעורר את האהבה בלבו עד שתחפץ באמת להתפשט מלבושי נוגה להיות בכל לבבך ובכל נפשך התלבשות מחשבה במחשבה כנ\"ל. עם כל זה עדיין לא נתפשטה מלבושי נוגה לגמרי למאוס ברע רק שע\"י התבוננות השכל מכריח ומחייב את הנפש לצאת מנרתקה עד שלבושי נוגה הם אצלו בעת ההיא בבחי' שינה שהרע כפוף ובטל אצלו ונק' בכל לבבך בשני יצריך ביצר טוב באהבה הטבעית שבשרש נפשו. וביצר הרע לאתכפייא סט\"א כו'. אבל עדיין אינו בבחי' לאתהפכא חשוכא לנהורא כנ\"ל. דהיינו שאין לו אלא לב א' כו'."],[115,"והנה ארז\"ל שאמרו השבטים ליעקב כשם שאין בלבך אלא אחד כן אין בלבנו אלא וכו' כי יעקב הוא ישראל שהוא בחי' ומדרגה העליונה שאין לו אלא לב אחד ומתענג על הוי\"ה כנ\"ל."],[115,"וכך השבטים שהם כללות הנשמות עד סוף כל הדורות גם בחי' הבינונים שהם למטה ממדרגה זו אעפ\"כ אין בלבנו אלא אחד. והיינו בחינת אתכפייא שעי\"ז נעשה ג\"כ גילוי הוי\"ה אחד בכל לבבך ובכל נפשך והתלבשות מחשבה במחשבה כנ\"ל."],[115,"והיא היא הדרך שיבור לו האדם להתבונן בעומק שכלו ותבונתו בה' אחד כפי אשר תוכל נפשו שאת שעי\"ז יכוף ויטה לבבו לאהבה את ה' ולעמוד נגד כל מונע בשבירת התאוות ובכבישתן על ידי המוח השולט על הלב לאכפיי' סט\"א ומזה יעלה ויבא לבחי' אתהפכא כנ\"ל."],[115,"ויהיה ⟦פה,א⟧גלוי פנימיות נקודת הלב ויאר ה' פניו וגו'. וזהו ואזניך תשמענה דבר מאחריך לאמר זה הדרך וגו' שמבחי' אחוריים דקדושה נמשך לאדם שיהא לו דרך ומבוא לגלוי הוי' בפנימיות ולכן נק' ק\"ש קבלת עול מלכות שמים עול דוקא שהוא בחי' אתכפיי' ובחי' אחרי ה' ילכו כאריה ישאג וגו':"],[115,"<b>והנה<\/b> עול זה הוא קבלת מדת מלכותו ית' מלכות שמים. כי הנה נודע כי אין מלך בלא עם עוממות כו'. ואין זה אלא כמ\"ש להודיע לבני האדם גבורותיו וכבוד הדר מלכותו. שלהיות כבוד הדר מלכותו הן הן גבורותיו וצמצומים רבים ועצומים להעלים ולהסתיר אוא\"ס ב\"ה שיהיה נראה דבר יש ונפרד ועם עוממות כו' כדי שיהי' שמו נק' מלך עליהם כי באמת כולא קמיה כלא חשיב ואתערותא דלעילא זו צריך להיות באתערותא דלתתא ג\"כ בחי' צמצומים והסתלקות והן הם בחי' גבורת האדם להתגבר נגד כל מונע בסור מרע ולא תתורו אחרי לבבכם עוצם עיניו וגו' ובועשה טוב אינו דומה שונה פרקו מאה פעמים למאה פעמים ואחד ונק' עובד אלהים מפני אחת היתירה על הרגילות כו'. וע\"י זה מקיים שום תשים עליך מלך וגו':"],[115,"<b>והנה<\/b> ע\"י כל זה נעשה השם שלם והכסא שלם. כי הנה השם הוא בחי' הוי\"ה ב\"ה דהיינו י\"ה הוא למעלה מן ההשתלשלות ונק' עלמא דאתכסייא חכים ולא בחכמה ידיעא מבין ולא כו'. ו\"ה הוא בחי' עלמא דאתגלייא. כי הוא\"ו היא המשכה להיות ה\"א שהוא עלמא דאתגלייא."],[115,"והנה כתיב את השמים ואת הארץ אני מלא נאם ה' שמה שהוא מלא את השמים ואת הארץ הוא נאם ה' שהוא בחי' דבר ה'. וזהו ע\"י אתערותא דלתתא את ה' האמרת אתה עשית אותו אומר כנ\"ל."],[115,"והיינו ע\"י גילוי הוי\"ה אחד בכל לבבך ובכל נפשך התלבשות מחשבה כו'. והוא גלוי הוי\"ה למטה בלב כמו למעלה במוח כי מתחלה היה המוח שליט על הלב על דייקא. ואח\"כ מתפשט ויורד הדעת שבמוח אל פנימיות הלב ותוכיותו להיות תוכו ותוך תוכו ופנימיותו רצוף אהבה לה' לבדו בחי' אתהפכא כו' ובאתערותא זו דלתתא אתערותא דלעילא שם י\"ה שיורד ומתפשט מהעלם אל הגילוי לעלמין דאתגלייא הנמשכים מבחי' ו\"ה וזהו השם שלם."],[115,"וענין הכסא שלם הוא בחי' כסא מלכותו שום תשים עליך מלך כו'. וכמ\"ש מושיב מלכים לכסא. וכתיב וישב ה' מלך לעולם כנ\"ל. ובחי' ישיבה כלפי מעלה היא בחי' השפלה והורדה ממדרגה למדרגה כמו שע\"י ישיבת האדם בגשמיות ע\"ד משל משפיל אחוריו כנ\"ל. כך הוא בחי' ירידת והמשכת גלוי הוי\"ה לבחי' אחוריים ע\"י שכופה לבו כנ\"ל. וקיום כל מצות המלך שהם גשמיות ונק' בשם בחי' אחוריים וכמ\"ש מגילה עפה כתובה פנים ואחור וגו'. ואעפ\"כ הן הם רמ\"ח אברין דמלכא כאדם האוחז בחבירו באחד מאבריו ומושכו וממשיכו כנ\"ל:"],[115,"<b>אך<\/b> הנה זה לעומת זה עשה אלקים שיש פנים ואחור בקליפה ג\"כ כמו בקדושה ויניקתם ואחיזתם באחוריים דקדושה. והנה ראשית גוים עמלק שהוא בחי' עורף דקליפה. ולכן נק' עמלק ע\"ם מל\"ק שמליקה מן העורף."],[115,"וביאור הענין כי מעלת ישראל כי עם קשה עורף הוא שלכן בקש משה וסלחת שהם מבחי' עורף דקדושה שיש להם התגברות בחי' אחרי הוי\"ה ילכו שיכולים לכוף את הלב בשבירת התאוות וכבישתן ולעמוד נגד כל מונע בהתגברות ובחוזק ונק' בחי' עורף שהעורף הוא המחבר ומקשר המוחין שבראש להיות להם התפשטות בגוף שעי\"ז נמשך אל הלב להטות לבב האיש ולהפכו מן ההפוך אל ההפוך לגמרי מאחר שמגילוי בחי' אחרי ה' יבא אח\"כ ⟦פה,ב⟧לגילוי בחי' פנימיות כו' וזה לעומת זה הוא בחי' עמלק הוא עורף הקשה שבקליפה דהיינו שגם אם לבבו יבין בעבודת ה' שכך יאתה כו' לא די שאינו מכריח את לבו לכופו ולהטותו לאהבת ה' אלא אף גם זאת שעושה ההפוך לגמרי. וזהו ויזנב בך כל הנחשלים אחריך דייקא בחי' אחוריים דקדושה."],[115,"והנה זו היא רק בחי' חוצפה בלי טעם ובלי דעת שעושה ההפוך מן הדעת וזהו לשון עמלק ע\"ם מל\"ק שהוא בחי' מליקה וכריתה ממול העורף דקדושה שהוא המכרית ומפסיק הקשר וההתחברות שבין הראש ומוחין להתפשטותם בלב."],[115,"וכך היה עמלק שידע וראה את כל הנסים שנעשו לישראל ואעפ\"כ מלאו לבו לגשת אתם למלחמה. משא\"כ פרעה אמר לא ידעתי את ה' ובמופתים היה לב פרעה נכנע לולי כי ה' אמר כי אני הכבדתי את לבו וזה היה עונשו כו' כמבואר בספרים. וכן כל העכו\"ם הקליפות מסתירים ומכסים מהם קדושת ה' מפני שמשוקעים בקליפות ההם. אבל ראשית גוים עמלק וזרעו של עמלק פי' הזריעה שלו שזרעה בישראל להיות להם בחי' זו וצריך להיות מלחמה בעמלק מדור דור שבכל דור יש בחי' יציאת מצרים וצריך ללכת תחלה בבחי' אחרי ה'."],[115,"והנה בזמן הגלות שההילוך הוא בבחי' אחרי ה' כתיב מחה אמחה את זכר עמלק. מלחמה להוי\"ה בעמלק שלא לאדם המלחמה שיוכל לכובשו שיהי' גילוי והתפעלות פנימית נקודת הלב אלא לה' המלחמה ואין כח האדם אלא ביגיעת הנפש בהתבוננות בה' אחד כפי אשר תוכל נפשו שאת ויבקש רחמים מה' שאותה אנו מבקשים בכל תפלת שמ\"ע ברוך אתה וכו' ברוך אתה כו' כנודע. אך והיה בהניח כו' בארץ כו'. דהיינו כשיגיע לבחי' ארץ טובה ורחבה וחלב ודבש בחי' אהבה בתענוגים אזי תמחה מעצמך את זכר עמלק ולא תשכח. שלא יהיה בבחי' שכחה שהיא בחי' אחוריים כו' ואין יניקתם ואחיזתם אלא בבחי' אחוריים. וכמ\"ש כל הנחשלים אחריך וגו'. והיינו בדרך בצאתכם ממצרים דייקא. משא\"כ בהניח ה' אלהיך לך מכל אויביך מסביב בארץ וגו' שהוא בחינת פנימיות:"],[116,"<b>ביאור אין השם שלם<\/b>"],[116,"<b>ביאור<\/b> הדברים אין השם שלם ואין הכסא שלם כו' הנה שם הוי\"ה הוא בז\"א וכסא במל' ולהיות בחי' הוי\"ה שלם היינו שיהיה התחלקות מוחין חו\"ב ואח\"כ הדעת מתחלק לבחי' חו\"ג הוא מבחי' קוצא דשערי דא\"א שיורד עד כתפין דז\"א מאחוריו שהוא המחלק כו'."],[116,"והנה זהו בחי' ו\"ק ו\"ה מל' דז\"א אף הוא מפרצוף דז\"א עצמו כנודע בכוונת הלולב והאתרוג כו' וכסא הוא פרצוף המלכות ונק' ו\"ה מוחין הגם שהוא מדות חו\"ג אברהם ויצחק כו' רק יש מדות שהם טבעיים והם בחי' קטנות שיכול להיות כל היום ויש שהוא בגדלות המוחין כמו בשעת התפלה שלבו מתלהט בהתבוננותו כו'."],[116,"והנה מלכות נק' לב לבבתני כו' שהוא עיקר החיות והוא בנפש למטה בחי' נקודת הלב ממש שהוא עצמיות מהות הנפש משא\"כ התפשטות כח הנפש בלבושים מחדו\"מ כו' הם מבי\"ע שאינם אלהו' גם שהם בחי' עה\"ד טו\"ר כו'."],[116,"והנה עיקר גילוי הלב הוא להיות בבחי' פנימיו' שתקבל מבחי' ישראל דלעילא פב\"פ כי הוא חייך מקור החיים מקור התענוגים ארץ זבת חלב ודבש יערי עם דבשי להתענג על ה'. אך בגלות מצרים הוא בכל יום שבכל לילה יורדת לבי\"ע ותתן טרף לביתה ונשארת ⟦פה,ג⟧הנקודה תחת היסוד ואח\"כ חוזרת ועולה ומתחלה נעשה פרצוף אב\"א ואח\"כ פב\"פ וזהו דרך המדבר אחרי הוי\"ה שצ\"ל תחלה אב\"א והוא ענין המשכ' המוחין בשלימות אך שאינו אלא דרך אחוריים."],[116,"ובאור זה בנפש האדם המשכלת ומתבוננת איך שכך יאתה והשכל מכריח ומחייב את האהבה שהרי מצד עצמו עומד על עמדו רק שהמוח שליט כו' לאכפיי' וכו'. בכל לבבך בשני יצריך ובכל נפשך כו' שיוכל להיות עבודה תמה והמשכת המקיפים אשר קדשנו במצותיו כי מצות המלך הוא ואעפ\"כ כל עבודתו הוא בבחינת חיוב והכרח השכל שעדיין אין התענוג נרגש להיות כו'."],[116,"והנה מבחינת אב\"א נעשה אח\"כ פב\"פ כי להיות המשכת המוחין הוא מבחי' קוצא דשערי דא\"א יאר פניו כו' ובבחי' פנימיות נעשה השם שלם וכו'. וכסא השם שלם כו' וכסא הוא מלכות בנין המל' מהגבורות שאין מלך בלא עם שלפי האמת אין על מי למלוך אלא שכך עלה ברצונו להיות צמצום ולהיות נראה ליש כו'."],[116,"וצ\"ל העלאת מ\"נ ע\"י צמצום ג\"כ בחי' גבורות עובד אלהים שונה פרקו כו' שהוא בחי' כסא וישיבה שמשפיל בחי' אחוריים כו'. וכן התורה היא כתובה פנים ואחור שיש פנימית וחיצוניות גשמית המצוה היא חיצונית כמו ד' פרשיות שבתפילין על קלף והפנימית הוא חו\"ב הרמוזים בקדש כו' וכן בסכך הסוכה הסכך הוא חיצונית ופנימית הוא המקיפין והכלל שהחיצוני' הוא מה שאין בזה תענוג ובפנימית מתגלה התענוג כו' עולמך תראה בחייך כו' וזה נמשך מזה שמאב\"א נמשך להיות פב\"פ כו'."],[116,"וזהו שמצא משה מעלת ישראל עם קשה עורף וסלחת כי חטא העם חטאה גדולה ולא היו ראויים לסליחה מצד המשכת והשתלשלות המדות רק משה המשיך מלמעלה בחי' ארך אפים כו' אך למה הם ראוים להמשכה זו לזה אמר משה עם קשה עורף הוא שיש להם קשות וחזוק והתגברות במדות עורף כו' ושם הוא בחי' קוצא דשערי מא\"א שעי\"ז יומשך י\"ג מדות דא\"א כנ\"ל."],[116,"והנה זלעו\"ז היא בחי' עמלק ע\"ם מל\"ק כו' ראשית גוים עמלק שכל עכו\"ם הם מז' ימי הבנין והוא בדעת דאחורי כתפין. אך פרעה היה מדעת העליון והוא היה בדעת התחתון. והנה המשכת המוחין במדות הוא דרך בחינת הצואר שמשם מצרים מצר הגרון וכ\"ז הוא בחינת אחוריים פרעה הוא אחורי עורף שלכן נק' ירידת המוחין בגרון בשם ירידה. והמשכתם משם ולמטה בגוף נק' עליי' כמ\"ש ויוסף הורד מצרימה וכתיב אנכי ארד עמך מצרימה ואנכי אעלך כו' ומה הוא עלייתם היינו בהתפשטותם, בהגוף ארץ טובה ורחבה (כמ\"ש בלק\"ת פ' וישב עמש\"ל בביאור ע\"פ לכן אמור פ' וארא) והיינו לפי שהגרון הוא בחי' אחוריים ולכן אינו תלוי במה שהמקום גבוה כו'. והנה המשכת דרך אחוריים שם עומד עמלק הוא בחי' הקשיות להפוך יודע רבונו כו' משא\"כ פרעה לא ידעתי כו' ובמופתים הי' בטל לולי כי אנכי הכבדתי כו' אבל עמלק ידע כל הנסים."],[116,"והנה זלע\"ז נגד אחוריי' דקדוש' חוזק התגברות מחמת חיוב השכל וזה להפך התגברות נגד השכל הגם שהשכל מחייב והוא בחוצפה בלי טעם ודעת וזהו כל הנחשלים אחריך שהם בבחי' אחוריים כו' ומלחמה לה' מדר כו' שבכל יום הוא יציאת מצרים וצ\"ל מלחמה זו בכ\"י. והנה בזמן הגלו' מחה אמחה כו' מלחמה להוי\"ה היינו בחי' אחוריים אבל והיה בהניח כו' אל ארץ טובה ורחבה אהבה בתענוגים תמחה מעצמך כו' וד\"ל:"],[117,"⟦פה,ג⟧<b>שמאלו תחת לראשי וימינו תחבקני.<\/b> הנה בענין העולמות כן דרך השם לבני ישראל עם קרובו כשמתעורר למעלה בחי' שמאל דוחה מחמת מעשה התחתונים ויהי להם למושיע וגורם שאדרבה עי\"ז יהיה להם נשיאות ראש."],[117,"וזהו כי תשא את ראש בנ\"י לפקודיהם פי' על ידי איזה פקידה שיפקד עליהם לרעה ח\"ו וכל' רז\"ל אין לך כל פקידה שאין בה מעון העגל. הנה עי\"ז אדרבה תשא את ראש בנ\"י כי בחי' השמאל דוחה אינה דחי' לגמרי ח\"ו אלא וימין מקרבת. וזהו וימינו תחבקני אשר כי יפול לא יוטל ח\"ו. ולהבין ענין זה בעבודת ה' כתיב הקל קול יעקב ב' פעמים קול א' בלא וא\"ו וא' בוא\"ו כי ב' קולות הם א' לתורה וא' לתפלה."],[117,"והנה פעם אמרו דתלמוד תורה כנגד כולן ופעם הפליגו מאד בשבח מעלת התפלה ושהיא כנגד הקרבנות. אך שניהם אמת כי הם חלוקים בענינים שהתפלה היא בבחי' מלמטה למעלה והתורה היא בבחי' מלמעלה למטה. ובאור ענין זה כי הנה ענין התפלה היא קיום המצות ק\"ש ואהבת וגו' כמ\"ש במ\"א ועד\"ז תקנו ג\"כ כל סדר התפל' קודם ק\"ש כדי שיקבל עליו בק\"ש ואהבת באמת וכמשי\"ת לקמן."],[117,"והנה הדרך המביאה את האדם לידי אהבה זו היא מ\"ש ראה נתתי לפניך היום את החיים ואת הטוב ואת המות ואת הרע ובחרת בחיים. לאהבה את ה' אלקיך כי הוא חייך וגו'. כי בכל דבר בעוה\"ז יש גשמיות ורוחניות והרוחניות והחיות אלהי הוא חיים וטוב והגשמי' הוא מות ורע שהוא כלה ונפסד."],[117,"ומזה יראה האדם שכשם שהגשמיות כל דבר בטל לגבי הרוחני' המחייהו וכן באדם עצמו הנה הגוף טפל ובטל לגבי הרוחניו' והחיו' שבו ⟦פה,ד⟧לכן אוהב את חיי נפשו במאד מאד. כן ויותר מכן יש לאדם לאהוב את ה' כאשר יסתכל בעין שכלו בראי' חושית כי הוא חייך ממש שהוא מקור וחיי החיים."],[117,"וזהו ענין וכל צבא השמים לך משתחוים כמארז\"ל שהחמה שוקעת במערב ומשתחוה לקונה וכן כל המזלות בעבור שרואים ומשיגים חיותם וקיומם המהוה ומחי' אותם ומקיימם. וזהו ראה נתתי לפניך וגו' שזה יראה האדם לעינים בראי' חושיי' שהרי רואה חיותו וקיומו וכן רואה ההשתחואה של צבא השמים ועי\"ז יבא למדרגת ואהבת את ה' אלהיך בכל לבבך בשני יצריך שאפי' היצה\"ר הוא נכנע ובטל נגד אהבת ה' וכמו שארז\"ל בטל רצונך מפני רצונו פי' לפי שאהבה זו הבאה מחמת ראי' חושיית כזו אין ערוך אליה ולא נמצא דוגמתה כלל בענינים גשמים וכמאמר מי ידמה לך ומי ישוה לך ומי יערך לך."],[117,"ובחי' ראי' זו צריך להיות נצחית ותמידי' ומי שאינו מסתכל בזה תמיד עליו נאמר והכסיל בחושך הולך. מה שאין כן החכם עיניו בראשו שיהיה תמיד לנגד עיניו חיותו וקיומו מאור אין סוף ב\"ה וככה תהי' אהבת הוי\"ה תקועה בלבו תמיד ותהיה נפשו קשורה באלהי' חיים קשר נפלא וחזק לעד ולעולמי עולמים."],[117,"וזהו ענין חילא דתיובתא יתיר ותדיר הנזכר בזה\"ק לתקון פגם הברית כי ברית הוא ענין התקשרות ובקדושה הוא ענין התקשרות נפשו בשרשו וחיותו ובהפך זלע\"ז הוא ההתקשרות בתאוות עוה\"ז ותענוגות בנ\"א ולכן התיקון הוא להפך לבו מהפוך להפוך מן הקצה אל הקצה ממש לדבקה נפשו בשרשו וחיותו הנמשך ממנו ית' שהוא אל חי וקים בחי' ברית המקשר וממשיך החיות מבחי' סוכ\"ע להיות ממכ\"ע להחיות נפש כל חי ורוח כל בשר איש שתהי' דבקות אמתי ⟦פו,א⟧ותמידי וזהו יתיר ותדיר ולא די בזה שהוא מעורר את האהבה בשעת התפלה וכיו\"ב ואח\"כ חולפת ועוברת כדכתיב קרוב ה' לכל קוראיו לכל אשר יקראוהו באמת ושפת אמת תכון לעד כתי' משא\"כ ועד ארגיעה כו':"],[117,"<b>והנה<\/b> בחי' ראי' חושיית זו המביא' לידי אהבה זו נמשך לישראל מלמע' כמ\"ש וה' עליהם יראה ויצא כברק חצו זה הוא המשכה והארה שמאיר ובא לישראל להיות עליהם יראה לראות באור ה' חיי החיים ית' בראי' חושית ולדבקה בו וע\"ד זה תקנו לפני ק\"ש כל סדר התפלה וברכות השחר ברוך אתה כו' שאנו מבקשי' שיאיר לנו אור הוי' בהתגלות כדי שיקבל עליו בק\"ש מצות ואהבת באמת וזהו הוי' אלהינו. כי הנה ארז\"ל גדולים ישראל יותר ממלאכים שממתינים לומ' קדוש עד שישראל אומרי' למטה."],[117,"ולכאורה אינו מובן שיהיה יתרון זה לאדם בהיותו בעוה\"ז מלובש בגוף גשמי ואין לך אדם שאין נופלים לו מחשבות זרות עכ\"פ מחשבה שהיא זרה אצלו לפי\"ע הגדול לפי גדלו והקטן לפי קטנו והמלאכי' כולם עומדים ברום עולם מופשטים מחומר הגוף הגשמי וכולם עושים באימה וביראה רצון קונם מו' ימ\"ב בלי שום בטול והפסק אפי' רגע אחד:"],[117,"<b>אך<\/b> הנה המלאכים אין אומרים קדוש מצד עצמם רק מצד החיות המתפשט ונמשך בהם רק שהם אינם תופסים מקום לפני חיות אלהות השורה בתוכם והמשכות והתפשטות החיות שבהם הוא הוא האומר והעושה בהם כרצונו באין מונע."],[117,"ולכן כתיב בהגר ותקרא שם ה' הדובר אליה והוא המלאך שדיבר עמה וכן במלאכים שבאו אצל אברהם כתיב ויאמר שוב אשוב אליך ובשליחותו של מקום אמר לו כן כאלו אמר הקב\"ה בכבודו ובעצמו והיינו לפי שאין תופסים מקום נגד חיות אלהות המדבר בהם ואינם רק מעבר שעל ידיהם יומשך הדבור והפעולה למטה. והמשכה והשפעה זו היא דרך השתלשלות כמ\"ש וקרא זא\"ז ואמר קדוש ותרגומו ומקבלין דין מן דין אלא שבלשון מקרא נאמר אל המשפיעים שקורא וממשיך שפע זה לזה ובלשון תרגום נאמר על המקבל בחי' נוקבא."],[117,"והנה מצד החיות לא שייך לומר על הקב\"ה שהוא קדוש ומובדל דמשמע שיש עוד דבר נפרד ויש זולתו אלא שהוא קדוש ומובדל ממנו. ובאמת אומרים איה מקום כבודו כו' כמ\"ש במ\"א עד שנמשך החיות למטה לישראל המלובשים בגוף הגשמי שהוא דבר נפרד ויש בפ\"ע ומכסה ומסתיר קדושת החיות ואז ע\"י אתעדל\"ת בביטול גוף הגשמי לגבי הרוחניות ומקור החיות שבו בהגלות אור ה' למטה במה שאומרים ברוך אתה וכו' ומצד הגוף שייך לומר אליו ית' שהוא קדוש ומובדל ולכן גם המלאכים אומרי' קדוש וגו' שהארה והמשכה זו שישראל ממשיכים למטה עוברת דרך המלאכים וג' פעמים קדוש כנגד ג' צמצומים שיש דרך כלל עד שיומשך ויתפשט למטה הארה זו להיות נק' בשם ה' צבאות שבכל אלו הצמצומים הוא קדוש ומובדל."],[117,"והנה הארה והמשכה שמתפשט למט' בישראל לבטל הגוף אליו ית' יש לו יתרון על האור וחיות המתפשט במלאכים כיתרון אור הבא מן החשך שיש לה תוספת אורה ושמחה שגם הגוף נעשה מרכבה ליחודו ית'."],[117,"ולכן אומרים ה' אלהינו שלנו ממש כמו ע\"ד משל האדם מתפאר את עצמו בשלו אף בבחי' רגל שבו משא\"כ בשל אחרים אינו מתפאר אפי' ביד שהיא חשובה יותר כיון שאינו שלו כך הנה הארה והמשכה זו אף שהיא רק זיו והארה בעלמא שירדה מטה מטה והיא בחי' רגל לעיקר האור של מעלה שאינה יכולה להתפשט בתוך הגוף שאותו האור נק' בחי' ראש לגבי זה מ\"מ הנה אלהינו זה ממש שלנו כדכתיב בנים אתם לה' אלהיכם."],[117,"וברא כרעא דאבוה שנעשה כמו בחי' רגל לגבי האדם שהוא עצמית אחד ולכן אמרו רז\"ל בטל רצונך מפני רצונו דהיינו להיות בחי' רגל אצל הקב\"ה ולהיות בטל אצלו ולעשו' רצונו שכמו שהרג' בטל לגבי האד' שלכל אשר יחפוץ יטנו ואין לה רצון וחפץ אחר כלל."],[117,"וזהו שאו' בתחלת ברכות השחר ⟦פו,ב⟧הנותן לשכוי בינה להבחין בין יום ובין לילה כי התעוררות בחי' האהבה והיראה שבא לאדם אינם מצד עצמם כ\"א שבא לו מלמעלה ע\"י בחי' שכוי רוחניות שיש למעלה שהוא המבחין בין יום ובין לילה דהיינו בין חסדים לגבורות ע\"י המשכת בינה עלאה וכן עד\"ז כל שאר הברכות וכל סדר התפלה למתבונן בהם ומשכיל על דבר ימצא. אך כדי להמשיך לו האהבה שיבא לו מלמעלה צריך מתחלה לבטש את הגוף ולהכניעו ולהשפילו במרירות כמ\"ש במ\"א. כדכתיב קרוב ה' לנשברי לב ואת דכאי רוח יושיע. וכדכתיב זבחי אלהים רוח נשברה. כי בכדי שיומשך בחי' הוי\"ה לבחי' אלהים שלנו צריך מתחלה לעשות זבחי אלהים שדרך ההוא נמשך בחי' הוי\"ה."],[117,"והנה כל זה נקרא אתערותא דלתתא מלמטה למעלה והוא ענין התפלה. אבל ענין התורה היא בחי' מלמעלה למטה. והוא בחי' ובכל נפשך דהיינו שיומשך ויתפשט בכל כחות הנפש במחשב' דבור ומעשה ונק' אתעדל\"ע שעי\"ז מעורר למעלה בחי' חכמתו ורצונו חכים ולא בחכמה ידיעא שהתורה היא חכמתו ורצונו ית' אלא שמלובשת בענינים גשמיים. וזהו ענין קורא בתורה כמ\"ש במ\"א:"],[117,"<b>ובכל<\/b> מאדך הוא ענין התשובה כי גדולה תשובה שמקרבת את הגאולה. ומאד הוא לשון רבוי הרבה יותר מכדי מדתו כי אהבת בכל לבבך ובכל נפשך הוא נמשך מהתפשטו' גילוי אלהותו השוכן בתחתונים שאינו אלא זיו והארה בלבד. כמ\"ש ויצא כברק חצו שאינו אלא מחשבה אחת בלבד. כמ\"ש היוצר יחד לבם וגו'."],[117,"וע\"ד משל כשם שמחשב' אחת אינה נחשבת לכלום לגבי מהותו ועצמותו של האדם שיכול לחשוב מחשבות אין קץ ומספר. כך על אחת כמה וכמה שאין המחשבה זו נחשבת לכלום נגד עצמותו ית' כי אתה הוא קודם שנברא העולם ואתה הוא כו'."],[117,"ואני הוי\"ה לא שניתי וכל ימות עולם הזה ועולם הבא וג\"ע התחתון והעליון וימות המשיח ותחיית המתים אינו נחשב אצלו אלא כרגע קטן וכמ\"ש במ\"א וזו היא עבודת ניצוץ הנשמה המתפשט ומתלבש בגוף הגשמי כי לא כל הנשמה כולה מתלבש' בתוך הגוף רק נצוץ והארה ממנה בלבד ועיקרה ושרשה נשאר למעלה בבחי' מקיף והנצוץ המתפשט למטה נק' רגל לגבי בחי' עליונה שלמעלה שנק' בחי' ראש משא\"כ בחי' בכל מאדך הוא בחי' עבודת עיקר הנשמה בחי' הראש שבה והיינו בטול הנפש במציאות ממש להשתפך אל חיק אביה ממש מצד מהותו ועצמותו שהוא רם ונשא לאין קץ ולא שייך עליו לאמר מצד עצמו לא ממלא כל עלמין ולא סוכ\"ע שאינו בגדר עלמין כלל וכמ\"ש במ\"א:"],[117,"<b>והנה<\/b> הזוכה לבחי' אהבה רבה ועצומה כזו הוא הבעל תשובה כי להיות שהיה בהפוך והיתה נפשו בארץ ציה ועיף. ויזעקו אל הוי\"ה וגו'. אזי יתגלה אהבה רבה ועצומה כזו להיות בכלות נפשו ממש. וזהו ופרעה הקריב ואמרו רז\"ל שהקריב את לבם של ישראל לאביהם שבשמים. ולכן נק' בחי' אהבה זו מאד כמארז\"ל והנה טוב זה מלאך החיים. מאד זה מלאך המות שעי\"ז יתרבה ויתגדל תשוקת האהבה ביתר שאת ויתר עז ויוסף אומץ דבקותו:"],[117,"<b>וזהו<\/b> שמאלו תחת לראשי שע\"י בחי' שמאל דוחה שהיה בו מתחלה על כן ירום ראש ומתנשא בבחי' עבודת הראש של הנשמה כנ\"ל. וזהו ענין מעלת הזהב על הכסף הנזכר בלקוטי אמרים."],[117,"והבחינה שוב שאחר זה הוא בחי' וימינו תחבקני. שימינו הם תורה ומצות בחי' חסד ומים שיורדים ממקום גבוה למקום נמוך והם מחבקין את האדם כדרך שמחבק האדם את חבירו מאחוריו ואינו מניחו ליפול. כך ע\"ד משל התורה והמצות הם יורדים לבחי' אחוריים להתלבש בענינים גשמיים להאחז את האדם שלא יפול כשפונה אחר תפלה לעסקיו ויהיה סור מרע ועשה טוב והם יורדים ממקום גבוה ציצית קבלת עול מלכות שמים וארבע פרשיות של תפלין כנגד חכמה ובינה ⟦פו,ג⟧וחסד וגבורה של הקב\"ה. פ' ראשונה קדש לי כל בכור רמז לחכמה. פ' שניה כי ישאלך בנך מה זאת שהוא ענין התבוננות דקיימא לשאלה. פ' שמע מפורש בה ואהבת. פ' והיה אם שמוע מפורש בה השמרו לכם וגו'."],[117,"ולזה אומרים אשר קדשנו במצותיו כמ\"ש במ\"א. וזהו והר סיני עשן כולו מפני אשר ירד עליו ה' באש. והר סיני אמרו רז\"ל שירדה שנאה להעכו\"ם שהוא בחי' הרע שעל זה נאמר תכלית שנאה שנאתים ומואס ברע. נמשך מפני כי ירד ה' עליו שירד והמשיך למטה באש כמ\"ש מימינו אש דת למו והוא לחול על ראש רשעים. כהמס דונג מפני אש יאבדו וגו'."],[117,"וע\"ד זה הם כל המצות הן בסור מרע הן בועשה טוב וצדקה כנגד כולם כי צדקה תרומם גוי להיות בבחי' חבוק שלא יפרד ולא ישוב אחור רק להיות עמו פב\"פ כמ\"ש יאר הוי\"ה פניו אליך וגו' כמ\"ש במ\"א. וזהו ונתנו איש כפר נפשו בפקוד אותם. כלומר אשר יפקד ויחסר פגם האות שלהם אזי התקון הוא ע\"י צדקה שעי\"ז מקשר ומעלה נפשו להוי\"ה. ועמ\"ש במ\"א ע\"פ שאו את ראש כו' לגלגלתם:"],[118,"<b>זה יתנו כל העובר על הפקודים מחצית השקל בשקל הקודש עשרים גרה השקל מחצית השקל תרומה להוי\"ה וגו'.<\/b> כתיב נודע בשערים בעלה שהקב\"ה הוא בעל של כל נשמה מישראל שמשפיע לכל או\"א. שכל אהבה או יראה שיש לכל נשמה מישראל הכל הוא מאתו ית' ולכל חד לפום שיעורא דיליה. ולפי מה שנכנס בשערים שהם ד' שערים אהבה ויראה תורה ומצות כנודע כנגד ד' אותיות הוי\"ה ב\"ה."],[118,"ולהבין זה אם הכל ממנו ית' א\"כ מהו הבחירה לאדם. ובודאי יש דבר התלוי בבחירתו של אדם. ולבאר זה מה תלוי בבחירתו ומה בא מלמעלה. כתיב שמע ישראל ה' אלהינו ה' אחד. ואהבת כו'."],[118,"והנה בואהבת יש ב' פירושים. אחד לשון צווי שתאהוב אותו. וא' לשון עתיד שתבא האהבה ממילא. וענין אהבה הראשונה היא מההתבוננות. והיינו להבין בדעתו אחדותו ית' בשבעה רקיעים ובארבע רוחות ואני ה' לא שניתי שאין לו שום שינוי כמו קודם בריאת העולם כן הוא ממש עתה כי כל העולמות בטלים בבטול גמור נגדו כידוע כי שמש ומגן כו' ואף שנראה לנו העולמות ליש הוא שקר גמור. כי בדבר ה' שמים נעשו וברוח פיו כו'."],[118,"ומבשרי אחזה כו'. כמו באדם בתחלה כשחושב אזי מחשבתו באחדות גמור אתו בלי שום התחלקות כלל ואח\"כ כשיוצא מפיו הוא נפרד מאתו. כן כל העולמות קודם הבריאה היו באחדות גמור אתו ית'. וכמו שבטל הדבור אצל המחשבה בבטול גמור כי ברגע א' יכול לחשוב דברים עד אין קץ. כן כל העולמות שהם רק דבור א' והוא נמשך מחכמתו ית' כדכתיב ויצא כברק כו'. ובטובו מחדש בכל יום כו'. וגם אחר הבראם הרי אצל הקב\"ה אין דבורו מובדל ממנו ית' ח\"ו כי אין לך דבר שחוץ ממנו כו'. וכמ\"ש בתניא (פכ\"א) ולכן קמיה כולא כלא חשיב ממש וגם העולמות בטלים זה בזה ומה שלמעלה בחי' דבור נק' למטה נגד עולם התחתון בחינת מחשבה ובטל אצלו כמו שהדבור של הרב נעשה בחי' מחשבה אצל התלמיד כו' כנודע (ועמ\"ש ע\"פ כאשר דברת לאמר ⟦פו,ד⟧בפ' שלח) וזהו לית מחשבה תפיסא ביה כלל דהיינו אף עולמות עליונים מאד שהם בחי' מחשבה הם בטלים אצלו ית' ולא תפיסא ביה כלל כי הוא למעלה ממחשבה. וזהו סתימא דכל סתימין טמירא וכו' אף מעולמות הנק' סתימא וטמירא הוא סתים וטמיר ולית מחשבה תפיסא ביה וע\"ז נאמר הצווי ואהבת את הוי\"ה אלקיך שיתבונן כ\"כ באחד ממש שיהיה הוי\"ה אלקיך בכל לבבך ובכל נפשך ובכל מאדך דהיינו מחדו\"מ שלא יהיה לו מחדו\"מ כלל רק בטלים בא' שהוא למעלה מן המחשבה ולית מחשבה תפיסא ביה כי האדם אינו יכול לחשוב רק דבר גשמי וזהו שקר גמור כו'."],[118,"וזהו בכל נפשך מסירת נפש. כי נפש של אדם הוא מחדו\"מ והכל למסור ולהיות בטל באחד ממש. אבל להיות שזה בלתי אפשר שיהיה בלי מחשבה כלל לכן צריך לקשר מחשבתו ודבורו ומעשיו להיו' מרכבה לרצון העליון ב\"ה בתורה ובמצות דאורייתא מחכמה נפקת שהוא למעלה מן המחשבה."],[118,"וזהו כל העושה מצוה אחת כהלכתה וכו'. ואף שהתורה נתלבשה בדברים גשמיים איסור והיתר וכדומה. וכ\"ש מעשה המצות שהם בדברים גשמיים ממש כמו צדקה בממון וכיוצא. הוא כמשל השערות הנמשכות מהמוח שאין במוח בחי' שערות כלל כן הוא התורה והמצות אף שהם דברים גשמיים עכ\"ז אורייתא מחכמה נפקת כו'."],[118,"ודבר זה חובה על כל אדם להתבונן בזה היטב. וזה תלוי בבחירתו. ופי' הב' של ואהבת את הוי\"ה לשון עתיד הבא ממילא הוא בחי' אהבה רבה הבאה מלמעלה מאתו ית'. ובזה פי' שמע לשון שמיעה שאינו יכול להיות בו שום התבוננות כלל שהוא למעלה מההתבוננות."],[118,"וזה נק' שקל הקדש כסף לשון נכסף נכספת בחי' אהבה רבה הבאה מלמעלה במשקל כל חד לפום שיעורא דיליה בבחי' עשה טוב וסור מרע צריך להיות בתכלית והוא בחי' עובר לסוחר לשון סחור סחור סוכ\"ע."],[118,"וזהו ארבע מאות שקל כסף בחי' ד' מאות עלמין דכסופין לעלמא דאתי. וזהו עשרים גרה השקל. כי כל א' משני בחי' אהבה הנ\"ל כלולה מעשר שכל ומדות כנודע ובחי' אה\"ר הבאה מלמעלה ג\"כ כלולה מעשר."],[118,"וזהו עשרים גרה השקל. וזהו כי תשא את ראש בני ישראל לפקודיהם דהיינו נשמות הנק' ראש לפקודיהם לשון וה' פקד את שרה וכו' ונתנו איש כפר נפשו לה'. אך שלא לכל אדם באה לו אהבה רבה הנ\"ל."],[118,"ולהיות בבחי' עשרים גרה כו'. אך בחי' אהבה ראשונה חובה על הכל והיינו בחי' מחצית השקל למסור נפשו הכלולה מעשר. וזהו זה יתנו כל העובר על הפקודים רמ\"ח פקודין היינו אף מי שעובר ח\"ו על איזה מצוה אעפ\"כ חובה היא ליתן מחצית השקל בחי' עשר שלו בבחינת אה\"ר ראשונה הנ\"ל ומחצית השקל היא תרומה לה'. (ועמ\"ש לקמן ע\"פ ויקהל בענין אית רצון ואית רצון. ועיין עוד בלק\"ת פ' כי תבוא בד\"ה תחת אשר לא עבדת. ושם פ\"ב גבי מש\"ש וע\"ז נאמר שמחו צדיקים בהוי\"ה ועיין סד\"ה זה יתנו כו' מחצית השקל עכ\"ל. ויובן משם ג\"כ דבחי' העבודה בשמחה שהחיוב על כל ישראל כמ\"ש תחת אשר לא עבדת כו' בשמחה. וכן נאמר עבדו את ה' בשמחה זהו בחי' מחצית השקל שהחיוב על כל א' מישראל ליתן. ובחי' שמחו צדיקים בה' זהו מחצית השני):"],[119,"⟦פו,ד⟧<b>ויקהל משה את כל עדת בני ישראל ויאמר אליהם וגו'.<\/b> ששת ימים תעשה מלאכה וביום השביעי יהיה לכם קדש שבת שבתון לה'. להבין מארז\"ל ע\"ז למה נסמכה פ' שבת למלאכת המשכן. גם צ\"ל מפני מה בצווי הקב\"ה למשרע\"ה בפ' תרומה ותצוה נאמר תחלה מלאכת כלי המשכן דהיינו הארון והשולחן והמנורה כו'."],[119,"ואח\"כ מלאכת המשכן עצמו הן היריעות של המשכן ⟦פז,א⟧ואח\"כ לבסוף הכל נאמר בפ' כי תשא אך את שבתותי תשמרו כו' הרי הקדים הכלים ואח\"כ היריעות ואח\"כ שמירת שבת."],[119,"ובצווי משרע\"ה לישראל דהיינו בפ' זו דויקהל משה הפך הסדר שאמר להם תחלה שמירת שבת. ואח\"כ מלאכת המשכן ואח\"כ הכלים. והענין דהנה כתיב ועשו לי מקדש ושכנתי בתוכם. בתוכו לא נאמר אלא בתוכם דהיינו בתוך כללות נשמות ישראל ישכון כבוד הוי\"ה ית' ע\"י המשכן ועכשיו ג\"כ הוא ע\"י עסקם בתורה ומצות. שהתורה היא כמו בחי' כלי המשכן."],[119,"והמצות הם בחי' יריעות המשכן כי ע\"י המצות נעשה בחי' לבושים לנפש. כמ\"ש והלך לפניך צדקך כבוד ה' יאספך. וזהו כמו בחי' יריעות שהן בחי' מקיפים והתורה היא בחי' מזון לנפש כמ\"ש ותורתך בתוך מעי. וזהו בחי' כלי המשכן שהן בחי' פנימיים:"],[119,"<b>ולהבין<\/b> זה יש להקדים להבין מ\"ש אני ה' לא שניתי שאין בו ית' שום שינוי והתפעלות ח\"ו ע\"י בריאת העולם שכמו שהיה יחיד ומיוחד קודם בריאת העולם כך הוא ג\"כ אחר בריאת העולם וכמאמר אתה הוא קודם שנברא העולם ואתה הוא משנברא כו'. ר\"ל בזה שאין בריאת העולמות פועל בו שום שינוי ח\"ו."],[119,"והיינו לפי שהחיות הנמשך ממנו ית' להחיות העולמות כללות אור וחיות זה הוא רק בחי' הארה בעלמא ממהו\"ע ית' שהאיר והמשיך ממנו עד\"מ הארה בעלמא. וע\"י זו ההארה הוא ית' מחיה אותן ומהוה אותן מאין ליש. אבל הוא ית' במהותו ועצמותו מרומם ומתנשא מגדר עלמין."],[119,"וזהו שנק' הקב\"ה שהוא קדוש ומובדל. והגם שנאמר ואתה מחיה את כלם. הנה עיקר חיותם וקיומם הוא רק מבחי' הארה בעלמא כנ\"ל. והארה זו היא בחינת מדת מלכותו יתברך כמ\"ש מלכותך מלכות כל עולמים. שחיות כל העולמים הוא מבחינת מלכותך דהיינו שמה שנק' הוא יתברך מלך עליהם מזה עצמו הם חיים וקיימים."],[119,"וז\"ש ישתבח שמך לעד מלכנו. פי' שהתפשטות מדת מלכותו ית' הנק' ג\"כ שמו הוא לעד דהיינו עד אין קץ ותכלית כי מדת מלכותו היא ג\"כ בחי' א\"ס ממש כיון שהיא הארה ממנו ית'."],[119,"וז\"ש בברכת יוצר ומשמיעים ביראה יחד בקול דברי אלקים חיים ומלך עולם שאין משיגים רק ההמשכה שנמשכ' מאלקים חיים ומלך עולם שקול הוא המשכה כנודע. אבל עצמותו ומהותו ית' הוא קדוש ומובדל דלמחת\"ב כלל ולכן לא שניתי כנ\"ל. וזהו והחיות נושאות את הכסא כו' זעות מחיל כסא. שתפול עליהם אימה ופחד של מדת מלכותו ית' שהוא בחינת מלך יושב על כסא רם ונשא ולכן הם מקבלים עליהם עול מלכות שמים כו':"],[119,"<b>והנה<\/b> מבחי' מדת מלכותו ית' נמשך האור והחיות ג\"כ בב' בחי' והוא בחי' סוכ\"ע וממכ\"ע. דהיינו שלהיות כי בחי' מל' הוא ג\"כ בחי' א\"ס ממש. וזהו פי' וענין אוא\"ס הנזכר בספרים. כי אור הוא בחי' גילוי והמשכה מעצמותו ומהותו."],[119,"וכנודע דהשמש עצמו נק' מאור. אבל אור היינו הזיו הנמשך ממאור השמש ומאיר לארץ ולדרים עליה. וכך בחי' אוא\"ס הוא עד\"מ זיו הנמשך ממהו\"ע ית'. אבל על מהו\"ע ית' ממש לא שייך כלל לשון אור. ולהיות כי האור הוא ג\"כ בחי' א\"ס ממש ע\"כ א\"א להעולמות להכיל בתוכן האור שלא יתבטלו ממציאות ממש. לכך עיקר האור הוא בחי' סובב ומקיף עליהן רק שע\"י צמצום רב ועצום נמשך איזה המשכה מצומצמת מהאור להיות מתלבש בתוך העולמות ונק' ממכ\"ע כו':"],[119,"<b>ובזה<\/b> יובן ג\"כ טוב טעם למה שכינו המקובלים לבחי' המשכת החיות מהבורא ית' בשם אור כנ\"ל בענין לשון אור א\"ס. (וכן בתניא )(פמ\"ח) אמר על ענין הסובב לשון הארה כו' ע\"ש. והגם שיש הרבה טעמים על זה. אך אחד מן הטעמים הוא זה והיינו ⟦פז,ב⟧כי כמו בגשמיות ענין הארה שהוא המשכת זיו השמש על איזה דבר. הנה הרי הזיו הוא רק בחי' מקיף על אותו הדבר ואינו נכנס בפנימיותו. נמצא שההארה היא המשכה וגילוי מההעלם. שהרי כשיש ענן ואין השמש מאיר זהו העלם גמור. כשהזיו נמשך ומאיר לארץ ולדרים עליה זהו גילוי."],[119,"ועכ\"ז גילוי זה הוא בחי' מקיף שאין הזיו נכנס בתוכיות הארץ והאדם כו'. וכך יובן ענין אור א\"ס שהוא בחי' סוכ\"ע שהרי הוא גילוי להחיות בחי' עולמות. וקודם בריאת העולם היה שמו נכלל בבחי' לבדו במהו\"ע. וזהו מארז\"ל עד שלא נברא העולם היה הוא ושמו בלבד שהיה שמו בבחי' לבדו. ובבריאת העולם נמשך להיות גילוי שיהיה בחי' סוכ\"ע. אבל מ\"מ הגילוי הזה הוא רק בבחי' מקיף ולכן נק' הארה כמשל הארת השמש שההארה מקפת כו':"],[119,"<b>וזהו<\/b> ארוממך אלוהי המלך ואברכה שמך לעולם ועד. דלכאורה לשון לעולם ועד אינו מובן שהרי ימי שנותינו בהם שבעים שנה. אלא דפי' אברכה שמך היינו להמשיך גילוי אלהותו בתוך העולמות ממש וזהו לעולם ועד. אך כדי להיות המשכה זו ממקורה ושרשה הוא ע\"י שבתחלה ארוממך כו'. דפי' ארוממך רוממות והתנשאות של בחי' המלך והוא בחי' סוכ\"ע כמשל התנשאות המלך על עמו הוא בחי' מקיף כו' ומשם יומשך אח\"כ להיות ואברכה שמך לעולם ועד בבחי' ממכ\"ע כו'. וזהו בקול דברי אלקים חיים ומלך עולם. קול הוא המשכה בפנימיות כו':"],[119,"<b>והנה<\/b> כמו שבכללות אור וחיות הנמשך מהא\"ס ב\"ה להחיות העולמות יש ב' בחינות סובב וממלא כנ\"ל. כך ג\"כ בענין המשכת גילוי אלהות ית' שאנו ממשיכים ע\"י תורה ומצות יש ג\"כ ב' בחינות אלו. כי ע\"י המצות נמשך בחי' לבושים שהוא בחי' מקיף וע\"י התורה נמשך בחי' מזון שהוא בחי' או\"פ כנ\"ל."],[119,"והענין כי הנה רמ\"ח מ\"ע נק' רמ\"ח אברין דמלכא. וגם נק' מצות המלך. ופי' אברין דמלכא היינו כמו שהאבר הוא לבוש שבו מתלבשת הנשמה שכח המעשה מלובש בידים. וכח ההילוך מלובש ברגלים והאבר ההוא נעשה כלי ולבוש מיוחד אל הכח ההוא המתלבש בתוכו. כך עד\"מ למעלה הרמ\"ח מ\"ע הם בחי' כלים ולבושים לבחי' אור א\"ס ב\"ה הנמשך בהן ועל ידן. כי הנה כתיב שום תשים עליך מלך. פי' להמשיך על עצמו עול מלכות שמים והיינו ע\"י מעשה המצות שהם מצות המלך וכמו ע\"י לבישת הטלית שממשיך עליו עול מלכותו ית' ונמשך עי\"ז המשכה מלמעלה ממדת מלכותו ית' על הנפש."],[119,"והמשכה זו היא בחינת מקיף. וזהו תשים עליך בבחי' מקיף שמתלבשת במעשה המצות הנק' אברין דמלכא. ועי\"ז נמשך על הנפש בבחי' מקיף מלמעלה וכמ\"ש יביאו לבוש מלכות כו'. וכן ומרדכי יצא מלפני המלך בלבוש מלכות כו'. שמדת מלכותו ית' נקראת בחי' לבוש מל' מפני שהיא אינהמתלבשת לגמרי בגילוי בתוך העולמו' בבחי' פנימיו' ממש רק שמתלבשת בבחי' לבוש ומקיף עליהם מלמעלה והיינו ע\"י מעשה המצות שהם הלבושין שבהן ועל ידן נמשך ומתלבש מדת מלכותו ית' להיות בחי' לבוש מלכות ובחי' מקיף כו'. שכאשר יקיים האדם מצוה א' ימשיך עליו בחי' לבוש מל' שיהי' נמשך עליו בבחי' מקיף כמו עד\"מ ע\"י הנחת תפלין שבזרועו ועל ראשו שיש בהן ד' פרשיות ממשיך עליו בחי' ד' מוחין עליונים. כי פ' קדש הוא כנגד מוח החכמה."],[119,"והיה כי יביאך בחי' בינה כו'. אך המשכה זו הוא בחי' מקיף בלבד שהרי ע\"י הנחת התפלין הכתובים בקלף ודיו גשמיים אין נכנס האור דד' מוחין עליונים בבחי' גילוי ממש בשכל האדם רק ששורה על המוח בבחי' מקיף בלבד."],[119,"ועד\"ז ע\"י כל המצות כולן נמשך מבחי' מלכותו ית' בבחי' מקיף על הנפש. ונקראו המצות אברים כמו עד\"מ באברי הגוף כאשר יאחז ⟦פז,ג⟧את חבירו באחד מאבריו ביד או ברגל יוכל להמשיך אליו כל גוף האדם על ידי שאוחזו באחד מאבריו כך על דרך משל זה בענין המצות שנק' רמ\"ח אברים דמלכא שע\"י קיום כל מצוה ממשיך עליו אור א\"ס ב\"ה. (ובכל הדרושים מבואר שהמצות הן המשכות מבחי' אנכי מי שאנכי שלמעלה מבחי' מל'. אך באמת גם כאן ר\"ל ההמשכה מבחי' סוכ\"ע שהוא בחי'כתר שנק' ג\"כ כתר מלכות כו'). וזהו ארוממך אלקי המלך בבחי' רוממות ומקיף עי\"ז ואברכה שמך בבחי' גילוי פנימי. וזהו ויעש דוד שם שע\"י מעשה המצות נמשך בחי' מלכותו ית' להיות מלכות כל עולמים בזמן ומקום כו'."],[119,"והנה ענין המשכה זו דבחי' מקיפים שע\"י המצות זהו ג\"כ ענין יריעות המשכן. כי הנה הגם שבדרך פרט הן רמ\"ח מ\"ע רמ\"ח אברים כו'. אך דרך כלל מתחלקים לז' חלקים כמ\"ש חצבה עמודיה שבע'. פי' עמודיה הן המצות כי תרי\"ג מצות דאורייתא עם ז' מצות דרבנן הם נקראים תר\"ך עמודי אור."],[119,"וכללותן הוא שבעה בחינות שהן שבעה מדות עליונות וע\"כ היו ביריעות המשכן שבעה מינים תכלת וארגמן תולעת שני ושש ועזים ועורות אילים ועורות תחשים כו'. כי היריעות הם בחי' המקיפים ע\"ד המקיפים הנמשך ע\"י מעשה המצות שהן בחי' חצבה עמודיה שבעה כו'. וזהו ג\"כ ענין לבושים דמרדכי שנאמר ומרדכי יצא בלבוש מלכות תכלת וחור כו' (וצ\"ע דכאן לא נזכר רק ו' לבושים ואולי הוא ע\"ד מ\"ש במ\"א בפי' לשון הזהר שיתא אינון שבע אינון כו' ע\"ש). וכ\"ז הוא בחי' מעשה המצות שהן המשכת בחי' מקיפים בחי' יריעות כו'. ואין הגילוי בנפש בבחי' או\"פ ממש אך ע\"י התורה נמשך בחינת אור פנימי שיכנס לנפש בפנימיותה ממש בבחי' מזון וחיות וכמ\"ש ותורתך בתוך מעי כו' וית' לקמן אי\"ה:"],[119,"<b>והנה<\/b> קודם שיתבאר בפרט בענין בחי' ומדרגת התורה צריך לבאר כללות ענין בחי' השבת מהו (שסמכו ענין לו למלאכת המשכן הן בצווי הקב\"ה למשה רבינו ע\"ה והן בצווי משה לישראל נזכרו ג' דברים אלו יריעות וכלים דמשכן ושבת רק שמשרבע\"ה הקדים השבת כו' ושינה הסדר כדלעיל) דהנה ידוע מארז\"ל שבשבת נתוסף בכל אחד ואחד מישראל נשמה יתירה. ולכאורה אינו מובן מהו ענין הנשמה יתירה הלא אין נרגש בנפש האדם תוס' חיותו בשבת יותר מבכל השבוע. הענין הוא דהנה כתיב בפ' ראשונה דק\"ש שמע ישראל כו' אחד ואהבת בכל לבבך כו'. פי' שאהבה זו נולדה ונמשכה מן ההתבוננות בגדולתו ית' איך שהוי\"ה אחד. כמארז\"ל תמליכהו בשמים וארץ וד' רוחות העולם. שע\"ז מורה הח' והד' דאחד. הח' הוא בחי' ז' רקיעים והארץ."],[119,"והד' הוא ד' רוחות העולם שהן בטלים ליחודו ית' המרומז באות אל\"ף. וכמו כן למעלה עד רום המעלות יש בחי' ז' רקיעים והארץ רוחניים בחי' לך ה' הגדולה כו' וכולם מקבלים חיות רק מבחי' שם כבוד מלכותו כו'."],[119,"ועל ידי התבוננות זו יבא לבחי' ואהבת בכל לבבך. ע\"ד מ\"ש השבטים ליעקב כשם שאין בלבך אלא אחד כך אין בלבנו אלא אחד פי' כשם שאין בלבך אלא אחד כי שרשו של יעקב הי' גבוה מאד נעלה שהי' בחי' מרכבה ממש ליחודו ואחדותו ית'. כך אין בלבנו אלא אחד אף שאנחנו למטה בעלמא דפרודא אעפ\"כ ע\"י הבטול רצון לאכפייא לסט\"א שלא יחפוץ בשום חפץ בעולם זולת לה' לבדו נעשה להם ג\"כ לב אחד לאביהם שבשמים (ועיין בזוהר פ' תרומה דקל\"ד ע\"ב מזה) דהיינו רצון א' פשוט התקוע בלב שלא לחפוץ בשום חפץ בעולם זולת לה' לבדו לכך אין בלבנו אלא א' בלבד הגם שאנחנו למטה נעשה למטה אחד כמו למעלה (באצי' ששם הוא בחי' רה\"י. וזהו ישראל גוי אחד בארץ שיהיה גלוי אחד גם בעשי' הגשמית) וזהו שאמר ואהבת בכל לבבך בשני יצריך שיתהפך ⟦פז,ד⟧גם הרצון של הנה\"ב הנק' יצה\"ר להיות לה' לבדו. ורצון זה ואהבה זו נולדים ונמשכים מהשכל דהיינו ע\"י ההתבוננות שמתבונן בגדולתו ורוממותו ית' איך דכולא קמיה כלא חשיבי ואפס בלעדו שמזה יומשך בטול הרצון. ולכן נסמך פסוק ואהבת לפסוק הוי\"ה אחד דלעיל מניה כי ע\"י ההתבוננות איך שהוא ית' אחד בז' רקיעים והארץ כנ\"ל הרוחניי' והגשמיי' יומשך ואהבת בכל לבבך כו':"],[119,"<b>והנה<\/b> כ\"ז הוא בכל ששת ימי המעשה שנאמר בהו ששת ימים תעבד. והעבודה היא בחי' פולחנא דרחימותא כי היא בחי' עבודה ויגיעה שא\"א להיות הולדת והמשכת האהבה מההתבוננות אא\"כ ייגע א\"ע לקשר דעתו בחוזק ונצרך לזה כל הל\"ט מלאכות ברוחניות הזורע והחורש כו' כמו שכתוב במ\"א."],[119,"ובחי' אהבה זו שבחול היא רק האהבה הנמשכת מהשכל וההתבוננות כו'. אבל בשבת נתוסף בכל א' נשמה יתירה והיינו שנולד בכנס\"י דבר חדש ממש מה שאין נמצא בהם בחול. והיינו בחי' אהבה ורצון לה' שלמעלה מן השכל וההתבוננות. כי הנה אית רצון ואית רצון פי' אית רצון שנולד מהשכל וההתבוננות ונק' רצון התחתון לפי שבחי' רצון זה נולד מהשכל א\"כ הוא למטה מהחכמה ובינה ונולד ונמשך מהם. אבל אית בחינת רצון העליון שלמעלה מעלה מהחכמה."],[119,"וגילוי בחי' זו בנפש האדם הוא בחינת האהבה שאינה נולד' מהתבוננות השכל כ\"א היא אהבה פשוטה שלמעלה מן השכל שזהו בחי' יחידה שבנפש שלמעלה מהחכמה וכמו עד\"מ כאשר יחפוץ האדם בחפץ ורצון לאיזה דבר הנוגע לעצם הנפש ממש וגורם לו לעשות דברים שלא ע\"פ הדעת והשכל כלל כי רצון זה עמוק עמוק מהשכל כו' וכנודע שיש בחי' רצון שלמעלה מהשכל ע\"ד אמרם כך עלה במחשבה ואין טעם לרצון."],[119,"ובחינת אהבה ורצון זה לה' מתגלה בנפש אדם ביום השבת דוקא. והיא בחינת אהבה רבה שהיא באה מלמעלה למטה בנפש האלקית בשבת דהיינו שאין האהבה לפי ערך השכל וההתבוננות לבד רק היא למעלה מהשכל ונמשכת מבחי' רצון העליון שלמעלה מהחכמה. (וזהו שמבואר בפע\"ח דהיכל האהבה המאיר בק\"ש דשבת הוא למעלה מעלה מבחי' היכל האהבה המאיר בק\"ש דחול ע\"ש) שבחי' גילוי רצה\"ע הוא בשבת דוקא דהנה כתיב שער החצר הפנימית הפונה קדים כו'. פי' כי בעשרה מאמרות נברא העולם בשימ\"ב ובראשית שהיא ח\"ע נמי מאמר הוא ונשפלה הח\"ע והמדות להתלבש בבחי' הדבור לומר יהי אור כו'. עד\"מ אדם הכותב או מצייר כו'."],[119,"ונק' לכך ו' ימ\"ב שמקבלי' מבחי' ראשית היא הח\"ע ובשבת כתיב וינפש שגמר המלאכה ונתעלו החכמה ומדות לבחי' שלמעלה מהחכמה הוא בחי' רצון ותענוג העליון. וזהו בחי' הפונה קדים בחי' שלמעלה מהחכמה נק' קדם שלמעלה מבחי' ראשית כו' כי הראשית יש שני לו משא\"כ בחי' קדמונו של עולם כו' וכנודע ג\"כ ע\"פ המגיד מראשית כו' ומקדם כו' ע\"ש ובשבת נפתח השער הפונה קדים הוא גילוי רצה\"ע ותענוג העליון לפי ששבת וינפש עליית החכמה בלמעלה מהחכמ' משא\"כ בששת ימי המעשה שנק' וי\"ב שמקבלים מחכמה ולא מבחי' קדם שלמעלה מהחכמה שאינו אז בבחי' גילוי כמו עד\"מ שבשעת המלאכה אין מתגלה עדיין התענוג רק כשנגמר כו'. ולכן נמשך גילוי בחי' רצה\"ע ג\"כ בנפש האדם שהיא גילוי האה\"ר שלמעלה מהשכל כו'. כמ\"ש ע\"פ כי טובים דודיך מיין. ומארז\"ל עריבים עלי כו' (וזהו שאנו אומרים בקדוש דשבת ורצה בנו ע\"ש התגלות רצה\"ע בנו ממש):"],[119,"<b>וזהו<\/b> ענין שבת שבתון לה' כי הנה המשכת הרצון העליון שהוא בחי' הרצון שלמעלה מהשכל הנמשך ומתגלה בשבת הוא דוקא כשיש כלי לגילוי אור זה והכלי הוא בחינת הרצון התחתון שנולד מן השכל ⟦פח,א⟧וההתבוננות בכל ששת ימי המעשה שזה הרצון התחתון נעשה בחינת כלי לגבי זה הרצה\"ע שיומשך בתוכו ממש בבחי' השראה כהשראת האור בתוך הכלי ממש. מפני שהרצון התחתון אע\"פ שהוא למטה מבחינת רצה\"ע אבל עכ\"פ כלי הוא לגילוי רצון העליון שיהיה מתלבש בו בהתחברות ויחוד אמתי ביום השבת."],[119,"וע\"ז נאמר שבת שבתון להוי\"ה. פי' שבת שבתון הם ב' רצונות הנ\"ל שמתחברים כאחד והיו לאחדי' ממש ולשון שבתון להוי\"ה היינו כי שם הוי\"ה הנה היו\"ד בחי' חכמה כו' ובשבת הוא בחי' שבת להוי\"ה שמתגלה הרצה\"ע שלמעלה משם הוי\"ה כו'."],[119,"וז\"ש כי אל דעות הוי\"ה שיש ב' בחי' דעת. הא' דעת עליון והב' דעת תחתון. פי' דעת הוא לשון רצון שדעת ורצון הכל ענין א' כמ\"ש רק אתכם ידעתי מכל משפחות כו'. שהכוונה הוא שבחרתי ורציתי אתכם לבחור לי לעם סגולה כי דעת הוא ענין הכרה שזהו בחי' התקשרות המביא לידי הרצון כו'."],[119,"וכן והאדם ידע ל' התקשרות והתחברות כו'. וענין אל דעות היינו התחברות ב' דעות הנ\"ל שהם ב' הרצונות הנ\"ל. ואז הוא בחי' שבת שבתון לשם הוי\"ה והוא ג\"כ פי' אל דעות הוי\"ה שמתחברים ב' הרצונות שהרצון העליון שלמעלה מהחכמה מאיר ומתגלה ג\"כ ברצון התחתון כו'. וזהו ענין הנשמה יתירה דשבת שהוא גלוי רצה\"ע מבחי' יחידה כנ\"ל. וזהו שנק' נשמת כל חי. וכמ\"ש ומשביע לכל חי רצון שגלוי רצה\"ע נמשך בבחי' הנק' כל חי כו' ומשם נמשך להיות רצון יראיו יעשה שיתגלה בהם הרצון העליון:"],[119,"<b>והנה<\/b> כשנמשך הרצה\"ע להתלבש ברצון התחתון ביום השבת אזי נמשך ממנו ג\"כ הארה בכל ששת ימי המעשה להיות נמצא בהאדם בחינת הארה מרצה\"ע שלמעלה מהשכל. וגילוי הארה זו היא בזמן התפלה דחול כשמתעורר באהבה וחפץ לה' ית' שהוא בחי' הארה מקדושת שבת המאיר בימי החול כמ\"ש בזוה\"ק יומא דא יהיב חילא לשאר יומי כו'. ולכן יכול להאיר בהן מבחי' רצה\"ע הנ\"ל. (וכמו שהביא בר\"ח שער הקדושה פ\"ב מאמרי הזוהר המבארים איך שצריך להתקדש ולהמשיך עליו בכל יום מקדושת שבת. וזהו פי' מ\"ש קדושים תהיו כו' להמשיך עליו מבחי' שבת שהוא קדש בעצם. וכ\"כ בפע\"ח שתוספת נר\"נ המאירים בשבת אינן מסתלקין ג\"כ בימות החול רק בחי' תוס' ח\"י מסתלקים במוש\"ק כו'. אך צריך להכין א\"ע לקבל בחי' זו דתוס' נר\"נ. והיינו ע\"י מחדו\"מ דתומ\"צ שהם כלים לבחי' נר\"נ. וכמשי\"ת לקמן בענין ז' קני המנורה איך שע\"י התומ\"צ ממשיכים גילוי בחי' רצה\"ע כו'. וזהו ענין חולין שנעשו על טהרת הקודש היינו כשבימי החול מאיר ג\"כ מעין קדושת השבת כו'). והנה התפלה של חול היא בחי' הממוצע בין שבת ליומין דחול הממשיך ההארה מבחי' רצה\"ע המתגלה בשבת בכל יומין דחול כו'. ולכן נמשלה התפלה לסולם דכתיב והנה סלם מוצב ארצה וראשו מגיע השמימה כו' כמשל הסולם שבו ועל ידו עולה התחתון מלמטה מהארץ על הגג."],[119,"וכן בו יורד העליון מלמעלה למטה. כך עד\"מ התפלה נמשלה לסולם שע\"י התפלה עולה הנפש מלמטה למעלה במעלות ומדרגות עליונות דרגא בתר דרגא עד רום המעלות. והיינו ע\"י צעקת הלב ברעותא דלבא לכלות נפשו אליו ית' שזהו בחי' העלאת מ\"נ מלמטה למעלה לעלות בעילוי אחר עילוי עד רום המעלות ליכלל באוא\"ס ב\"ה."],[119,"וכן נמצא בה בחי' הירידה מלמעלה למטה דהיינו כאשר כבר נתעלה בתכלית העילוי ברום המעלות בהגיעו אל בחי' רצה\"ע ב\"ה אזי יעוררו וימשיכו שירד בהשתלשלות המדרגות מלמעלה למטה להתלבש ברצון התחתון וממנו יתפשט ההארה בכל ו' יומין. וז\"ש ומלאכי אלקים עולים ויורדים בו שבהסולם ימצא ב' בחי' ומדרגות ⟦פח,ב⟧שונות בחי' העלייה מלמטה למעלה ובחי' הירידה מלמעלה למטה. והיינו בחי' התפלה כו' שמחברת בחינת קדושת השבת עם ו' יומין דחול להיות מאיר הארת רצה\"ע שבשבת בכל יומין דחול להיות חולין שנעשו עטה\"ק. והיינו על ידי עלייה וירידה (ועבמ\"ש בפסוק יונתי כו' איך שיש בחי' נשמה שבגוף ויש בחי' שרש הנשמה ושם נתבאר דשרש הנשמה היא בבחי' מחשבה הקדומה שלמעלה אפי' מבחי' תורה והיא בחי' רצה\"ע הנ\"ל וגם נתבאר דע\"י התפלה עולה נשמה שבגוף לשרשה הנ\"ל. וא\"כ נראה בענין תוס' נשמה יתירה דשבת דהיינו גם מבחי' שרש הנשמה הנ\"ל. וכ\"מ בפע\"ח שער השבת פי\"ט דהמקיפים נכנסים בשבת בבחי' פנימיים והארה ממנה מאיר בכל יום כו' על ידי התפלה כנ\"ל):"],[119,"<b>והנה<\/b> ע\"י התורה ממשיכים ג\"כ רצון העליון שיתלבש ברצון התחתון כי התורה נמשכה מבחי' רצה\"ע. והגם דאורייתא מחכמה נפקת. נפקת דוקא שיציאתה מהעלם אל הגילוי הוא מבחי' חכמה אבל שרשה מבחי' רצה\"ע ית' (כי תרי\"ג מצות דאורייתא עם ז' דרבנן בגימטריא כתר) רק שנתלבשה למטה בבחי' המדות חג\"ת דאצי' שמבחי' חסד נמשך להקל להיות כשר ומותר וזכאי ומבחי' גבורה נמשך להחמיר כו'. ובחי' המדות הם למטה מהחכמה. נמצא ענין התורה הוא המשכת רצה\"ע שלמעלה ברצון התחתון שהוא בחי' דעת תחתון שהוא בחי' פנימיות המדות כנודע (רק שהמשכה זו ע\"י התורה א\"א להמשיך כ\"א ע\"י הקדמת התפלה שהוא בחי' הסולם לעלות מלמטה למעלה וגם דוקא ע\"י קדימת בחי' שבת שהוא ג\"כ אותיות תשב עליית רצון התחתון ברצה\"ע וירידת רצה\"ע ברצה\"ת וזהו כעין בחי' אתעדל\"ת שעי\"ז יוכל להמשיך אח\"כ ע\"י תומ\"צ כו' מלמעלה למטה וכדלקמן אי\"ה). והנה התורה היא נגד בחי' כלי המשכן שהם מנורה ושולחן. (וכ\"ש הארון שבו היו מונחים הלוחות ממש רק שבחי' הארון שהיה בבית קדה\"ק הוא כמו שהתורה בשרשה. ובחי' המנורה שהיה בהיכל הוא בחי' גילוי התורה במדות. וז\"ש בתורה פיה פתחה בחכמה ותורת חסד על לשונה הנה נקראת בחי' חכמה ובחינת חסד כי אורייתא מחכמה נפקת. וזהו בחי' הארון ומתלבשת במדות שכללותם הוא החסד. וזהו בחינת המנורה שהי' בדרום בחי' חסד כו') כי הנה כמו שהמנורה מדליקין בה אור. כמו\"כ בתורה כתיב ותורה אור. ופי' אור דתורה הוא כמ\"ש חכמת אדם תאיר פניו. כי ארז\"ל חכמת זו סדר קדשים שע\"י למוד סדר קדשים מעורר וממשיך הגילוי בבחי' ח\"ע להיות חכמת אדם תאיר פניו."],[119,"וענין הארת פנים למעלה הוא כמו עד\"מ למטה באדם כשמשכיל השכלה חדשה יצהבו פניו כמ\"ש רז\"ל גבי ר' אבהו שצהבו פניו מחמת שראה תוספתא חדתא. והוא מחמת גילוי התענוג שמתגלה ומתלבש בההשכלה חדשה ונמשך ומתגלה בפנים ממש עד שצהבו פניו ומאירים. כך עד\"מ למעלה ע\"י עסק התורה ממשיכים גילוי אור התענוג עליון להיות מאיר ונמשך בח\"ע והוא בחי' אור חדש מעצמות א\"ס ב\"ה שמתלבש בחכמת התורה."],[119,"וזהו ענין יאר ה' פניו אליך כו'. וזהו ג\"כ ענין אור דמנורה. ובזה יובן ג\"כ ענין ז' קני המנורה היינו קנה האמצעי שהוא גוף המנורה ושלשה קנים יוצאים מצדה האחד. ושלשה קנים מצדה השני וכפתר תחת שני הקנים ממנה כו'. דהיינו שבמקום שיוצאים שני קנים מקנה האמצעי א' לכאן וא' לכאן שם יש כפתור כו' וכן תחת שני הקנים השניים ותחת שני הקנים השלישיי'."],[119,"והענין כי כל זה רומז על כללות התורה שהיא תושב\"כ ותושבע\"פ. וזהו ענין ששה קנים היוצאים מן קנה האמצעי הם שיתא סדרי משנה שמקבלים מקנה האמצעי שהוא ⟦פח,ג⟧בחי' תושב\"כ. שהרי למדין הכל מן המקרא כמ\"ש בגמ' מאי טעמא אמר קרא כו' נמצא התושבע\"פ יוצאת ונמשכת מבחי' תושב\"כ. כמו שששת הקנים יוצאים מן המנורה כו'."],[119,"וענין הכפתור תחת שני הקנים הענין דכל השפעה הנמשכת ממשפיע למקבל א\"א להיות כ\"א ע\"י אתעדל\"ת מן המקבל אל המשפיע ועי\"ז נמשך אתעדל\"ע מהמשפיע ונק' מ\"ן ומ\"ד. וכמו\"כ בענין ההשפעה מתושב\"כ לתושבע\"פ יש ג\"כ ב' בחי' אלו. שהרי נודע שתושב\"כ נק' מוסר אביך. בחי' אב הוא בחי' דכורא המשפיע."],[119,"ותורה שבעל פה נק' תורת אמך בחי' נוק' ומקבל מתושב\"כ רק דשם נגדל ההשפעה כו'. וא\"כ יש בזה בחינת העלאת מ\"ן והמשכת מ\"ד ונק' אתעדל\"ת ואתעדל\"ע. וזהו ענין הכפתור תחת שני הקנים שבמקום יציאת הקנה מהקנה האמצעי שם הוא ענין התחברות המ\"ן והמ\"ד שמתחברין אתעדל\"ת ואתעדל\"ע לכן יש שם אור כפול עד\"מ מהתחברות ב' הבחי' לכן היה כפתור שהוא עב יותר משאר מקום המנורה כיון שבבחי' זו מתחברים ב' בחינות משפיע ומקבל כו'."],[119,"ונק' בחי' זו קשרין בזהר עד\"מ הקשר שמתקשרים שני דברים יחד הנה במקום הקשר הוא עב יותרמחמת ששם יש חבור שני הדברים יחד. וכן השולחן ג\"כ רומז לבחי' התורה שעליו מניחים לחם הפנים."],[119,"והתורה נק' לחם לכו לחמו בלחמי כי היא בחי' מזון לנפש להמשיך הגלוי בפנימית שמשיג החכמה בפנימיותו ששכלו משיג חכמת התורה שבה מלובש אוא\"ס ב\"ה כו'. לכן נעשה לו מזה מזון וחיות ממש לנפש. וכן למעלה הוא בחי' ישראל מפרנסין כו' שיהיה התלבשות א\"ס בח\"ע כו'. אבל המצות הם בחי' לבושים ומקיפים לנפש שהן המשכות מבחי' שאין הגלוי יכול להתלבש בפנימיותו רק שאור ה' מקיפו מראשו ועד רגלו והן בחי' יריעות המשכן כמשנת\"ל (ולשם נת' דבמצות יש ג\"כ ז' בחי' חצבה עמודיה שבעה. וכן ז' מינים ביריעות רק שהם מקיפים ובתורה ז' קני המנורה הם בחי' פנימיים):"],[119,"<b>וע\"פ<\/b> כל הנ\"ל בביאור בחי' היריעות וכלים דמשכן שהם בחינת תומ\"צ כנ\"ל. ובביאור ענין השבת שהוא בחי' הנשמה יתירה התחברות רצה\"ע ברצה\"ת. יובן בטוב טעם ענין שייכות הצווי במצות שבת סמוך לצווי דמלאכת המשכן כמ\"ש בפ' תשא אך את שבתותי תשמרו כו'."],[119,"וגם מה שמשרבע\"ה הקדים הצווי על השבת למלאכת המשכן הפך ממה שנזכר בצווי הקב\"ה למשרע\"ה. והענין כי עם היות שע\"י תומ\"צ ממשיכים בחינת מקיפים ופנימיים שהם בחי' לבושים ובחי' מזון לנפש שיהיה גלוי רצה\"ע בנפש בבחי' פנימי ע\"י התורה ובבחי' מקיף ע\"י המצות. אך באמת כיון שהאדם הוא מלמטה בגוף גשמי א\"א לו להגיע לבחי' רצה\"ע שלמעלה מעלה מכל העולמות להמשיך משם האור למטה."],[119,"ולזאת צ\"ל תחלה בחי' אתעדל\"ת שיעורר בנפשו ויעלה להגיע לגלוי בחי' רצה\"ע ועלייה זו היא בחי' שבת אותיות תשב עליות העולמות מלמטה למעלה מעלה עד רום המעלות שהוא בחינת רצה\"ע המתגלה במנחה בשבת כמ\"ש ואני תפלתי לך ה' עת רצון כו'."],[119,"וגם בנפש האדם יש בחי' עלייה זו וגלוי זה שזהו ענין הנשמה היתירה כדלעיל. ואח\"כ נמשך מבחי' הארה זו לכל ימות החול ע\"י התפלה הנק' סולם ועי\"ז יוכלו להמשיך אח\"כ ע\"י התומ\"צ גלוי והמשכת האור מלמעלה למטה משא\"כ בלא קדימת בחי' ההעלאה שע\"י השבת א\"א להמשיך וכמארז\"ל כל האומר אין לי אלא תורה כו'."],[119,"ולזאת בצווי משרבע\"ה לישראל בעשיית המשכן הקדים הצווי על השבת ואח\"כ צוה ענין יריעות המשכן שהם בחי' מקיפים הנמשכים ע\"י המצות ואח\"כ על כלי המשכן שהוא בחי' פנימיים. והענין שכל המשכה מלמעלה למטה ⟦פח,ד⟧מתחלה נמשך האור בבחי' מקיף על המקבל ואח\"כ נשפע ונמשך ממנו הארה בפנימיותו כו'."],[119,"והשאר נשאר בבחי' מקיף לכן הקדים היריעות להכלים וזהו שארז\"ל כל הקורא ק\"ש בלא תפלין כאלו מעיד עדות שקר בעצמו. כי הנה בתפלין הם ג\"כ הפרשיות שמע והיה דק\"ש רק בתפלין הם בחי' מקיף. ובק\"ש שאומר אחד ואהבת הוא בחי' גלוי בפנימיות. ולכן תחלה צ\"ל המקיף ואח\"כ הפנימי. וכשקורא ק\"ש בלא תפלין להמשיך הפנימי בלא המקיף זהו עדות שקר כו':"],[119,"<b>וכ\"ז<\/b> הסדר הוא בענין עבודת האדם. וזהו צווי משרבע\"ה לישראל בפ' ויקהל. אבל בענין סדר ההמשכה מאור א\"ס ב\"ה בעולמות הוא להפך שמתחלה צ\"ל הכלים ואח\"כ היריעות ואח\"כ בחי' שבת. כי להיות ההמשכה מאוא\"ס בעולמות הוצרך להיות צמצום רב ועצום ושיהיה הגלוי רק הארה מועטת כדי שיוכלו העולמות לקבל ולא יתבטלו ממציאותן ובחי' גלוי זה זהו ענין כלי המשכן שהם בחינת פנימיי'."],[119,"ואח\"כ מבחי' גלוי זה נמשך אח\"כ להיות בחי' מקיף וסובב על העולמות. וזהו ענין היריעות המשכן. וזהו דבפ' תרומה ותצוה שהוא צווי הקב\"ה למשרבע\"ה נאמר תחלה הכלים ואח\"כ היריעות דכך הוא סדר ההמשכה מלמעלה למטה ואח\"כ נאמר צווי השבת בפ' תשא."],[119,"והענין כי הכלים והיריעות הם סדר ההמשכה מלמעלה למטה ואח\"כ בגמר ותכלית ירידת השפע העליונה אז הוא בחי' השבת שהיא המנוחה וההסתלקות אל עצמותו כמ\"ש כי בו שבת וינפש כאדם ששובת ונח שהוא בחי' עליית כחות הנפש מהשפלתן לעצמותן כו'."],[119,"ולכן נאמר צווי השבת אח\"כ כי לא שייך בחי' שביתה ואור חוזר רק אם מתחלה נמשך בחי' או\"י והמשכה מלמעלה למטה ע\"י הכלים והיריעות אז צ\"ל אח\"כ או\"ח ע\"י השבת משא\"כ בעבודת האדם מלמטה למעלה צ\"ל תחלה ההעלאה דהיינו בחי' השבת לעלות למעלה מעלה עד רום המעלות."],[119,"ואח\"כ ימשיך השפע מלמעלה למטה היינו מבחי' רצה\"ע המתגלה ביום השבת וההמשכה מבחי' זו היא מתחלה בבחי' מקיף ולבוש שזהו ענין יריעות המשכן ואח\"כ בחינת הכלים דהיינו בחי' התורה שהיא חכמתו ית' ומחכמה נמשך מדת החסד שנמשל למים כמו המים היורדים ממקום גבוה למקום נמוך כך התורה נמשכה ממקום גבוה מאד וירדה למטה לכך נמשלה למים. וזהו פיה פתחה בחכמה ותורת חסד על לשונה. שנקראת התורה תורת חסד ע\"ש ההמשכה כו' שנמשכה חכמתו ית' למטה מטה כנודע שחכמה וחסד הם קו א' והיינו בחי' תורה וגמילות חסדים:"],[120,"<b>קחו מאתכם תרומה להוי' כל נדיב לבו יביאה את תרומ' הוי\"ה.<\/b> ולהבין ענין ב' תרומות אלו. אחת להוי\"ה והב' תרומת הוי\"ה. הנה תרומה לשון רוממות. ארוממך אלקי המלך כו' וגם תרומה לשון הפרשה להפריש תרומה. ולהבין ענין הרוממות הוא כי הנה נודע שיש ב' בחי' בהשתלשלות ממכ\"ע וסוכ\"ע. שבחי' ממכ\"ע הוא כמשל הנשמה שמחי' את הגוף ומתלבשת בו להחיות בבחי' התחלקות מחשבה ודבור ומעשה והתלבשות המוחין בראש כו'. וכן בכל אבר חיות פרטי (שהחיות מתלבש בכל אבר לפי מזגו ותכונתו דהיינו שכללות גילוי חיות הנשמה היא במוחין ומשם נמשך הארה לכל כלי ואבר כפי בחינתו. בעין נמשך ומתלבש כח הראיה. ובאוזן נמשך ומתלבש כח השמיעה. וכח המעשה נמשך ומתלבש בידים עד כח ההילוך שנמשך ומתלבש ברגלים. נמצא האור והחיות מאיר ומתלבש בכל כלי לפי בחינתו ומהותו. ועל כן בהמוחין מאיר הארה וחיות יותר גדול מפני שהכלי מזוכך ונעלה יותר. ע\"כ יכול לקבל הארה יותר גדולה והיא גילוי השכל והמחשבה. משא\"כ בידים אין הכלי יכול לקבל בחי' גילוי זה לכן אין נמשך ומתלבש בהם רק גילוי כח המעשה. ואעפ\"כ יש בהם הארה יותר גדולה מבכח הנמשך ומלובש ברגלים שאין בהם רק כח ההילוך. משא\"כ ביד יוכל לעשות כל מלאכת מחשבת ולכתוב דברי חכמה. הרי שהשכל אע\"פ שאינו מלובש בגילוי ביד נמשך הוא ומתגלה ע\"י אמצעות כח המעשה שבידים. משא\"כ בכח ההילוך שברגל אין שייך בו המשכה זו. ואעפ\"כ בבחי' אחרת יש מעלה ברגל שנושא את הראש. וזהו משום דנעוץ סופן בתחלתן ויש בחי' בהסוף מבחי' תחלתן אך מ\"מ נקרא הרגל סוף ולא כן היד. והיינו שביד יש גילוי החיות יותר מברגל כנ\"ל ממשל כתיבת השכל ע\"י הידים דייקא. וכ\"ז מפני שהחיות נמשך ומתלבש בכל אבר לפי ערכו ותכונתו:) <b>ומזה<\/b> יובן הנמשל בענין סדר השתלשלות והמשכת החיות מאוא\"ס ב\"ה הנמשך בתוך כל עלמין. בכל עולם ובכל נברא לפשע\"ד כפי אשר יוכל שאת. וכללות חיות זה נק' בזוה\"ק ממלא כל עלמין. שבגעה\"ע מדור הצדיקים הגדולים מאיר בגילוי יותר והוא כמשל השכל המתגלה במוחין שבראש."],[120,"ואח\"כ בעולם המלאכים שעיקר מהותם באהוי\"ר טבעיים ואין להם השגה כמו נשמות הצדיקים הגדולים זהו כמשל החיות הנמשך ומלובש בידים חסד דרועא ימינא בחי' אהבה. מחנה מיכאל. וגבורה דרועא שמאלא. היא בחי' יראה מחנה גבריאל."],[120,"ואעפ\"כ יש להם השגה ג\"כ כמו שהשכל נמשך על ידי הידים. וגם כמו שהשכל נמשך ומתלבש במדות שבלב שהוא גילוי פנימי יותר מבידים כי הידים הם חיצוניות המדות. וכך יש מלאכים מבחי' פנימיות מיכאל וגבריאל אש ומים שהם מדות שבלב."],[120,"ויש מבחי' חיצוניות דרועא ימינא דהיינו להיות ההשפעה למטה מכלכל חיים בחסד כו'. וכן יורד עוד החיות בבחי' עשייה בכל עולם לפי ערכו. וכך כתיב אתה עשית את השמים ושמי השמים כו' הימים וכל אשר בהם ואתה מחיה את כלם. שהחיות ההוא מבחי' ואתה מחיה את כולם מתלבש תוך עלמין וממלא הוא בכל עולם לפי ערכו בשמי השמים גילוי בחי' עליונה יותר מבשמים. וכן בשמים יש גילוי בחי' יותר עליונה מבארץ כמו שנראה בחוש:(ויובן זה יותר ממה שהיה נראה בחוש בענין המשכת המן דכתיב הנני ממטיר לכם לחם מן השמים. וכתיב וברדת הטל ירד המן. והנה המן נק' ג\"כ לחם אבירים שמלאכי השרת נזונים בו. והוא תמוה דאיך המלאכים שהם רוחניים יאכלו המן שהיה דבר גשמי כמ\"ש וטחנו ברחים או דכו במדוכה. אך הענין שהמן שרשו גבוה מאד שנמשך מבחינת טל השמים והוא בחי' טלא דבדולחא שהוא בחי' אורות עליונים ממש וכמ\"ש כי טל אורות טלך נמצא שהוא ממש אורות עליונים הרוחניים. ונק' בזה\"ק טלא דנטיף מעתיקא לז\"א. וזהו טל השמים. הן ממש נמשכו ונתלבשו במן. ואיך יהיה ההמשכה זו ממקום עליון כ\"כ למטה הוא ודאי לא כמו שהאור ממש למעלה נמשך ומתגלה למטה. כי הרי בחי' טל אורות הוא אורות עליונים ממש שלמעלה אפי' מבחי' הכלים דע\"ס דאצילות. ולכן נק' טל אורות דוקא וא\"כ איך יומשך למטה כמו שהוא. אלא ודאי היינו ע\"י התלבשות בסדר ההשתלשלות ממדרגה למדרגה שמי השמים לבחי' שמים. ואח\"כ לבחי' ארץ. ולכן בעודו למעלה מלאכי השרת נזונין בו שאז עדיין היה מזון רוחני ולא גשמי כלל. ואח\"כ נתגשם ונעשה מזון גשמי. ומ\"מ מלובש בו אורות העליונים ממש. ולכן הוא ג\"כ למטה לחם אבירים שנבלע ברמ\"ח אברים ואין ממנו פסולת וע\"כ בשבת לא ירד מן. משא\"כ שאר השפעות נמשכים גם בשבת אע\"פ שאין לך עשב שאין לו מזל מלמעלה המכה בו ואומר לו גדל גם בשבת משא\"כ במן. והיינו משום דבמן היה נמשך מבחי' טל אורות. ובחי' זו א\"א לה לירד בשבת לפי שאז הוא עליית העולמות למעלה. רק שלפי שעלייה זו רק בפנימיות ולא בחיצוניות. לכן שאר השפעות יורדים בשבת לפי שהם מבחי' חיצוניות. וא\"כ מובן מזה איך שבמן היה התלבשות טל אורות. והיינו ע\"י השתלשלות ממדרגה למדרגה. ולכן אין דומה המן שלמטה לכמו שהוא למעלה. שלמטה נעשה גשמי. משא\"כ בעודו למעלה בעולם הרוחני הוא רוחני ולחם שמלאכי השרת נזונין בו. והיינו מן כמו שהוא עדיין למעלה בבחי' עליונות טרם ירידתן למטה. נמצא מזה יוכל האדם להשכיל ענין בחי' ממכ\"ע שהוא ירידת החיות מרום המעלות להיות יורד ונמשך ומתלבש בכל עולם לפי ערכו ובחינתו. והוא מ\"ש ואתה מחיה את כולם כו':) <b>עוד<\/b> יובן זה ממ\"ש בפ' שלח היש בה עץ אם אין. ופי' הזוה\"ק שם שרצו לידע מהות ההשפעה הנמשך בארץ ישראל אם היא רק מבחינת עץ הוא בחי' עץ החיים שהוא בחי' חכמה כמ\"ש והחכמה תחיה כו' וגם עץ ל' עצה ותושיה והוא בחי' חכמה. או שנמשך מבחי' אין שהוא בחי' שלמעלה מעלה ממדרגת החכמה כמ\"ש והחכמה מאין תמצא."],[120,"והסימן היה אם יראו גידול הפירות ע\"ד שאר הארצות לבד אז היא רק מבחי' עץ וכמו דכתיב כלם בחכמה עשית מלאה הארץ קניניך שכל העולם ומלואו שרשו מבחי' ח\"ע בראשית ות\"י בחוכמתא. אבל אם יראו גידול הפירות וההשפעה בעילוי רב שלא בערך כל הארצות וכנזכר בדברי רז\"ל סוף מס' כתובות. אז יובן שההשפעה לשם נמשך מבחי' אין שהוא למעלה מבחי' חכמה שמשם נמשך בגילוי יותר שלא על ידי צמצומים כו'. הרי מובן מזה ג\"כ איך אפי' בהשפעה גשמית ממש נמשך ומתלבש מבחי' אין שלמעלה אפי' מבחי' חכמה ואיך הוא אלא ודאי ע\"י השתלשלות מדרגות רבות עד אין קץ רק שמ\"מ מלובש בזה ממש מבחי' אין ומזה נמשך תוספת הברכה והגידול בתוספת מרובה. א\"כ מכ\"ז יובן למשכיל ענין בחינת ממכ\"ע שההשפעה נמשך מרום המעלות ממש רק שנמשך ומתלבש בכל עולם ובכל נברא לפי ערכו."],[120,"ולכן יש באור וחיות זה התחלקות מדרגות רבות אין קץ ממש שאפי' בכל עולם מתחלק לד' בחי' דצח\"מ. וגם בכל בחי' מד' בחי' אלה יש מדרגות שונות עד אין קץ ומספר ולכל בחי' לפי ערכה כך היא ההמשכה וזהו לכל חד לפום שיעורא דיליה:"],[120,"<b>ובחינת<\/b> סוכ\"ע הוא אור וחיות אלקי שאינו מתלבש תוך עלמין ממש ואין פי' סובב עולה וסובב מלמעלה אלא שהוא ג\"כ תוך עלמין אלא שאינו מתלבש בהם וכמ\"ש הלא את השמים ואת הארץ אני מלא אני דוקא שאין בחיות ההוא בחי' התחלקות כלל אני ראשון ואני אחרון קדמון לכל הקדומים כו' משא\"כ בחי' ממכ\"ע הוא בבחי' גבול מהלך ת\"ק שנה כו' רגלי החיות כו'."],[120,"וזהו ארוממך שעצמותו ומהותו מרומם ומנושא עד אין קץ ותכלית. אלקי שבחי' האור וחיות שנמשך מבחי' סוכ\"ע הוא ע\"י המלך שמלך שמו נקרא עליהם כמשל המלך שרק שמו והתפשטותו על מדינות ממשלתו. והמשכה זו שמבחי' סוכ\"ע להיות בחי' מל' מכ\"ע הוא ע\"י ישראל אין מלך בלא עם כו' ודוד אמר המקרא הזה בעד כלל ישראל ארוממך אלקי הוא ע\"י המלך כו':(ופי' הענין הוא דבחי' סוכ\"ע זהו המשכה מא\"ס ב\"ה שנמשך להיות מתנשא על העלמין. ובהתנשאות זו הוא מחיה אותם והוא החיות בבחי' מקיף שהרי ההתנשאות והרוממות שהמלך מרומם ומתנשא על עמו אין זה בחי' המשכה בפנימיותן כ\"א הוא כמו ענין הארה מבחוץ ובדרך מקיף. ולמעלה עי\"ז נמשך להם חיות וקיום מבחי' התנשאו' ומקיף זה. וזהו הנק' סוכ\"ע והוא בחי' מלכותך מכ\"ע. והחיות המתלבש בפנימיותן שזהו בחינת ממכ\"ע היא מבחינת דבר ה' ואתה מחיה את כולם היינו האותיות מאל\"ף עד תי\"ו וה' מוצאות וזהו פי' אתה. הוא המתלבש בפנימיותם. משא\"כ בחי' מלכותך וההתנשאות זהו בחי' סוכ\"ע. אבל מהותו ועצמותו ית' הוא למעלה מעלה מבחי' סוכ\"ע. וכמשל המלך שמהותו ועצמותו אינו מה שמתנשא על עם כי התנשאות זו היא רק התפשטות הארה ממנו לבד. וזהו ארוממך אלקי המלך. דבחי' רוממות זהו בחי' סוכ\"ע לפי שבחינה זו הוא ענין הרוממות וההתנשאות שזהו מקיף על כל עלמין ומחי' אותם עי\"ז והוא ג\"כ רק מבחי' המלך מדת מלכותו ית'. ואלהי הוא בחי' ההארה המתלבשת בתוך כל עלמין והיא הארה מבחי' מלכות. ועל כן פי' ארוממך היא ההמשכה ממהותו ועצמותו ית' להיות בחי' סוכ\"ע. ודהע\"ה שהיה מרכבה למדת מלכותו אמר זה וכנ\"ל):"],[120,"<b>אך<\/b> להיות הכח הזה בנפש שע\"י יומשך בחי' סוכ\"ע להיות בבחי' מלכות להחיות נבראים בע\"ג הוא ע\"פ מ\"ש שבעת ימים תאכל מצות לחם עוני כו' שכדי לקבל התורה בשבועות פנים בפנים כו' אחרי יציאתן ממצרים שהי' בבחי' אחוריים נצטוו לספור ספירת העומר ז' שבועות."],[120,"ובשבוע ראשונה לאכול מצה דייקא. והענין שיש בנפש הבהמית ז' מדות רעות כו' וכ\"א כלולה מכולם זפ\"ז הם מ\"ט. והוא ענין הספירה להיות המדות בחי' אתהפכא כו'. וזהו ענין העומר שבא מן השעורים מאכל בהמה בחי' נה\"ב כו'."],[120,"ובז' שבועות אלו מהפכן מעט מעט חסד שבחסד כו'. ע\"י שמאיר וממשיך בהן בחי' אור כמשל הנר שדוחה החושך כו'. וזהו וספרתם לשון הארה ואור ואומרים בכל יום היום כו'. היום כו'."],[120,"והמשכת האור הוא מלמעלה מבחי' המדות שעי\"ז מתהפכים המדות מבחי' אהבה שבלעו\"ז לאהבת ה' כו'. וכמ\"ש וספרתם לכם ממחרת השבת מלמעלה מבחי' המדות. אך א\"א להיות בחי' אתהפכא מבלי שתקדים תחלה בחי' אתכפייא שהיא בחי' בטול בטל רצונך כו'."],[120,"וכנודע שא\"א להיות התהוות יש מיש כמשל הגרעין הנזרע בארץ שמתרקב תחלה ונעשה בחי' אין ואז יכול להיות צומח גם בתוספת מרובה ע\"י כח הצומח שבארץ. משא\"כ קודם הרקבון שהוא עדיין בבחי' יש לכן ארז\"ל ביציא' אפרוח מן הביצה כי קא גביל עפרא בעלמא הוא כו'."],[120,"וכך א\"א להיות מבחי' אהבה שבלעומת זה בחי' אהבת ה' אם לא שתקדים תחלה בחי' בטול. וכמ\"ש בק\"ש אחד ואהבת שתחלה צ\"ל מס\"נ בחי' בטול למסור נפשו באחד ועי\"ז ואהבת בכל לבבך בשני יצריך כו' שהוא ענין אתהפכא כו' וזהו ענין המצה שנצטוו לאכול בשבוע הא' של ספירה וגם קודם ספירה כי מצה בחי' אתכפייא ובטול. כי המצה אין בה התנשאות להיות תופח ועולה וגם אין בה טעם כמו החמץ והא בהא תליא כנודע שמי שאין בו בחי' התנשאות אינו רוצה למצא טעם בעבודתו כו'. וזהו ענין המצה לחם עוני לפני קבלת התור' כמ\"ש ונפשי כעפר לכל תהיה ואח\"כ פתח לבי בתורתך כו' שע\"י נפשי כעפר יוכל להיות אח\"כ בחי' אתהפכא ולהיות פב\"פ."],[120,"והנה בבחי' זו בחינת אתכפייא הוא למעלה מבחי' אתהפכא. כי הגם שאינו מהפך את המדות עדיין מ\"מ הרי הוא בטול מכל וכל. ובאתעדל\"ת זו בבחי' בטול שמסלק א\"ע מכל בבחי' אתכפייא אתעדל\"ע להיות נמשך מבחי' סוכ\"ע בחי' מל' שהוא ג\"כ בחי' הסתלקות עצמותו ומהותו ית' להחיות רוח שפלים ולב נדכאים כו'."],[120,"וזהו בשכמל\"ו. היינו להיות בחי' ברכה והמשכה בבחי' מלכותו לעולם ועד. כי ועד בחילופי אתוון אחד. וארז\"ל כ\"מ שנאמר ועד אין לו הפסק היינו להיות מלך מלך ימלוך עד אין קץ כו'. ובנפש היינו שלא להיות ⟦פט,ד⟧בחי' שינויים תוך התפלה ואחר התפלה כל היום שהשינויים הוא מבחי' וימלך וימת כו'. וזהו ענין תרומה להוי' שהוא בחי' הבטול מלמטה למעלה. (והענין שהמשכה זו להיות בשכמל\"ו הוא ע\"י אתעדל\"ת ג\"כ בבחי' זו שאין לה הפסק דהיינו בחי' קבלת עומ\"ש שענין עול הוא בחי' אתכפייא ובטול רצון שבחינה זו אין לה הפסק כי בחי' זו יוכל להיות בשוה כל היום כולו. היינו שגם אחר התפלה אע\"פ שאינו עוסק בעומק ההתבוננות מ\"מ יוכל להיות בבחי' אתכפייא מצד ההסכם שנשאר אצלו בשעת התפלה. משא\"כ בבחינת אהבה יש שינוי בין שעת התפלה לאחר התפלה כו' ונמצא מעלת בטול רצון ואתכפייא יש לה מעלה יתירה בבחי' זו גם כן והוא מה שאין בה שינויים:) <b>והענין<\/b> הוא כי הנה ידוע דכל השינויים הוא מבחי' שבה\"כ וכמ\"ש בזוה\"ק בענין וימלך וימת כו' דז' מלכין דתהו דמאן דנפיל מדרגיה אקרי מות. וענין נפילה זו שלהם הוא שהיו בבחי' רצוא לבד ולא היה בהם בחי' השוב. ולכן אין קיום לבחי' זו. וכן בנפש האדם צ\"ל בחי' רו\"ש דייקא כמ\"ש ואהבת ואח\"כ ודברת בם בד\"ת כו' כנודע."],[120,"והנה מצד בחי' שבה\"כ הנ\"ל נמשכים כל השינויים ג\"כ באדם שאע\"פ שמתפלל באהבה עכ\"ז אחר התפלה יוכל להיות נמשך ח\"ו אחר תאוות עוה\"ז אלא השמירה לזה היא בחי' השוב ודברת בם ובקיום המצות כו'. אך הנה ידוע דהשבירה היה בז' מדות לבד אבל בבחי' מלכות לא היה כלל שבירה ממש וכמ\"ש בספרא דצניעותא ובפי' האר\"י ז\"ל שם."],[120,"וזהו הענין שבחי' קבלת עומ\"ש שהוא בחי' בטול רצון אין בה שינוי והוא בחי' ועד שאין לה הפסק. וע\"י אתערותא דלתתא בבחי' זו מעורר ג\"כ למעלה להיות בשכמל\"ו דהיינו שיהיה ברכה והמשכה מעצמות א\"ס ב\"ה להיות בחי' שם כבוד מלכותו."],[120,"וכענין המבואר למעלה בפירוש ארוממך אלקי המלך. וזהו ענין תרומה הא' להוי'. הלמ\"ד מורה על ההעלאה ממטה למעלה. והיינו מפני שהמשכת הרוממות ובחי' מלכות ממהותו ועצמותו ית' עם היות שזהו המשכה וירידה מעצמותו להיות סוכ\"ע אך מהות המשכה זו הרי אינה בהתלבשות בהעלמין רק בחי' רוממות והתנשאות עליהם שזהו כעין העלאה ממטה למעלה. לכן נק' המשכה זו בזהר בל' אסתלק יקרא דקוב\"ה כמאמר הידוע כד אתכפייא סט\"א אסתלק יקרא דקוב\"ה בכולהו עלמין."],[120,"ואין זה ענין סילוק האור ממש ח\"ו. דא\"כ מאי מעליותא אלא אדרבה ודאי היא המשכת וגילוי אור א\"ס ב\"ה רק שהוא בחי' גילוי אור הסוכ\"ע שא\"א שיהיה הגילוי בפנימיות בתוך הכלי כ\"א בבחינת רוממות ולכן נק' אסתלק כאלו האור מתגלה רק מעט ומסתלק. ע\"כ נאמר תרומה להוי\"ה שיהי' בבחינת רוממות והתנשאו' והוא המשכת אור הסוכ\"ע ממקורו שהמשכה זו היא כמו העלאה. ועוד שהמשכה זו היא ע\"י אתעדל\"ת שבבחי' העלאה ובטול מלמטה למעלה כנ\"ל. וזהו ענין תרומה האחת שהיא מלמטה למעלה:"],[120,"<b>ואח\"כ<\/b> כתי' כל נדיב לבו יביאה את תרומת הוי'. היא בחי' ההמשכה מלמעלה למטה תרומה ל' הפרשה כנ\"ל. תרי ממאה כו'. היינו להיות נמשך מבחי' הוי' הוא בחי' סוכ\"ע מהווה תמיד כי היו\"ד שבראש מורה על הפעול' כמו ככה יעשה איוב כו' בבחי' הוי' שבחי' ממכ\"ע יו\"ד צמצום כו'."],[120,"והמשכה זו ע\"י נדיבים בחי' האבות שנקראים נדיבים ורועים. כי נדבן הוא בחי' משפיע מטובו לזולתו. וכן הרועה רועה צאנו במרעה טוב ומאכיל ומשקה אותם. וכמ\"ש נדיבי עמים נאספו עם אלקי אברהם כו' להושיבי עם נדיבים עם נדיבי עמו כו' כרוה נדיבי עם שמעשה האבות היה לחפור בארות ויחפור אברהם כו'."],[120,"וכל הבארות אשר חפרו בימי ⟦צ,א⟧אברהם כו' שהבאר הוא בחינת גילוי המים מן ההעלם תוך הארץ שכל מעשיהם היה להביא בחינת סוכ\"ע בחינת העלם בגילוי בחינת ממכ\"ע שזה היה תכלית כל מעשיהם ועבודתם."],[120,"ונק' נדיבי לב כי הקב\"ה נק' בשם לב עד\"מ כמ\"ש צור לבבי כו'. כי הנה הלב מחיה את כל הגוף ע\"י דם הנפש שנסגר בתוכו ואח\"כ נפתח ויוצא לכל האברים שתמיד סוגר ופותח פותח וסוגר כו' שהוא בחי' רצוא ושוב משפיע ומקבל. כך הנה החיות של כל העולמו' היא בדרך רו\"ש כו' והמשכה זו להיות בחי' רו\"ש הוא ע\"י בחי' האבות ולכן נק' נדיבים כי מדתו של אברהם מדת האהבה הלוך ונסוע רצוא ושוב ע\"י זה מעורר למעלה כמים הפנים כו' בבחינת אהבה עליונה."],[120,"ומדתו של יצחק ביראה. ופחד יצחק היה לי ע\"י בחי' יראה כו'. ולכן אומרים אלקי אברהם אלקי יצחק כו' אלקי אצל כאו\"א לפי שמדתו של זה לא כמדתו של זה. וצ\"ל ב' הבחי'. כי שמאלו תחת לראשי וימינו תחבקני. שגם ע\"י בחי' שמאל דוחה גורם נשיאת ראש כו'. וזהו כל נדיב לבו יביאה את תרומת הוי\"ה. היינו המשכת התורה מלמעלה למטה שנק' יין ושמן כו' שהיא בחי' מצה עשירה הנלושה ביין ושמן שאינה באה לידי חמוץ כלל כנ\"ל וד\"ל:"],[121,"⟦צ,א⟧<b>יביאו לבוש מלכות אשר לבש בו המלך וסוס אשר רכב עליו המלך ואשר נתן כתר מלכות בראשו.<\/b> הנה ענין לבוש מלכות הוא ענין מ\"ש ה' מלך גאות לבש שנתלבש בלבוש גאות להיות מלך העולם."],[121,"וסוס אשר רכב עליו המלך הוא ענין מ\"ש במ\"ת כי תרכב על סוסיך מרכבותיך ישועה. ואשר נתן כתר מלכות בראשו הוא ענין מ\"ש בעטרה שעטרה לו אמו ביום חתונתו זה מ\"ת. כי הנה כל הבחי' שנתגלה במ\"ת נתגלה ג\"כ בפורים בימי מרדכי שנא' וקבל היהודים את אשר החלו לעשות כי במ\"ת שאמרו ישראל נעשה ונשמע החלו לעשות שהיה רק התחלה ובימי מרדכי היה גמר הקבלה:"],[121,"<b>וביאור<\/b> הדברים יובן בהקדים לבאר מארז\"ל תכלית חכמה תשובה ומע\"ט שנאמר ראשית חכמה יראת ה' שכל טוב לכל עושיהם ללומדיהם לא נאמ' כו'. והלומד שלא לעשו' נוח לו אלו נהפכה שלייתו על פניו מפני שהעיקר הוא המעשה והיינו במצוה שא\"א לעשות ע\"י אחרים אבל במצוה שאפשר לעשות ע\"י אחרים ארז\"ל ע\"פ וכל חפצים לא ישוו בה אפי' חפצי שמים שכל המצות אינם שוים אפי' לדבר אחד מדברי תורה שיש בחי' מעלה יתירה בדברי תורה על קיום המצות ויש מעלה יתירה בקיום המצות על דברי תורה."],[121,"ונבאר עתה בחי' ומעלה שיש בקיום מצות על ד\"ת ע\"ד מאמר תכלית חכמה כנ\"ל. והלומד שלא לעשות כו'. והענין כי הנה חכמה היא ראשית ההשתלשלות. ובחי' ההשתלשלות היא כשלשלת מהרבה טבעות אחוזות זו בזו. כך החכמה היא בבחינת ההשתלשלות שממנה נשתלשלו המדות."],[121,"והחכמה עצמה מלובשת היא בתוכן והמדות מלובשות במחשבה ומחשבה בדבור ומעשה. ועם היות שהחכמה מאין תמצא והיא בחי' מקור ושרש לכל ההשתלשלות עכ\"ז בהיותה נק' ראשי' הגלוי הרי יש לה שניה ושלישי' שגם הראשונה נמנית מן המנין למנות אחרי' שני' ושלישי' לכן אברהם שהית' מדתו מדת החסד נק' אב\"ר מ\"ה שהוא בבחי' אבר וכלי להתלבשות בחי' חכמה כח מ\"ה שהחכמה עצמה היא המלובשת בתוך המדות ולכן כתיב והחכמה מאין תמצא ולא אין ממש."],[121,"ומשרבע\"ה שהיה בבחי' ונחנו מה דהיינו בבחי' אין ממש אמר כבד פה וכבד לשון אנכי כבד פה לגבי תושבע\"פ וכבד לשון בתושב\"כ שהית' מדרגת נשמתו למעלה מבחי' התורה דאורייתא מחכמ' נפקת שהיא בבחי' ראשית והתלבשות אוא\"ס ב\"ה שבה הוא בבחי' ממכ\"ע כסדר ההשתלשלות שמתלבש בבחינת עלמין בכל עולם לפי מדרגתו. אבל הארת והמשכת אוא\"ס ב\"ה במעש' המצות גשמיות תרומות ומעשרות כו' הוא בבחי' סוכ\"ע שלא בדרך הדרגה והשתלשלו' אלא בדרך דילוג. כמ\"ש קול דודי דופק כו' מדלג על ההרים כו'. לפי שאין ההארה ההיא מלובשת ⟦צ,ב⟧ממש בדברים גשמיים שבהם נעשים המצות כמו החכמה המלובשת במדות ומדות במחשבה כו'. אלא בחי' הארה בעלמא."],[121,"והענין הוא כי אם היתה המשכת אוא\"ס שבתוך עלמין רק בדרך התפשטות והתלבשות בבחי' ממכ\"ע בסדר ההשתלשלות בדרך עילה ועלול לא היו יכולים הנבראי' להיות מאין ליש כלל רק היו בטלים במקורם ושרשן ואפי' התהוות בחי' ח\"ע להיות חכים ולא בחכמה ידיעא מ\"מ מאחר שנק' בשם חכמה הרי הוא בחי' דבר מה עד שעולה בשם בפ\"ע ולא הי' זה אפשר להיות מאוא\"ס ב\"ה שכשמו כן הוא אין לו סוף כנ\"ל רק היתה כלולה במקור' ושרשה כמו התכללו' המדו'בשכל עד\"מ שהרי המדות נולדו ונתהוו משכל המולידן ובודאי היו כלולין בשכל תחלה קודם שנולדו ונתהוו בבחי' מדות מורגשות בפ\"ע אלא שבעודן כלולים בשכל אין עולות בשם מדות כלל אלא אחר שנולדו ונתגלה להיות מדה בפ\"ע."],[121,"וכך בחי' ח\"ע אינה עולה בשם חכמה אלא אחר יציאתה מן ההעלם אל הגילוי ויציאה זו שמההעלם אל הגילוי אינה בבחינת ההשתלשלות אלא החכמה מאין תמצא מבחינת אין ממש דרך מציאה."],[121,"והיינו מהארת בחי' סוכ\"ע ומכ\"ש להיות התהוות מאין ליש גשמיות שאין התהוות הגשמיות מן הרוחניו' דרך השתלשלות עו\"ע לפי שאין ערוך בין רוחניות לגשמיות כלל. כי מה שנפש הבהמות היא נמשך מבחי' פני שור שבמרכב' והעופות מפני נשר."],[121,"ונה\"ב שבאדם כו' היינו בחי' הנפש היא הרוחניות וחיות אבל גוף הגשמי של אדם ובהמה וחיות ועופות לא נתהוו מרוחניות כלל אלא התהוות הגשמי הוא מהארת בחי' א\"ס ב\"ה ממש הסוכ\"ע שהוא ית' כל יכול וקמיה כחשכה כאורה ורוחניות וגשמיות שוין לפניו משם נמשך הארה והמשכה להיות בחי' יש ודבר בהשתלשלות העולמות עד שמתהוה אפי' יש גשמי מחומריות העוה\"ז ואוא\"ס ב\"ה הסוכ\"ע מאיר וממשיך חיות לכולם בשוה בבחי' סובב ומקיף עליהם מלמעלה."],[121,"ולכן נק' הבריאה מאין ליש כי מאחר שלא היה כדרך השתלשלות דרך עו\"ע אלא דרך דלוג הרי אין ההארה ההיא מלובשת ממש בתוך עלמין אלא הארה בעלמא וה\"ז יש מאין ממש."],[121,"ולכן אמרו תכלית חכמה תשובה ומע\"ט כו' כי חכמה היא בבחי' השתלשלות בחי' ממכ\"ע אלא שהיא נמנית ראשונה שהיא ראשי' ומקור לכולם ומ\"מ מאחר שנק' ראשית הוא מן המנין וראוי למנות אחריה שניה ושלישית כו'. משא\"כ תשובה ומע\"ט היא המשכת אוא\"ס ב\"ה הסוכ\"ע."],[121,"והגם שאינו בבחי' גדר כל עלמין ואינו נמשך אלא הארה בעלמא בחי' אין ממש מ\"מ מאחר שהארתה והמשכת' הוא אוא\"ס ב\"ה ממש הסוכ\"ע הרי היא בבחי' ומדרגת יותר נעלה על המשכת אוא\"ס ב\"ה הנמשך בבחי' ההשתלשלות דרך עילה ועלול הוא בחי' ממכ\"ע. רק לא כל המעשים שוים רק ⟦צ,ג⟧מע\"ט דוקא הם דברים שנעשה בהם המצות שהם רצה\"ע ב\"ה להיות צצית של צמר וקלף של תפלין ובהם מאיר אוא\"ס ב\"ה הסוכ\"ע בגלוי ממש בלי שום הסתר פנים ולבוש. משא\"כ שאר כל המעשים אשר לא לה' המה הגם שאוא\"ס ב\"ה הוא הסוכ\"ע ומקיף כל העולמות בהשוואה אחת הוא המהוה היש והעשיה יש מאין מ\"מ יש שם לבוש והסתר פנים המכסה ומסתיר אור ה' וקדושתו ונראים ליש ודבר נפרד בפ\"ע. משא\"כ דברים הנעשים בהם המצות שהם רצונו ית' הרי הם בטלים לאור ה' וקדושתו ואוא\"ס מתגלה בהם בלי הסתר פנים ולבוש. הגם שהן מלובשים בדברים גשמיים. הנה מאחר שיש בהם גלוי אוא\"ס ב\"ה הסוכ\"ע ומקיף את כולם בהשוואה אחת הרי כל מה שלמטה מטה במדרגה יותר ובפרט מדרגה התחתונה שבעשיה גשמית יש בה גלוי יותר מהארת אור א\"ס ב\"ה הסוכ\"ע שמזה נעשה היש כנ\"ל:"],[121,"<b>והנה<\/b> על הארה והמשכה זו שמבחי' סוכ\"ע שאינה אלא הארה בעלמא נאמר ה' מלך גאות לבש. והענין הוא כמאמר יחיד חי העולמים מלך כו'. שהוא ית' יחיד ומיוחד הוא לבדו כמו קודם שנבה\"ע כו'."],[121,"וכמ\"ש אתה ה' לבדך כו'. וזהו ההפרש שבין פי' וביאור מלת אחד לפי' וביאור מלת יחיד. כי מלת אחד מורה על המשכת יחודו ית'. ונמשך בז' רקיעים וארץ וד' רוחות העולם להיות בטלים ונכללים ביחודו העליון ית' בבחי' בטול והתכללות ממש ולא יהי' תופס מקום ויש ודבר נפרד כו'. משא\"כ בחי' יחיד מורה על יחודו ית' האמת ממש טרם שנמשך בעולמות שהוא לבדו הוא ולכך אחר בריאת העולמות אין עוד מלבדו כתיב דכולא קמיה כלא חשיבי ממש אלא שנמשך להיות חי העולמים הוא רק בחי' מלך בחי' מל' מכ\"ע דהיינו כמו המלך המושל במדינה עד\"מ שאין עצמותו ומהותו נתפס ומתפשט במדינה כולה רק שמו לבדו שנק' מלך עליהם וכבוד מלכותו ותפארת גדולתו הוא המתפשט במדינתו מזה מקבלים עול מלכותו וממשלתו עליהם כך המשכה זו שמסוכ\"ע לקיום וחיות והתהוות יש מאין הוא בבחי' התפשטות מלכותו והתנשאותו ית' כי לפי שהוא המלך המרומ' לבדו מאז והמתנשא מימות עולם מזה נמשך חיות והתהוות כל הנבראים ליש מאין דהיינו מבחי' ההתנשאות שהוא הארת אין ממש:"],[121,"<b>וזהו<\/b> כי הוא לבדו מרום וקדוש פועל גבורות כו' למלך אל חי וקיים רם ונשא כו'. וזהו ה' מלך גאות לבש שנתלבש במדת גאות והתנשאות להיות בבחי' מלך על העולם שגאות והתנשאו' זו היא המאירה ומתפשטת להיות העולמות מאין ליש והוא סבת קיום היש גשמי. והוא אף תכון תבל בל תמוט שכדי להיות תבל גשמי נתלבש במדת גאות להמשיך בחינת מלכותו ית' שמזה נמשך קיום היש גשמי כנ\"ל:"],[121,"<b>וזהו<\/b> יביאו לבוש מלכות כו'. הוא בחינת גאות והתנשאות אור א\"ס ב\"ה. ויביאו כתיב שבחי' גאות והתנשאות להמשיך בחי' מלכותו ית' באתעדל\"ת תליא מילתא כי מאחר דכולא קמיה כלא חשיב על מי יהיה שייך ונופל לשון מלוכה אלא היינו מחמת שיומשך ויאיר אור א\"ס ב\"ה הסוכ\"ע בגלוי ממש בדברים הנעשים בהם המצות שהן הן רצונו ית' משם יאיר ויתגלה אוא\"ס ב\"ה ממש בגילוי בלי שום הסתר פנים לבוש להיות הדברים הגשמיים ההם הנתונים תחת ממשלת ק\"נ בטלים לאור ה' וקדושתו הנמשך ומאיר בהם."],[121,"והמשכה זו באתעדל\"ת תליא מילתא כמ\"ש אשר יעשה אתם האדם שהאדם עושה אותן למצות כו' כמ\"ש במ\"א. אך היינו המשכת אוא\"ס ב\"ה בדברים הנעשים בהם המצות כגון ציצית של צמר ותפלין של קלף ואתרוג."],[121,"וכיוצא בהן שהתהוות מאין ליש הגשמי שבהם הוא מאוא\"ס ב\"ה הסוכ\"ע ומקיף ⟦צ,ד⟧כולן בהשוואה אחת. אמנם קיום המצות במעשה האדם אשר יעשה בגופו ומאודו כגון בלבישת הטלית ותפלין ונטילת האתרוג ונתינת הצדקה וכיוצא בהם שהוא המשכת אור וגילוי החיות מאור א\"ס ב\"ה בנפש האדם ממש הגם שהארה והמשכה זו היא ג\"כ בבחי' מקיף מ\"מ אין הארה זו נמשכת מאוא\"ס ב\"ה הסוכ\"ע ומקיף את כולם בהשוואה אחת לבד כי ההארה ההיא היא מבחי' התנשאו' לבד שהוא המתנשא מימות עולם שההתנשאות מצד עצמו הוא בחי' הסתלקו' החיות מאוא\"ס ב\"ה שלא יאיר ויתגלה בגילוי רב ועצום כדי שלא להיות בטול העולמות במציאות ממש. רק אחר שמתנשא מבחי' עלמין כדי להראות מלכותו והתנשאותו על כל העולמו' הרי נמשך גילוי הארת מלכותו והתנשאותו ית' והוא בחי' סוכ\"ע ומקיף את כולם בהשוואה אחת. אבל ההארה הנמשכת על האדם בקיום המצות במעשה בפו\"מ היא בחי' כתר מלכות והוא בחינת בעטרה שעטרה לו אמו וכתר שנעשה על ראש המלך עד\"מ הוא מאבנים טובות שהם בחי' דוממים שהוא מבחי' התחתונה שבד' בחי' דצח\"מ."],[121,"ואעפ\"כ נעשי' עטרה וכתר על הראש להתענג ולהתפאר כו'. וכך בקיום המצות אשר יעשה האדם הגם שהן מלובשים בדברים גשמיים מ\"מ זה נעשה בחי' כתר עטרה למעלה דהיינו בחי' ענג העליון ב\"ה נח\"ר לפני שאמרתי ונעשה רצוני. וענג ונח\"ר זה מתגלים בנפש האדם בעשותה אחת מכל מצות ה' ות\"ת כנגד כולם כי הלכות הן הליכות עולם שהן המשכת אוא\"ס ב\"ה ממש בעולם ואין להקב\"ה בעולמו אלא ד\"א של הלכה:"],[121,"<b>ולכן<\/b> ארז\"ל (בירושל' דמגלה) הנביאים והכתובים עתידים להבטל ומגלת אסתר והלכות אין עתידים ליבטל. והענין מ\"ש הנביאים והכתובים עתידים להבטל אין פי' שיבטלו לגמרי ולא יהיה גלוי הנביאים כלל ח\"ו אלא שיהיה אוא\"ס ב\"ה כ\"כ בגילוי רב ועצום עד שגילוי הנביאים יהיו בטלים כבטול זיו השמש בשמש שעם היות שהזיו ודאי יש לו אור רב במקורו ביתר שאת מהאור המאיר לארץ ולדרים עליה אלא שבמקורו הוא בטל מחמת אור השמש שהוא מקור האור. וכך כל הנביאים עתידים להבטל באור גילוי א\"ס ב\"ה שיתגלה לע\"ל וראו כל כו'."],[121,"והנה ע\"ז אמרו שמגלת אסתר לא תבטל. והענין כי ארז\"ל אסתר מן התורה מנין דכתיב ואנכי הסתר אסתיר פני ביום ההוא שהשכינה מסתתרת בגלות בבחינת ביום ההוא בחי' עלמין סתימין דלא אתגליין. דהנה לע\"ל כתיב ואמר ביום ההוא הנה אלקינו זה קוינו לו שבחי' הוא בחי' סתים יהי' בבחי' זה שהוא בחי' התגלות כאלו הוא לנוכח דהיינו שיאיר אוא\"ס ב\"ה המסתתר והנעלם בבחי' עלמין סתימין להיות בגילוי בעלמין דאתגליין. משא\"כ בחי' אסתר שהוא בחינת הסתר אסתר פני ביום ההוא שאפי' בבחי' ביום ההוא הוא בבחי' הסתר והעלם לפי ששרשה מבחי' סתימו דכל סתימין וע\"ז נאמר אכן אתה אל מסתתר הנה אור כזה גדול מאד ורב כחו שאין לו בטול כמו זיו השמש בשמש שאור זה אינו זיו אלא מאור עצמו."],[121,"וכן הלכות שהן בחי' מרדכי. כי מרדכי מן התורה מנין דכתיב מר דרור ומתרגמינן מירא דכיא כו'. פי' מירא דכיא מרירות שבמקום טהור דהיינו הלכות שהן דבר ה' ושרשן ומקורן בח\"ע המלובשות בבחי' מרירות שהוא גשמיות גסות עוה\"ז וחומריות כתרומות ומעשרות ואפי' בדברים טמאים כגון שקצים ורמשים אשר הבדילנו מהם."],[121,"וע\"ז נאמר ששה חדשים בשמן המור שמן הוא בחי' ח\"ע המלובשת בבחי' מרירות שהן הלכות שמלובשות בגשמיות. ופסוק זה מדבר על ענין ביאת הנשמה לג\"ע שצ\"ל בשמן המור. וכמארז\"ל אשרי מי שבא לכאן ותלמודו בידו."],[121,"ומה שההלכות מלובשות בגשמיות הוא כמשל האבוקה שמאירה ⟦צא,א⟧למרחוק מאד. וכן חבית מלאה שנתמלאה על כל גדותיה בשפע רב ועצום עד שנשפך לחוץ באבוד וכן בחי' ההולדה אינו בקטן עד שיהי' גדול ויכנסו בו מוחין דגדלות."],[121,"ועי\"ז נתוסף בו כח להוליד בדומה לו. כך הנה ההלכות המלובשות בגשמיות היינו שבאו מאור האבוקה המאירה למרחוק ומחבית שנתמלאה על כל גדותיה ושפע רב ועצום עד שנשפך לחוץ. וזהו סימן ברכה בית שנשפך בו יין כמים כו'. ואדרבה מאור וגילוי זה שבגשמיות מובן מקור האור ושרשו שהוא בבחי' האבוקה הגדולה. הגם שאם היה מדליק הנר במקומו היה מאיר יותר מהאור הבא מהאבוקה מרחוק מ\"מ מאחר שמאיר ברחוק מאד מעיד על מקום האור ומקורו שגדול מאד והאבוקה גדולה היא ולכן אור וגילוי זה שבהלכות אין לו בטול כבטול זיו השמש. (וז\"ש ויקחו אליך שמן זית זך כתית למאור שהוא בחי' מאור ולא אור וזיו לבד. וכמארז\"ל מאור שבה מאור דוקא). וכן מגלת אסתר הגם שהנס של פורים היה מלובש בדרך הטבע ע\"פ אחשורוש. הנה אדרבה מזה מובן ששרש האור וגילוי למעלה הוא ממדרגות עליונות מאד וכמשל אור האבוקה וחבית של יין המלאה עד שעוברת ממנה על כל גדותיה לחוץ. לכן כתיב וימי הפורים האלה לא יעברו מתוך היהודים."],[121,"והנה כדי להמשיך אור וגילוי גדול כזה שאין לו בטול בבחי' זיו אמרו ישראל בשעת מ\"ת נעשה ונשמע הוא ענין בטול הרצון לבעל הרצון עצמו שזהו ענין נעשה שהיו מוכנים לעשות טרם ישמעו שהוא בחי' העלאה ובטול רצון ואח\"כ נשמע הוא בחינת המשכת התורה לשמוע. וזהו ענין כתר מלכות כי תרי\"ג מצות דאורייתא וז' מצות דרבנן הן בגימטריא תר\"ך. וזהו תר\"ך עמודי אור שבכתר כמו עמוד המחבר מעלה ומטה. כך המשכת התורה והמצות הן המשכות ממקום עליון מאד מאא\"ס ב\"ה ממש למקום נמוך מאד הוא העוה\"ז השפל הגשמי:"],[121,"<b>אך<\/b> כל הב' בחניות לבוש מלכות וכתר מלכות עדיין צריכין לבחי' סוס אשר רכב עליו המלך. והוא כי הנה כתיב במ\"ת כי תרכב על סוסיך מרכבותיך כו'. והענין הוא כי הנה ארז\"ל ג' שעות ראשונות של יום הקב\"ה יושב וזן כו'. ובלילה רוכב על כרוב קל שלו ושט בח\"י אלף עלמין:"],[121,"<b>וביאור<\/b> הדברים הנה תקנו חז\"ל ח\"י ברכאן דצלותא נגד ח\"י חוליות שבשדרה. ולכאורה אינו מובן. אך הענין הוא דהנה השדרה היא הנמשכת מן המוח אל הירכיים הן סוף המדרגות ולכן בברכה הא' כורע בברוך שהכריעות והשתחואות הן כריעת הראש והוא המשכת בחי' ח\"ע. ואח\"כ בברכה שלאחריו אומרים מודים אנחנו לך בחינת הודאה שהוא מבחינת ירכין."],[121,"והנה הח\"י ברכאן ממשיכים נש\"י ג\"פ ביום. אך המלאכים זמן שירתם היא בלילה שאז ותתן טרף לביתה ואזי נמשכים בחי' הח\"י ברכאן במלאכים ושם מתחלק לח\"י אלף עולמות כי רכב אלקים רבותים אלפי שנאן. אלפי שאינן שב' אלפים חסר מרבותים שהוא ך' אלף. שנשאר ח\"י אלף וכך מתחלק השפע בכל מדרגה ומדרגה לפי השגתה בכל הח\"י אלף מדרגות. והשפעה והמשכה זו היא בבחי' כרוב קל שלו היא בבחי' צירופי אותיות שנק' כך בשם כרוב."],[121,"והנה בתריה דהאי קרא רכב אלקים רבותים כו' כתיב אדני בם סיני בקדש. כלומר שכמו שנמשך שפע וגילוי בצירופי אותיות והמשכות במלאכים. כך נמשך בבחי' סיני בקדש הם צירופי אותיות והמשכות גילוי אא\"ס ממש בתורה ממש שניתנה בהר סיני."],[121,"וגם אחר ירידת משה מן ההר בסוף מ' יום כתיב ועשו לי מקדש ושכנתי בתוכם להיות גילוי שכינה ממש בגשמי' הדברים שנעשה בהם המשכן זהב וכסף ונחשת ויריעות ⟦צא,ב⟧וקרשים כו'. וזהו כי תרכב על סוסיך שהמשכות אלו להיות גילוי רב נק' בשם סוסים שהם צירופי אותיות שנק' כך בשם סוסים. שיש אותיות שנק' בשם סוסים. ויש אותיות שנק' בשם כרוב. כי יש הרבה מיני אותיות. אותיות הדבור ואותיות השכל ואותיות המחשבה ואפי' בקדמות השכל יש בחי' אותיות:"],[121,"<b>וזהו<\/b> ענין וסוס אשר רכב עליו המלך שכדי להיות בחי' גילוי בחי' לבוש מלכות וכתר מלכות צ\"ל ע\"י בחי' סוס שהן בחי' צירופי אותיות והמשכות להמשיך גילוי א\"ס ב\"ה למטה כמו למעלה."],[121,"והנה כל בחי' הללו נתגלו גם בפורים בימי מרדכי שאז קבל היהודים את אשר החלו לעשות במ\"ת שבמ\"ת אמרו נעשה ונשמע שהיה בחי' בטול רצון ובימי מרדכי ואסתר מס\"נ ממש על קדוש השם שהרי המן לא רצה להרוג אלא יהודים. וכמאמר כל הכופר בעכו\"ם נק' יהודי. ולכן נק' מרדכי איש יהודי ואף שהיה משבט בנימין. ואף כהנים ולוים שבאותו הדור נק' בשם יהודים לפי שמס\"נ על קדה\"ש ולא המירו דתם להחיות נפשם ומחמת מס\"נ זו זכה להיות גילוי בחי' לבוש מלכות וכתר מלכות וסוס אשר רכב עליו המלך:"],[121,"<b>אך<\/b> להבין מ\"ש ויקח המן את הלבוש ואת הסוס כו' מאין זכה המן לבחי' הללו. הנה ארז\"ל המן מן התורה מנין דכתיב המן העץ כו'. והענין דכתיב ראשית גוים עמלק שכל העכו\"ם הן מבחי' עה\"ד טו\"ר ועמלק הוא למעלה מהן. וזהו המן העץ בתמיה שהוא למעלה מבחי' העץ. ומ\"מ מאחר דכתיב המן העץ אפי' בלשון תמיה הרי יש לו עכ\"פ קצת שייכות אל העץ. שאל\"כ למה מזכירו אצל העץ. אך הענין שהוא בבחי' מקיף להעץ נוגע ואינו נוגע והוא בחי' חוצפה וגסות הרוח."],[121,"והנה לעומת זה יש בקדושה ונק' ג\"כ בחי' המן לאחר הבירור. כי מבני בניו של המן למדו תורה ברבים. הרי שיש בחי' המן לאחר הבירור שנכלל בקדושה והוא ויגבה לבו בדרכי ה' וכמארז\"ל שצ\"ל עיניו למטה ולבו למעלה. עינים הם בחי' חכמה כח מ\"ה בחי' משה שהיה ענו מכל האדם בחינת בטול."],[121,"ובחי' הלב צ\"ל למעלה ששם יסוד האש והצמאון וטבע האש להגביה ולעלות למעלה. והאדם צ\"ל כלול משניהם. כי אם לא יהיה בבחי' הגבהה כלל לא יערב לבו לגשת אל העבודה באמרו מי אנכי ומה עבודתי. לכך צריך לו הגבהת הלב בתשוקה והצמאון שבו."]]);
